var e={Id_Editor_Unnamed:{en:`Unnamed`,zh:`Unnamed`},Id_Editor_Default:{en:`Default`,zh:`Default`},Id_Editor_AnyLocation:{en:`(Any Location)`,zh:`(Any Location)`},Id_Editor_AnyCharacter:{en:`(Any Character)`,zh:`(Any Character)`},Id_Editor_AnyItem:{en:`(Any Item)`,zh:`(Any Item)`},Id_Editor_AnyEvent:{en:`(Any Event)`,zh:`(Any Event)`},Id_Editor_AnyObject:{en:`(Any Object)`,zh:`(Any Object)`},Id_Editor_None:{en:`(None)`,zh:`(None)`},Id_Scenario_Name:{en:`At the Heart of Power`,zh:`力量核心`},Id_Location_Name_0:{en:`Scotland Yard`,zh:`苏格兰场`},Id_Location_Name_1:{en:`Parliament`,zh:`国会`},Id_Location_Name_2:{en:`Warehouse`,zh:`仓库`},Id_Location_Name_3:{en:`Squat`,zh:`非法占用居所`},Id_Location_Name_4:{en:`Royal Estate`,zh:`皇家花园`},Id_Location_Name_5:{en:`MI5`,zh:`国安局`},Id_Location_Name_6:{en:`Military Barracks`,zh:`军营`},Id_Character_Name_0:{en:`Drake O'Brian`,zh:`德雷克·柯布连`},Id_Character_Name_1:{en:`Chief Officer Doyle`,zh:`戴尔局长`},Id_Character_Name_2:{en:`Louise Blanche`,zh:`露易蕬·布兰奇`},Id_Character_Name_3:{en:`Buck`,zh:`伯克`},Id_Character_Name_4:{en:`Kevin Doyle`,zh:`凯文·代尔`},Id_Character_Name_5:{en:`Roger Gaiman`,zh:`罗杰·盖曼`},Id_Character_Name_6:{en:`Eric Gloomerry`,zh:`艾力·古鲁梅利`},Id_Character_Name_7:{en:`Jeremy King`,zh:`哲礼美·甘`},Id_Character_Name_8:{en:`Harvey Marshall`,zh:`哈维·马绍`},Id_Character_Name_9:{en:`Lou Chin`,zh:`刘紫嫣`},Id_Character_Name_10:{en:`The Duke of Windsor`,zh:`温莎公爵`},Id_Character_Name_11:{en:`Johanna Clarke`,zh:`约翰娜·克拉克`},Id_Character_Name_12:{en:`The Prince`,zh:`王子`},Id_Character_Name_13:{en:`Colonel Trooper`,zh:`翠普上校`},Id_Character_Name_14:{en:`Conor McVeill`,zh:`科拿·麦威尔`},Id_Character_Name_15:{en:`Dolores Kelly`,zh:`桃乐丽思·凯莉`},Id_Character_Name_16:{en:`Mike Sanders`,zh:`迈克·桑德斯`},Id_Scenario_Description:{en:`More dangerous than ever, the M Organization is preparing to strike. Will you manage to stop them in time? `,zh:`M组织打算主动出击，形势万分危险。究竟你能否及时制止他们？ `},Id_Scenario_SameLocationDefaultMessage:{en:`Focus detectives, you are already here.`,zh:`集中精神，你已在这里。`},Id_Scenario_UnusedScanCodeMessage:{en:`Your leads are too random, detectives. You should focus on the case.`,zh:`侦探，你的行动太茫然了。专注在案件疑点吧。`},Id_Scenario_ClosedLocationDefaultMessage:{en:`The neighborhood is large, and without an exact address it will be difficult for you to find what you are looking for.`,zh:`这社区太大了，要是没有确切地址，你很难找到想要找的地方。`},Id_Scenario_Introduction:{en:`You had an appointment this Thursday at 10 am, an unlikely appointment in the MI5 offices at Southbank <loc=O>. It seems that your investigations caught the attention of the nation's powerful domestic intelligence agency.@ Conor McVeill <char=36>, the young director who's been at the head of the agency for nearly four years, wants to meet you. You arrived on time but now it feels like you've been waiting for ages in front of his personal secretary's <char=18> desk.@ You watch her screening appointments and calls without paying any attention to you. @ At last, she turns to you and tells you with disdain that Director McVeill <char=36> is expecting you. She motions to the door with her eyes and invites you to go in and talk to him.`,zh:`国安局约了你星期四早上十点会面，至今你也没想到竟然会来到国安局的南区办公室<loc=O>。看来你的调查引起了国内最高情报机关的注意。@年轻的局长科拿·麦威尔<char=36>从四年前开始接管这部门，如今他想跟你见面。尽管你准时到达，但是来到局长的私人秘书<char=18>桌前之后，等候的时间却度日如年。@你看到她扫视所有约见的时间表，不断接听、拨出电话，对你视若无睹。@最后终于转向你，蔑视地告诉你麦威尔局长<char=36>等著见你，然后眼神望向门口，示意你自己进去跟局长谈话。`},Id_LocationState_Introduction_0:{en:`In the absence of the Chief Officer <char=33>, the atmosphere feels strange around Scotland Yard today. Scott Clover <char=43> is running all over the Yard to handle emergencies, and it seems he wants to talk to you. `,zh:`局长<char=33>今天不在局内，所以苏格兰场今天气氛怪异。史葛·葛洛佛<char=43>在局内四处奔走，处理要紧事务，而看来他想跟你聊一下。 `},Id_Character_Name_17:{en:`Cynthia Callum`,zh:`辛西雅·卡琳`},Id_Character_Name_18:{en:`Carol Stern`,zh:`嘉璐·施坦`},Id_Location_Name_7:{en:`Goldman and Associates`,zh:`戈德曼旗下集团`},Id_Item_Name_0:{en:`M Organization`,zh:`M组织`},Id_DisplayTextPerState_0:{en:`I suppose you know why I summoned you here today? You have solved your little investigation: well done! Are you pleased with yourself?@ You have just destroyed Agent O'Brian's <char=49> years of working undercover to dismantle the M Organization <itm=02>. They are planning to execute a major operation in 2 days, and due to you, we had to recall our best asset!@ So allow me to make a simple request: kindly return to your daily trivialities and desist from sticking your nose in the business of your betters. Doing otherwise will not end well for you.`,zh:`我想你很清楚为什么今天我叫你来吧。你刚解决了个小案件，做得真好！很高兴对吗？@柯布连探员<char=49>多年以来揭露并瓦解M组织<itm=02>的努力，就因为你毁于一旦。原本他们两天之后有一个重大行动，多亏你，我们只好召回最优秀的同僚！@我对你只有一个简单请求：专注在你琐碎的日常案件，不要强出头，到处惹是生非，对你可没有好处。`},Id_DisplayTextPerState_1:{en:`I'm told you have solved several cases related to the M Organization <itm=02>. @ We know they are planning to execute a major operation in two days, and we are convinced we can stop it from happening.@ To that end, I will require you to stop interfering with this case. The stakes are too large for you and for our agent. Worse, you might derail our counteroffensive.`,zh:`听说你解决了好几宗有关M组织<itm=02>的案件。@我们得悉他们在两天之后有一个重大行动，而我们很有信心制止他们。@长话短说，我要求你不要再干涉这案件，对你对我们的同僚来说，风险都太大，最怕的是我们精心部署因你而泡汤。`},Id_DisplayTextPerState_2:{en:`I'm told you have solved several cases related to the M Organization <itm=02>. @ We know they are planning to execute a major operation in two days. To that end, I will require you to stop interfering with this case, lest you derail our counteroffensive. We have an agent who will be able to manage without you.`,zh:`听说你解决了好几宗有关M组织<itm=02>的案件。@我们得悉他们在两天之后有一个重大行动，而我们很有信心制止他们。@长话短说，我要求你不要再干涉这案件，以免我们精心部署因你而泡汤。我们的同僚胜任有余，不用你操心。`},Id_DisplayTextPerState_3:{en:`Director McVeill <char=36> is expecting you. He is not a patient man. You shouldn't keep him waiting.`,zh:`麦威尔局长<char=36>要见你。他耐性不好，不要让他等你。`},Id_DisplayTextPerState_4:{en:`This organization has influence in finance, politics, and even the justice system. All this is way beyond you. Leave it to the professionals.`,zh:`这组织足以摇动财政、政治、甚至司法制度。这些都远超你的能力，请留给专业人士。`},Id_DisplayTextPerState_5:{en:`Why are you talking to me about this person? Even if he was connected to the M Organization <itm=02>, I wouldn't tell you anything. I told you to cease your investigation!`,zh:`你跟我说这人干嘛？即使他跟M组织<itm=02>有关联，我也不会告诉你任何事情。你必须停止调查！`},Id_DisplayTextPerState_6:{en:`I wasn't yet heading this service when Drake started working undercover in the M Organization <itm=02>. He was our best chance of dismantling them, and you mucked up everything!`,zh:`德雷克开始潜入M组织<itm=02>时，我还没有掌管这部门。他本来可以大大有助我们瓦解那组织，就给你一手摧毁了。`},Id_DisplayTextPerState_7:{en:`Ah, you figured it out. Clever. Thank you for not compromising his cover. He was already undercover in the M Organization <itm=02> before I rose to the head of this agency. He is the asset in the best position to dismantle them.`,zh:`啊，你搞懂了，真聪明。谢谢你没有揭露他的身份。我当上这部门的局长前，他已经潜入了M组织<itm=02>，如今他在绝佳的位置，帮助我们瓦解这组织。`},Id_DisplayText_Action_0:{en:`You receive a call from the Chief Officer's wife: "I need your help! I haven't heard from Stanley <char=33> since yesterday and he's not answering his phone <itm=03>.@ He's looking for our son <char=47> who's been missing for a week, and I'm at my end! I know Stanley had every confidence in you--please help me."`,zh:`你接到局长妻子的电话：「请你帮帮我！昨天以来史丹利<char=33>就音信全无，打电话给他<itm=03>也不接。@他本来去找失踪了一个星期的儿子<char=47>，但我已经束手无策！我知道史丹利非常信任你，所以请帮帮我。」`},Id_Item_Name_1:{en:`Chief Officer's phone`,zh:`局长的电话`},Id_DisplayTextPerState_10:{en:`It's been nearly 10 years since I was asked to go undercover into the M Organization. I earned their trust as an informant for them. I didn't get my hands dirty, but I circulated information. For example, I played a role in the kidnapping of the French ambassador's <char=15> daughter.`,zh:`大约十年前，我受命潜入M组织，担任联络人博取了他们的信任。我没有直接弄脏双手，不过负责传递消息。例如我在法国大使<char=15>女儿绑架案里有所涉足。`},Id_DisplayTextPerState_11:{en:`Well done. You completely blew my cover! I have to wonder if you work for the M Organization <itm=02>. But I guess I don't really have a choice and I have to ask for your help. @ In 2 days, the organization is going to strike a major blow. My best lead to stop them was Gaiman <char=35>. Now that he's dead, I'm left with Mike Sanders <char=23>, a soldier who was hired by Gaiman. @ Colonel Trooper <char=24> confirmed that Sanders is back in his barracks <loc=J>. Go. Interrogate him, find out what he knows, and we might still be able to stop the M Organization.`,zh:`干得好哇！你完全揭露了我的身份！我甚至怀疑过你是不是为M组织<itm=02>效力，不过事到如今，我别无办法，只有找你帮忙。@两天之后他们会有大动作，原本我倚赖盖曼<char=35>来阻止他们，但他如今死了，只得转向盖曼雇用的士兵迈克·桑德斯<char=23>。@翠普上校<char=24>核实了，桑德斯现在回到他的军营里<loc=J>。去盘问他，找出他知道什么，然后也许我们就能阻止M组织。`},Id_DisplayTextPerState_12:{en:`There has to be a reason why he tried to take you off the case. I'm convinced he's involved too. Maybe you'll be able to get useful information from him.`,zh:`他有理由把你调离这案件。我确信他也牵涉其中，也许你可以从他身上获得有用的资讯。`},Id_DisplayTextPerState_13:{en:`Louise Blanche <char=15>, the French ambassador, connected to them after her daughter <char=14> had a transplant. I'm the one who informed them that Buck <char=44> had kidnapped her, and they were interested in getting her back. @ I know she had gone to France. She is only coming back tomorrow, but maybe she knows something. I will pass the message that you need to talk to her.`,zh:`自从她的女儿接受心脏移植手术以后，法国大使露易蕬·布兰奇<char=15>跟那组织便有联系。就是我告诉他们伯克<char=44>绑架了她女儿，而M组织打算夺回她。@我知道她去了法国，明天才回来，不过也许她知道一些事情。如果你有事问她，告诉我，我会帮你转达。`},Id_DisplayTextPerState_14:{en:`Don't waste your time with that piece of trash. He's just collateral damage, and doesn't know anything useful.`,zh:`不要在这垃圾身上浪费时间，他无足轻重，不知道任何事情。`},Id_DisplayText_Default_0:{en:`I don't know who this is. Should I know him?`,zh:`我不认识这人。我该认识吗？`},Id_DisplayText_Default_1:{en:`Are you sure this is connected to the case? Because it's really not ringing any bells.`,zh:`你确定他跟本案有关？因为我毫无头绪。`},Id_DisplayText_Default_2:{en:`No, I don't think I know this person.`,zh:`我不认识这人。`},Id_DisplayTextPerState_15:{en:`Your Chief Officer's son is missing? Maybe they're putting pressure on him. That's the kind of thing they do. And it could perhaps explain Gaiman's death <char=35>.`,zh:`局长的儿子失踪？也许是组织向他施压，这是他们常用手段，也许可以解释盖曼<char=35>之死。`},Id_DisplayTextPerState_16:{en:`A prominent member of the M Organization <itm=02>. There's so much he could have revealed, maybe he even knew the name of their leader. @He hung himself while he was in custody at Scotland Yard. Very convenient for anyone who didn't want us to interrogate him.`,zh:`M组织<itm=02>的重要成员。原本他可以吐露很多事情，甚至知道首领的名字。@他在苏格兰场里被拘留期间上吊自杀，这手法用来杀人灭口非常方便。`},Id_DisplayTextPerState_17:{en:`Of course I've heard of him. He's an important political figure. Very visible lately, since he submitted legislation to strengthen the judicial system's power to fight terrorism.@ He would even like to reform MI5, which he deems unsuited to our society. I can confirm any guess you have that my director <char=36> doesn't like him very much.`,zh:`像他这样重要的政治人物，我当然听说过他。最近他向立法机关呈交了一条法案，建议加强司法制度的权力以对抗恐怖主义，使他更加备受瞩目。@他甚至认为我们不适合现今社会，打算改革国安局。我可以告诉你，我的局长<char=36>并不怎么喜欢他。`},Id_DisplayTextPerState_18:{en:`A brilliant woman who has done an awful lot of good for this country, but I wonder if she has enough of an iron fist.`,zh:`卓越的女性，对这国家贡献超凡，但我不知道她拳头够不够硬。`},Id_DisplayTextPerState_19:{en:`You've been contacted by the Prince? Seriously? I knew the case was alarming, but I didn't know it was that bad. You have to find out who is leading the M Organization <itm=02> at all costs. `,zh:`王子联络过你？没说笑？我知道这案件令人担忧，但还没糟到这个地步。你要尽最大努力找出M组织<itm=02>的首领。 `},Id_DisplayTextPerState_20:{en:`That's a man I have known for a long time and for whom I have a lot of respect. But I've also wondered if he could work for the M Organization <itm=02>, or even if he could be their leader.`,zh:`我认识他好多年了，一直都非常尊敬他，不过同时怀疑他是不是为M组织<itm=02>工作，甚至是首领。`},Id_DisplayTextPerState_21:{en:`I've had little to do with him. I was already undercover when he arrived so I never met him in person. I have to admit I don't like him much. @ He often left me to my own devices on important matters, and didn't use information I passed along that had seemed vital to me. I sometimes wonder if he isn't undermining my investigation.`,zh:`我跟他很少接触，因为他接任局长时，我已开始当卧底，所以跟他没见过面。我必须承认我不怎么喜欢他。@他常常丢我在重要事情上独力作战，而且不把我的机要情报当一回事。有时候我觉得他妨碍我调查。`},Id_DisplayTextPerState_22:{en:`He was in the same regiment as Gaiman <char=35>. I think they were already doing business at the time, but Gaiman covered for him so he wouldn't be kicked out. @ Since then they've kept working together and I am convinced he is a member of the M Organization <itm=02>. There's a reason why he was the one who was sent to Ireland to collect his package.`,zh:`他跟盖曼<char=35>同属一个军团，我猜他们当时已经一同做事，不过事发之后盖曼独力承担，保护了他不用被除籍。@自那之后他们继续合作，我确信他是M组织<itm=02>的一员，因此他被派往爱尔兰收拾他的行囊。`},Id_DisplayTextPerState_23:{en:`That's Director McVeill's <char=36> secretary, a brilliant woman. I never understood why she settled for this position. In any case, he's not the first director she's worked with, and he's certainly not going to be the last one.`,zh:`她是麦威尔局长<char=36>的秘书，很优秀的女人，我至今还弄不清楚为什么她留在这位置。麦威尔不是她第一位服务的局长，而且一定不会是最后一任。`},Id_DisplayTextPerState_24:{en:`She seems to be an Irish woman who roams the terrorist circles. She's quite discreet and we have no interesting information about her.`,zh:`她看上去像是游走于恐怖分子的爱尔兰女性，行事隐秘。关于她，我们没有多少值得留意的资料。`},Id_DisplayTextPerState_25:{en:`You want me to locate the Chief Officer's phone? That's a little unorthodox. The funny thing is, just yesterday he asked me to locate his son's <char=47> phone. You think they ran into trouble? @ ...Well, just like with his son, it's not working. They must have network problems where they are--or a jammer. So I won't be able to help you. ...though here--here's a recording of the last call from the Chief Officer's son <itm=12> @ He's not saying much, but maybe it will give you a lead.`,zh:`你想我找出局长电话的位置？这有点不正规，但是有趣的是，昨天局长也要我找出他儿子<char=47>电话的位置。你觉得他们陷进麻烦了吗？@……结果跟他的儿子一样，找不到。他们所在位置有连线问题，也许是干扰，所以我帮不了你……但是你看一看这里，这里记录了局长的儿子最后一次来电<itm=12>。@他没有说多少话，不过也许能给你一些头绪。`},Id_Item_Name_2:{en:`Audio Recording`,zh:`录音`},Id_Item_Name_3:{en:`Detonator & Explosives`,zh:`雷管和炸药`},Id_DisplayTextPerState_26:{en:`While I was trying to locate him, Kevin <char=47> called the Chief Officer <char=33> to tell him that he was fine and he shouldn't go after him. It was a bit weird and probably doesn't help much, but you never know.`,zh:`我尝试锁定他的位置时，凯文<char=47>打电话给局长<char=33>，告诉爸爸自己很好，不用爸爸来找。这聼起来很奇怪，也许帮不上忙，但谁说得准？`},Id_DisplayTextPerState_27:{en:`Well, that's not my field at all. And to be honest I'm not very comfortable about this. Are you sure it's not going to blow up? You can't be too careful.`,zh:`这完全不是我的专长，而且坦白说，这个在我身边我觉得很危险。你肯定它不会爆炸吗？请你务必小心。`},Id_DisplayText_Default_3:{en:`Sorry, but I really don't find anything useful for you.`,zh:`抱歉，我找不到任何有用资讯。`},Id_DisplayText_Default_4:{en:`You know, the Internet is not magic, and I really don't see how I could help you there.`,zh:`请你理解网路并非万能，我不晓得怎样帮你。`},Id_DisplayText_Default_5:{en:`You might think that I am paid to just faff around on the Internet but sorry, I don't see how I could help you there.`,zh:`也许你以为我只是拿著薪水在网上闲逛，其实并没有。这事情我帮不了你。`},Id_DisplayTextPerState_28:{en:`I don't know if it has anything to do with your investigations, but people are starting to talk openly about that group. Mostly on nationalist or extremist forums. I have the feeling they are planning something big, and I hope we'll be ready for it.`,zh:`我不知道这跟你的调查有什么关系，但是网路上的人们开始公开谈及这组织。大部分都是在国族主义或极端分子的论坛上。我感觉它要干大事，而希望我们已经准备好应对。`},Id_DisplayTextPerState_29:{en:`The Chief Officer came to see me yesterday, wanted me to help locate his son. He told me the boy had run away but it didn't seem to be that simple. I don't know if the recording <itm=12> was helpful, but I hope he found Kevin <char=47>. `,zh:`局长昨天来请我锁定他儿子的位置。他告诉我儿子出走了，但事情没那么简单。我不知道这段录音<itm=12>有没有用，不过希望这可以帮助他找到凯文<char=47>。 `},Id_DisplayTextPerState_30:{en:`I never met the Chief Officer's son. I know he's a very smart boy and the Chief is having a bit of a time with him.`,zh:`我从未见过局长的儿子，听说他很聪明，与局长之间相处不怎么好。`},Id_DisplayTextPerState_31:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_32:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_33:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_34:{en:`Hello, detective, how is your investigation going? Can I analyze something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_35:{en:`Hello, detective, how is your investigation going? Can I analyze something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_36:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_37:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_38:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_39:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_40:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_41:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_42:{en:`Hello, detective, how is your investigation going? Can I analyze something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_43:{en:`Hello, detective, how is your investigation going? Can I analyze something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_44:{en:`You never know what's going on in people's mind. How can I help you, detective?`,zh:`你永远弄不清人心。要帮忙吗？`},Id_DisplayTextPerState_45:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way.`,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。`},Id_DisplayTextPerState_46:{en:`How can I help you, detective? My keyboard is itching!
`,zh:`要帮忙吗？我正摩拳擦掌！
`},Id_DisplayTextPerState_47:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_48:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_49:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_50:{en:`Hello, detective, how is your investigation going? Can I analyse something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_51:{en:`Hello, detective, how is your investigation going? Can I analyse something to help you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_52:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_53:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way.`,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。`},Id_DisplayTextPerState_54:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_55:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_56:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_57:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_58:{en:`Hello, detective. How is your investigation going? Can I analyze something for you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_59:{en:`Hello, detective. How is your investigation going? Can I analyze something for you?`,zh:`嗨，侦探，调查顺利吗？有物件需要分析吗？`},Id_DisplayTextPerState_60:{en:`You never know what's going on in people's heads. How can I help you, detective? `,zh:`你永远弄不清人心。要帮忙吗？ `},Id_DisplayTextPerState_61:{en:`A new body for me, detective? Let's see if I can get it to talk in my own way. `,zh:`有新的尸体要分析吗？看看我能不能从中找出任何线索吧。 `},Id_DisplayTextPerState_62:{en:`How can I help you, detective? My keyboard is itching!`,zh:`要帮忙吗？我正摩拳擦掌！`},Id_DisplayTextPerState_63:{en:`You're saying the phone can't be located anymore? Maybe that's a clue: if he's still in London, there aren't that many dead zones-- but we still need more information.`,zh:`你说锁定不到电话的位置？也许这本身就是线索——伦敦城中没多少死角。不过我们需要更多资讯。`},Id_DisplayTextPerState_64:{en:`That's not much to go by. I have the feeling I can hear something in the background but I can't identify it. Pity. It could be a useful clue.`,zh:`这里面没多少情报。我感觉能从背景听得出一些声音，但不能确认是什么。可惜，那原本可以作为线索。`},Id_DisplayTextPerState_65:{en:`Well of course, I recognize that sound, it's the siren of the Wormwood factory. Hmmm...a remote location where mobile coverage is miserable and this sound can be heard... It may be worth searching the warehouses close to Dockland <loc=P>. `,zh:`当然，我认得出那声音，是苦艾工场汽笛声。嗯……讯号差、偏僻、能听到这声音的地方……我建议你搜查一下码头区的仓库<loc=P>。 `},Id_DisplayTextPerState_66:{en:`You think he could have been kidnapped by the M Organization to blackmail the Chief Officer <char=33>? That may well be, but we would need a better lead and I am not sure it will help us to derail what they are planning.`,zh:`你觉得他被M组织绑架，用来威胁局长<char=33>吗？也许是，但我们需要更有用的资料。这能否帮助我们破获该组织谋划的事情呢？`},Id_DisplayTextPerState_67:{en:`This sound is familiar. Gaiman <char=35> had shown me a warehouse he owned in the Dockland area <loc=P>. You should start looking there.`,zh:`这声音听起来很熟悉。盖曼<char=35>给我看过他在码头区拥有的一幢仓库 <loc=P>。也许你该到那里看一下。`},Id_DisplayTextPerState_68:{en:`Strange, but I have to confess I already didn't trust your Chief Officer. The M Organization <itm=02> has a way of acquiring the services of influential people.`,zh:`奇怪了，不过我胆敢说我开始不信任你们的局长。M组织<itm=02>有办法拉拢位高权重的人。`},Id_DisplayText_Default_6:{en:`Sorry but the analysis was inconclusive.`,zh:`抱歉，但分析得不出明显结果。`},Id_DisplayText_Default_7:{en:`Although I like to consider all possibilities, I don't see how this clue could move your investigation forward.`,zh:`尽管我不想遗漏任何可能，但看不出这线索跟你的调查有什么关系。`},Id_DisplayTextPerState_69:{en:`This subject is coming up quite a bit with you. A bit of a pet cause, perhaps.`,zh:`这组织跟你如影随形，是你锲而不舍吗？`},Id_DisplayTextPerState_70:{en:`The Chief Officer is missing? Bugger! Do you think it has anything to do with his son <char=47> running away?@ He had asked me to analyze a recording  <itm=12> to help him. I managed to extract this sound that can be heard in the distance. It sounds like a siren. I don't know if it helped him in his investigation, but it may be something to go on.`,zh:`局长失踪了？蠢蛋！你认为这跟他儿子<char=47>出走有关吗？@局长来找过我帮忙分析一段录音<itm=12>，所以我抽出了这个远处都听得见的声响，似乎是汽笛声。不清楚这对他的调查有没帮助，不过事情似乎不对劲。`},Id_DisplayTextPerState_72:{en:`Yes, the Chief Officer already asked me to analyze this recording, and I managed to extract this siren sound that can be heard in the distance. I don't know if it helped him, or if someone managed to recognize it.`,zh:`对，局长找我分析这段录音，我便抽出了这个远处都听得见的声响。不知道对他有没帮助，又或者有没有人知道那是什么声响。`},Id_LocationState_Introduction_1:{en:`You arrive in an old abandoned warehouse. In the distance you hear the siren of the Wormwood factory. Your phone is having trouble picking up a signal, so it seems you might be in the right place.`,zh:`你来到老旧的废弃仓库，远处听到苦艾工厂的汽笛声，手机讯号断断续续，看来你来对了地方。`},Id_LocationState_Introduction_2:{en:`The barracks are a modern and rather impressive place, accommodating about a thousand men. When you identify yourself to the soldier on duty at the entrance, he tells you that Colonel Trooper <char=24> would like to speak to you. @He also lets you know that Private Sanders <char=23> is in his quarters.`,zh:`军营是一处很现代化美观的地方，住著大约一千人。你向门口当值士兵表明身份，对方告诉你翠普上校<char=24>要见你。@他还告诉你桑德斯一等兵<char=23>在自己的住所里。`},Id_DisplayText_Default_8:{en:`I really don't know who you're talking about.`,zh:`我真不知道有什么可跟你说。`},Id_DisplayText_Default_9:{en:`I'm not going to tell you how to do your job, but nothing ever came of throwing names around on the off chance you might get a response.`,zh:`我并不希望指导你工作，不过随便抛出人名，并不能获得任何资讯。`},Id_DisplayText_Default_10:{en:`This person doesn't serve under my command, and I don't think I ever met them.`,zh:`这人不属我指挥，我也没见过他。`},Id_DisplayTextPerState_73:{en:`I worked with this agent years ago, on an espionage case among my troops. His scar came from that sordid affair. @ But he left me with the memory of a trustworthy man devoted to his country, and that's why I'll help you with your investigation in any way I can.`,zh:`很多年前我跟这特务一起工作过，那是我队中一宗间谍案。他的伤疤就是那时候留下的。@尽管之后他离开了，我至今敬重他是条可信的汉子，为国赴汤蹈火，因此我现在愿意尽一切努力帮助你查案。`},Id_DisplayTextPerState_74:{en:`I haven't had the honor of meeting your superior officer.`,zh:`我还未有幸与你的局长见面。`},Id_DisplayTextPerState_75:{en:`The French ambassador. I followed the case about her daughter in the papers. To be frank, I don't respect her much.@ Her government has expressed its opposition to several English military decisions, and she was a strong voice for her country. She's created difficulties for me several times. @ I was surprised to see, however, that she supported the Duke of Windsor <char=27> in his proposal for reorganizing our justice department, which is going to be introduced in the House of Lords this Saturday.`,zh:`她是法国大使，我在报上读过她女儿的案件。老实说，我不怎么尊敬她。@法国政府公开反对过几次英国的军事决定，她的意见尤其举足轻重，更好几次令我举步维艰。@不过我很惊讶她竟然支持温莎公爵<char=27>重组司法机关的建议。这条法案本周六会呈交上议院。`},Id_DisplayTextPerState_76:{en:`It's an old story I only heard about when I interrogated Private Sanders <char=23>, who was charged as an accessory in that case. @ Gaiman was very much involved in trafficking, including illegal operations. We dismissed him without pay to avoid the scandal, while Sanders was cleared due to lack of evidence.`,zh:`我盘问桑德斯一等兵<char=23>时才听说这个旧案，他当时被起诉作为本案帮凶。@盖曼包揽了这起偷运案许多步骤，包括违法手术。当时我们没有给他付退伍金，以免酿成丑闻，而桑德斯一等兵由于证据不足，判为无罪。`},Id_DisplayTextPerState_77:{en:`I never had the opportunity to meet him but I've heard much about the Duke. I approve of his ideas. Times have changed, and our justice system is unsuited for an age of terrorists. The reform he proposes may well be a good thing.`,zh:`我无缘亲觐公爵，不过大名早已如雷贯耳。我非常认同他的想法，时代变了，而我们的司法制度不足以应付今天的恐怖分子时代。他提出的改革可以大大改良制度。`},Id_DisplayTextPerState_78:{en:`A competent woman, but she might not be aware of the new challenges our society is facing. It's the time for a strong hand. It's war.`,zh:`优秀的女人，但未必察觉如今社会的新难题。我们需要强而有力的领导，如今这局势形同战争。`},Id_DisplayTextPerState_79:{en:`Like everyone, I respect our Prince greatly. I feel he has a more contemporary vision of the country than our dear Queen ever had. His engagement ceremony will improve the morale in the country.`,zh:`我跟每个人一样十分崇敬王子。我感觉他有亲爱的女王所不具备的前瞻视野。他的订婚典礼可以振兴全国的民心。`},Id_DisplayTextPerState_80:{en:`I am Colonel Karl Trooper. I have over 30 years of military experience, and I like things to go to plan. I know nearly everything that happens in those barracks, so don't hesitate to ask me questions, as long as you are not disturbing the peace.`,zh:`我是卡尔·翠普上校，从军超过三十年，喜欢事情按计划发展。我知道这座军营里发生的近乎每一件事情，所以随便问问题吧。只要你不打扰这里的安宁，我都会帮助你。`},Id_DisplayTextPerState_81:{en:`The sneak. He's not as young as he looks. Don't like him.@I don't know how he secured such a prestigious position, but I wouldn't be surprised if he turned out to be a fraud. The less I have to work with his services, the happier I am.`,zh:`这个老油条，他并没有外表那么年轻。好好提防他。@我不晓得他怎样爬到这个高位，不过要是最终发现他原来是个骗子我也不会惊讶。我非常乐意少接触他，越少越好。`},Id_DisplayTextPerState_82:{en:`Are you joking? How do you expect me to know such a person?`,zh:`你说笑吗？我怎么会认识这人？`},Id_DisplayTextPerState_83:{en:`Private Sanders is an efficient man, but I have reasons to doubt his loyalty. He went on leave last week with Private Stern <char=22>, if I understood correctly.@ I was informed that he came back rather hastily in the middle of the night.`,zh:`桑德斯一等兵办事俐落，但我怀疑他不怎么忠诚。要是我没记错，上星期他跟施坦一等兵<char=22>一同休假。@之后我接到报告说他当晚深夜匆忙地回来了。`},Id_DisplayTextPerState_84:{en:`Conor McVeill's <char=36> secretary. I already talked to her on the phone, but I don't really know her.`,zh:`科拿·麦威尔<char=36>的秘书。跟她通过电话，不过说不上认识她。`},Id_DisplayTextPerState_85:{en:`A good soldier, highly motivated. I'm surprised to see her hanging out with someone like Sanders <char=23>. She's a smart girl, usually tends to avoid problems.`,zh:`一名好士兵，意志坚定，所以很惊讶她跟桑德斯<char=23>这样的人一起出外。她是聪明的女孩，通常懂得怎样避开麻烦。`},Id_DisplayText_Default_11:{en:`You know, at my level of responsibility, you don't overload yourself with certain details.`,zh:`须知在我这岗位不可以在意太多细节，以免负担过重。`},Id_DisplayText_Default_12:{en:`Try to focus on the questions that really matter for your case, as I don't have much time to talk to you.`,zh:`集中在真正有用的事情，我没时间跟你浪费。`},Id_DisplayText_Default_13:{en:`No, I don't know. Do you have other questions?`,zh:`我不知道。还有问题吗？`},Id_DisplayTextPerState_86:{en:`You think Sanders <char=23> is connected to this case? That's quite worrying, I didn't think this organization had one foot in the army. @ I heard a few rumors--they seem to be very influential and deeply rooted in many circles. Their name comes up often in extremist and reactionary groups. `,zh:`你觉得桑德斯<char=23>跟此案有关？真令人担心，我本来以为这组织没有渗透进军队里。@我听过一些谣言，说这组织在多个圈子根深蒂固且举足轻重。通常在极端分子或反动组织当中听到这组织的名字。 `},Id_DisplayTextPerState_87:{en:`I don't think I ever heard that sound, but that's not really my field.`,zh:`我不认为我听过这声音，但说不准。`},Id_DisplayTextPerState_88:{en:`And why would this discussion have anything to do with me?`,zh:`为什么跟我有关？`},Id_DisplayTextPerState_89:{en:`Indeed, we have all the supplies required to make bombs in our stores. But you can imagine that we secure such things with the utmost vigilance. What would people think of the army if such dangerous things could leak out?`,zh:`当然我们有完备的材料，供应我们制造炸弹。不过你想想也知道要万分谨慎处理，不然一个不小心给这些危险的东西流出去，公众对军队会有什么印象呢？`},Id_DisplayTextPerState_90:{en:`Drake <char=49> told me you would come. I'll be happy to help you, however I can.`,zh:`德雷克<char=49>告诉过我你会来，所以我会尽力帮你。`},Id_DisplayTextPerState_91:{en:`The police ? What's the problem? I'm just back from spending a few days in Ireland with a friend, Private Stern <char=22>, I haven't done anything wrong. You can ask her--she's in the barracks.`,zh:`警方？有啥事？我刚刚从爱尔兰休假回来，施坦一等兵<char=22>跟我一起，我可没做坏事。她也在营中，你可以去问她。`},Id_DisplayTextPerState_92:{en:`I'm Private Stern. What can I do for you?`,zh:`我是施坦一等兵。有何贵干？`},Id_Item_Name_4:{en:`Drugs`,zh:`药物`},Id_DisplayTextPerState_93:{en:`The name is familiar. If I'm not mistaken, she benefited from a rehabilitation program we offered some small dealers, to drop the charges against them if they joined the Army. @You won't find any trace of it on her record-- the goal was to allow young people to get off the street and accomplish some good with their life. If you talk to her about drugs <cat=08>, she might be more cooperative.`,zh:`这名字很耳熟。要是我没记错，她曾参与我们举办的更生计划，帮助犯过轻微贩毒罪的人洗脱罪名，换取他们从军。@你不会在她的纪录找到这件事，因为计划目的就是让他们改过自新，重新做人。如果你跟她谈起药物<cat=08>，她应该会乖乖合作。`},Id_DisplayTextPerState_94:{en:`Private Sanders invited me to go to Ireland and stay in a bed & breakfast for four days. But we had a deep disagreement yesterday and he decided to come back hastily. I have nothing more to say.`,zh:`桑德斯一等兵邀请我到爱尔兰，一同度假四天，不过昨天我们有严重争执，令他决定立即匆忙回来。没有其它补充了。`},Id_DisplayTextPerState_95:{en:`My name is Private Carol Stern. I joined the Army more than three years ago. I have a chance to serve my country, and I'm doing the best I can.`,zh:`我是嘉璐·施坦一等兵，从军超过三年，为国效力是我志愿，能为此上山下海。`},Id_DisplayTextPerState_96:{en:`I'm not proud of it but I did sell some drugs to survive. I don't touch that stuff anymore, though. If I was caught selling again, my military career would be compromised and that's not an option.`,zh:`这不是引以为傲的事情。以前我当过一个小毒贩以谋生，但现在已经没再碰毒品了。要是再被抓到贩毒，我的军旅生涯也就此完结，这可不是我想要的。`},Id_DisplayTextPerState_97:{en:`A rather discreet woman. I'm not finding much information about her. Her record is surprisingly empty. Kind of strange, really. If you uncover something, it will probably be interesting.`,zh:`比较隐秘的女性，我找不到多少资料，她的纪录空白得出人意表。实在不寻常，要是你能揭开什么一定很有趣。`},Id_DisplayTextPerState_98:{en:`Why are you talking to me about this? Did Sanders say something?`,zh:`你为什么跟我谈起这事情？桑德斯说了什么？`},Id_DisplayTextPerState_99:{en:`Roger Gaiman? That's an old story, I've been cleared since then. It has been proven that I had nothing to do with all that skulduggery... Or rather, it has not been proven otherwise.`,zh:`罗杰·盖曼？那是旧事了，而我获证明清白。证据显示我跟那些阴谋无关……或者这么说，没有证据显示我跟那事有关。`},Id_DisplayTextPerState_100:{en:`A tough but fair boss. I can't complain about him.`,zh:`严明的上司。我没有不满。`},Id_DisplayTextPerState_101:{en:`Yeah, I liked her. So I offered her to spend four days in Ireland at a bed & breakfast with me. But yesterday she got all in a twist so I decided it was time to go home. You know how it is with chicks!`,zh:`对，我对她有好感，所以邀请她一同到爱尔兰一家提供早餐的饭店旅游。不过昨天她心情突然转差，所以我决定回家。妹子就是这样。`},Id_DisplayTextPerState_102:{en:`That's right. I was lucky I could join a rehabilitation program for small dealers. That opportunity probably saved my life and I'm doing my best every day to give back to my country.`,zh:`对，我很幸运，得以参加为小毒贩开设的更生计划，自此拯救了我的人生。如今我每天都全力以赴，回馈国家。`},Id_DisplayTextPerState_103:{en:`A brilliant man with a real vision. He's tough, but I know that with a superior like him, I have the opportunity to build a real career.`,zh:`理念清晰，出类拔萃。尽管严格，但跟从这上司足以让我发挥自己，建立充实的生活。`},Id_DisplayTextPerState_104:{en:`That's the girl Sanders <char=23> fetched in Ireland. I got the sense she didn't quite agree with it, but I guess he had a way to blackmail her too. 
I heard her mention a squat in Whitechapel <loc=I>.`,zh:`她是桑德斯<char=23>拐来的女孩。我感觉她并不怎么认同桑德斯，我猜是被勒索吧。

她还提起过白教堂一处非法占用居所<loc=I>。`},Id_DisplayText_Default_14:{en:`Sorry detectives, I don't meet many people outside barracks.`,zh:`抱歉，我没有见过多少军营外的人。`},Id_DisplayText_Default_15:{en:`I don't think I know this person, sorry. Are they a civilian?`,zh:`我不认识这人。是平民吗？`},Id_DisplayText_Default_16:{en:`You'll have to ask someone else. I don't think I know this person.`,zh:`去问别人吧，我不认识这人。`},Id_DisplayTextPerState_106:{en:`I might have seen Private Sanders <char=23> talk to him a few days ago.`,zh:`几天前我见过他跟桑德斯一等兵<char=23>聊天。`},Id_DisplayTextPerState_107:{en:`I don't want any of this rubbish in my house. If one of my soldiers was caught using drugs, they would be drummed out immediately.`,zh:`我的屋里不需要这种垃圾。要是我手下有人吸毒，立即就把他轰出去。`},Id_DisplayTextPerState_108:{en:`Well, I don't touch this stuff. They tried to get me involved when Gaiman <char=35> was charged with trafficking, but nothing was proven. But, well, some people should be careful--the Colonel <char=24> doesn't go easy on drug addicts.`,zh:`我可不碰这东西。盖曼<char=35>著手偷运时，他们尝试让我掺一脚，不过没证据显示我有份。不过，某些人要小心——上校<char=24>对瘾君子严惩不贷。`},Id_DisplayTextPerState_109:{en:`No, it doesn't mean anything to me. Am I supposed to have heard of this somewhere?`,zh:`这对我毫无意义。我应该在哪里聼过吗？`},Id_DisplayTextPerState_110:{en:`It's a detonator, isn't it? I have seen some during my training but I don't know how it works.`,zh:`这是雷管吧。训练时见过，但不清楚原理。`},Id_DisplayTextPerState_111:{en:`Why would you want me to know about that thing?`,zh:`为什么问我这种事情呢？`},Id_DisplayText_Default_17:{en:`I don't mind helping you, but please stop asking about everything and anything.`,zh:`我不介意帮助你，但不要把有的没的都来问我。`},Id_DisplayText_Default_18:{en:`Is it really your job to ask those kind of questions?`,zh:`你的工作要问这种问题吗？`},Id_DisplayText_Default_19:{en:`Well, unless you have a real question, I'd say we can leave it at that.`,zh:`如果你的问题都是捕风捉影，那么请你停止吧。`},Id_DisplayTextPerState_112:{en:`That bastard. I should never have trusted him. He found a bit of weed in my stuff--for personal use, I swear. But the colonel is very strict about it and I don't want to lose my position. @Sanders <char=23> said he would keep it quiet if I travelled with him for a few days without saying anything. I should have guessed it would be the worst idea in the world to say yes...`,zh:`那浑蛋，我真不该相信他的。他在我的物品里发现一丁点大麻，我发誓那只是自己用的。不过上校决不宽待毒品，而我不希望毁掉事业。@桑德斯<char=23>说要是我跟他一起旅行几天，他就会守秘密。我当时应该知道千不该万不该，就是不该答应他……`},Id_DisplayTextPerState_113:{en:`I should have guessed that bastard wouldn't keep his mouth shut. Even when he probably has a lot more to lose than I do. You know what he did during our so-called 'romantic getaway'? First, he fetched that Punk <char=19> in Ireland. @ She looked about as thrilled as I was to give him a hand. Then they locked themselves in a warehouse <loc=P> while I had to stay in a seedy hotel to cover for him. Finally, last night he came back to pick me up in a panic. @ He threatened to report me to the colonel again if I didn't confirm his 'bed & breakfast' alibi.`,zh:`我早应该醒悟那浑蛋不会守秘密，即使因此比我失去更多也不会罢休的。你知道在我们那趟「浪漫假期」他做了什么？首先，他在爱尔兰诱拐了庞克<char=19>。@当时她看起来惊恐万分，以为我也要跟桑德斯一同对她不利。然后他们进了一幢仓库<loc=P>，锁上了门，我就在破旧的酒店里为他把风。最后，昨晚他整个人不知所措地回来。@他威胁说假使我不配合他「浪漫假期」的口供，就会向上校告发我。`},Id_DisplayTextPerState_114:{en:`Yes, Sanders <char=23> and he were talking in front of a warehouse <loc=P>, I don't know where they met, but for sure, they know each other.`,zh:`对，桑德斯<char=23>跟他在仓库<loc=P>前说话。不知道他们在那里见过面，但肯定早已认识。`},Id_DisplayTextPerState_115:{en:`Never heard of that person`,zh:`没听过这人。`},Id_DisplayTextPerState_116:{en:`I believe I heard Sanders <char=23> say his name. Whatever he was up to, it was for him.`,zh:`我听到桑德斯<char=23>提起过这名字。那是他自己的事情。`},Id_DisplayTextPerState_117:{en:`Like everyone else, I know who the Prime Minister is. Count me pleased it's a woman for a change, but I don't have much to say about her policies.`,zh:`跟大家一样，我也不例外。我很欣慰能够有位女性上场改变政局，但对她的政治主张没多少意见。`},Id_DisplayTextPerState_118:{en:`Lots of talk about him in our circles. His legislative proposal could radically change the way we work, the whole institution even. I'm not sure what to think about it.`,zh:`我们的圈子里很多人谈起他。他提出的新法案会翻天覆地改变我们的工作，甚至整个机关。我不知道怎样看待这事。`},Id_DisplayTextPerState_119:{en:`Oh, the Prince. I heard he was going to get married soon. Lucky girl.`,zh:`噢！王子。听说他快结婚。那女生真幸运。`},Id_DisplayTextPerState_120:{en:`I swear to you, I stopped doing that stuff. All I want now is to serve my country. But it's hard to get rid of bad habits, and I still smoke some weed when things are bad.@ That son of a bitch Sanders <char=23> took advantage of it. I was stupid--I should have reported him right away. Now I can't even imagine what he got me into.`,zh:`我发誓已经没再干那行了。现在我全心服务国家，但习惯不是那么容易戒掉，所以当心情不好，还是偶尔会抽一点大麻。@那浑蛋桑德斯<char=23>用这个要胁我。我也够笨的——当时就应该直接举报他，现在他要怎样对待我，已经不堪设想。`},Id_DisplayText_Default_20:{en:`I don't see what I could tell you about this.`,zh:`我不知道为什么你跟我说起这个。`},Id_DisplayText_Default_21:{en:`I don't think I can tell you much you don't already know.`,zh:`我能告诉你的，都是你已经知道的。`},Id_DisplayTextPerState_121:{en:`I've heard the name, but only as part of some rumors. Some rather reactionary and drunk soldier who suggests that the world will be a better place with the M Organization. I have to admit I always thought it was crackers.`,zh:`我听过这名字，但都是传闻而已。有些反动势力或喝醉的士兵说M组织令世界更美好。不得不说，我心底认为它们只是狂人。`},Id_DisplayTextPerState_122:{en:`I did a defusal course once. You can pick up a few fun tricks in the army.`,zh:`我试过拆弹一次。你能在军中学到一些有趣的技能。`},Id_DisplayTextPerState_123:{en:`Yeah, I think I've heard of that, but I wouldn't be able to tell you where.`,zh:`对，我听过这声音，但说不出在哪里。`},Id_DisplayTextPerState_124:{en:`Yes, I recognize that sound. It could be heard quite clearly around the warehouse <loc=P> where Sanders <char=23> hid for the whole week.`,zh:`对，我认得这声响。桑德斯<char=23>藏身整个星期的仓库<loc=P>能清楚听到这声响。`},Id_DisplayTextPerState_125:{en:`I'm supposed to know him?`,zh:`我应该认识他吗？`},Id_DisplayTextPerState_126:{en:`Yeah, Gaiman <char=35> had talked to me about that bloke. He didn't trust him and was wondering if he wasn't a cop.`,zh:`对，盖曼<char=35>跟我提起过这人，并不相信他，怀疑他是警察。`},Id_DisplayTextPerState_127:{en:`I rarely have anything to do with the Police, you know.`,zh:`我很少接触警察。`},Id_DisplayTextPerState_128:{en:`What, he's dead? Bugger! His kid had asked me to let his father believe I had kidnapped him. I thought it was a joke! I didn't think it would end like this...`,zh:`什么？他死了？那家伙！他的儿子想要我让他相信，他儿子被我绑架了。我以为只是开玩笑！怎料到会变这样……`},Id_DisplayTextPerState_129:{en:`Yeah, I guess the evidence is piling up. Maybe we can work something out? You have questions, I have answers...we should be able to plead self-defense?`,zh:`对，我们发掘到越来越多证据。也许能由此找出一些事情？你有问题，我有答案……也许我们可以辩称自卫？`},Id_DisplayTextPerState_130:{en:`The French ambassador? I'm not really into politics, you know.`,zh:`法国大使？我不理政治的。`},Id_DisplayTextPerState_131:{en:`I don't really have the details, but yeah, she has a role to play in what's coming.`,zh:`虽然我不清楚细节，不过对于将要发生的事情，她绝对有份。`},Id_DisplayTextPerState_132:{en:`You see me hanging out with that kind of bloke?`,zh:`你见过我跟那种小鬼一起混吗？`},Id_DisplayTextPerState_133:{en:`This little moron had problems with his father. I tried to help him but I didn't think it would end like this.`,zh:`那小鬼跟父亲处不好，我尝试帮助他，但是没想到最后会这样收场。`},Id_DisplayTextPerState_134:{en:`This little moron was in full rebellion against his father, and it wasn't too hard to recruit him by making him think he was going to change the world. I have no idea where he may be now. @ He must have run away with Dolores <char=19>. I think the boy is in love.`,zh:`那小鬼正值叛逆期，全力反抗他父亲，所以很容易就引导他自以为能改变世界。我不知道他现在在哪里。@大概跟桃乐丽思<char=19>一起逃走了，我觉得他爱上了她。`},Id_DisplayTextPerState_135:{en:`Dolores Kelly aka "Kaboom", a legendary IRA activist. She made her first bomb when she was 12. At 14, she was sentenced to 5 years in a young offenders center. Since then she's either been sticking to the rules.. or she's been more careful. @Some people even say that she managed to hack a few databases so she could disappear. If you meet her, I'd like an autograph!`,zh:`桃乐丽思·凯莉，代号「爆炸狂」，是爱尔兰共和军的传奇成员。她十二岁开始制造炸弹，十四岁被判监禁五年，进了少年囚犯中心。自此她行事更循规蹈矩，或者说更小心翼翼。@有些人还说她有办法骇进某些资料库，消灭自己出没的证据。要是你见到她，最好弄一张她的照片给我看。`},Id_DisplayTextPerState_136:{en:`No need to ask if MI5 went through here... There is absolutely no data about her online. A real ghost.`,zh:`不需要问国安局有没有动过手脚……网上完全没有她的资讯。完全是幽灵一般。`},Id_DisplayText_Default_22:{en:`Yeah, who is that? I'm supposed to know him?`,zh:`嗯？这人是谁？我应该认识？`},Id_DisplayText_Default_23:{en:`I'm not trying to get rid of you, but if all your questions are that useful, I think we're wasting our time talking together.`,zh:`不是我想随便打发你，不过要是你只问一些没用的问题，那么就不要浪费时间了。`},Id_DisplayText_Default_24:{en:`Don't mind making an effort, but unless I come up with something to please you, I don't know who this person is.`,zh:`我绝不介意帮忙，不过你问的人我毫无头绪。`},Id_Item_Name_6:{en:`Food leftovers`,zh:`吃剩的食物`},Id_Item_Name_7:{en:`Folding beds`,zh:`折床`},Id_Item_Name_8:{en:`A broken computer`,zh:`烂电脑`},Id_Item_Name_9:{en:`Camping furniture`,zh:`营地家具`},Id_DisplayText_Default_25:{en:`This person doesn't seem to be here.`,zh:`看来人不在这。`},Id_DisplayTextPerState_137:{en:`The Chief Officer's lifeless body is lying on the cold floor of the warehouse.`,zh:`局长的尸体躺在仓库冰冷的地板上。`},Id_DisplayText_Default_26:{en:`You don't find anything that looks like this here.`,zh:`在这里找不到这东西。`},Id_DisplayText_Default_27:{en:`Look harder, detectives. There is nothing of the sort here.`,zh:`这里没这东西，再用心找找。`},Id_DisplayTextPerState_138:{en:`You find what looks like the explosive material needed to create a BOMB! <itm=11>`,zh:`你找到看似可以引发爆炸的材料，可以用来制造炸弹<itm=11>！`},Id_Item_Name_10:{en:`Ammunition boxes`,zh:`弹药箱`},Id_DisplayTextPerState_139:{en:`Camping tables and chairs, a rudimentary facility.`,zh:`营地桌椅，非常简陋。`},Id_DisplayTextPerState_140:{en:`A computer with a display that was intentionally smashed.`,zh:`一台电脑，萤幕被蓄意砸烂。`},Id_DisplayTextPerState_141:{en:`Camping beds that look like they have been used over the last few days.`,zh:`营地的床，看来几天前有人用过。`},Id_DisplayTextPerState_142:{en:`Among the tools, you notice a very distinctive screwdriver.`,zh:`在不少工具当中，你找到一个非常独特的螺丝起子。`},Id_Item_Name_5:{en:`A strange screwdriver`,zh:`奇怪的螺丝起子`},Id_Item_Name_11:{en:`The Chief Officer's blood`,zh:`局长的血`},Id_DisplayTextPerState_143:{en:`Varied food leftovers and disposable dishes, enough for three people.`,zh:`很多种类的食物，还有免洗盘子。分量够三人食用。`},Id_DisplayTextPerState_144:{en:`The Chief Officer bled out on the floor.`,zh:`局长在地上流血致死。`},Id_DisplayTextPerState_145:{en:`Ammunition boxes, most of them empty.`,zh:`弹药箱，大部分都是空的。`},Id_DisplayTextPerState_146:{en:`Ah yes, we're dealing with another winner who thinks that it's enough to break the screen if you want to destroy a computer... @Well, I didn't find much that would be useful, but while searching the drive, I managed to restore a file from MI5 about the Duke of Windsor <char=27>. Not quite what I was expecting.`,zh:`呀，又有一些聪明人，以为打碎萤幕就能摧毁电脑……@好吧，我没在硬碟找到有用的资讯，不过从中拼出一个国安局关于温莎公爵<char=27>的档案。确实始料未及。`},Id_Item_Name_12:{en:`File from MI5 about the Duke`,zh:`国安局关于公爵的档案`},Id_DisplayTextPerState_147:{en:`I am not a DIY expert, but this screwdriver is clearly intended for a very specific use.`,zh:`我不是DIY专家，不过这螺丝起子明显有特别用途。`},Id_DisplayTextPerState_148:{en:`They clearly got their supplies in local restaurants, that won't help you very much. On the other hand, it is making me hungry.`,zh:`看得出他们从当地餐厅买食物回来，这情报对你没帮助。另一方面，看到这些让我肚子饿。`},Id_DisplayTextPerState_149:{en:`I don't know what to say... I hope you'll find who did it.`,zh:`我不知道该说什么……希望你找出凶手。`},Id_DisplayTextPerState_150:{en:`No ammunition theft was reported, yet these boxes belong to the British Army.`,zh:`没有弹药失窃报告，不过箱子属于英国陆军。`},Id_DisplayTextPerState_151:{en:`It's the first time I've seen this kind of file. Based on the final evaluation, it looks like Conor McVeill <char=36> doesn't really appreciate the Duke of Windsor <char=27>. @ You should talk to the Duke about it--after all, he may be the target of these terrorists. You'll probably find him at the House of Lords in Westminster <loc=A>.`,zh:`我第一次见到这档案。以结论来看，科拿·麦威尔<char=36>并不欣赏温莎公爵<char=27>。@你应该跟公爵谈一下——说到底，他可能是恐怖分子的目标。你可以到西敏的上议院 <loc=A>找他。`},Id_DisplayTextPerState_152:{en:`This is an autopsy I would've rather never performed. But if I can help to find his murderer, I'll do everything I can. The Chief Officer died by a gunshot to the heart. Here is the bullet <itm=15>. I hope it will be useful.`,zh:`我由衷希望不用为他验尸，不过要是有助找出凶手，我绝对愿意帮你。局长被人朝心脏开枪丧生，子弹<itm=15>在这里，希望这用得着。`},Id_Item_Name_13:{en:`Fatal bullet`,zh:`致命子弹`},Id_DisplayText_Default_28:{en:`If you don't bring me a body, I won't be able to help you.`,zh:`你不是带来尸体我就帮不上忙。`},Id_DisplayText_Default_29:{en:`You know, dead people are more of my specialty.`,zh:`记得死人是我专长吗？`},Id_DisplayText_Default_30:{en:`Sorry detective, I am only a forensic doctor.`,zh:`抱歉，我只是鉴识医生。`},Id_DisplayText_Default_31:{en:`If it's never been alive, I won't be able to help you.`,zh:`恐怕我对死物帮不上忙。`},Id_DisplayText_Default_32:{en:`Do you know we have experts for that kind of thing?`,zh:`你知道我们有专家负责这些吗？`},Id_DisplayText_Default_33:{en:`I really like you, but if you just want to chat, let's do that outside working hours.`,zh:`我不讨厌你，不过闲聊留待下班之后吧。`},Id_DisplayTextPerState_153:{en:`Detonators and explosives to make bombs, professional equipment. I managed to extract a fingerprint <itm=07>.`,zh:`用来制造炸弹的雷管和炸药。专业的人制造。我找到指纹<itm=07>。`},Id_Item_Name_14:{en:`Fingerprint`,zh:`指纹`},Id_DisplayTextPerState_154:{en:`An attempt was made to wipe them away, but we found Mike Sanders' <char=23> fingerprints on the computer. Other than that, nothing useful. You should show it to the IT department.`,zh:`有人尝试摧毁它，但我在上面发现迈克·桑德斯<char=23>的指纹。此外就没有用得着的资讯了。你应该给电脑部看一下。`},Id_DisplayTextPerState_155:{en:`This kind of screwdriver is used to assemble or disassemble bomb mechanisms <itm=11>. This tool is rarely used and makes the bombs much more difficult to defuse.`,zh:`这螺丝起子只用来装嵌或拆卸炸弹装置<itm=11>。这工具很少用得着，让炸弹更难拆除。`},Id_DisplayTextPerState_156:{en:`We found explosive residue in the boxes. There can be little doubt that bombs have been made in this warehouse.`,zh:`箱子里发现残留炸药。毋庸置疑，有人在这仓库里制造过炸弹。`},Id_DisplayTextPerState_157:{en:`We managed to find the origin of the projectile. It comes from the ammunition stockpile of the British Army. I don't have access to their files, but the round is definitively identified. Maybe they'll agree to cooperate in the investigation. `,zh:`我们找出了这发子弹的来历，是来自英国陆军的弹药库存。我没有办法调阅他们的档案，不过证据确凿。也许他们会同意协助调查。 `},Id_DisplayTextPerState_158:{en:`Ask your suspects for their fingerprints and I will compare them.`,zh:`向嫌疑犯索取指纹，我就能比对。`},Id_DisplayText_Default_34:{en:`You know, I'm not very comfortable with people. But if you have objects to analyze, then I am the woman you need!`,zh:`你要知道，我不习惯跟人相处。但如果是分析物件，尽管找我！`},Id_DisplayTextPerState_159:{en:`He was the one who hired me. He was like a father to me. I hope you'll catch whoever did this!`,zh:`是他聘请我的，如同父亲一样照顾我，希望你找出凶手！`},Id_DisplayTextPerState_160:{en:`He was a bit tense the last time I saw him. His son is making his life miserable, if I understood correctly.@ He asked me to analyze an audio file <itm=12>. I cleaned it up, and a factory siren can be heard, but I couldn't identify the location where the recording was made.`,zh:`上次跟他见面时，他整个人很紧绷。据我所知，是儿子令他不顺心。@他请我帮忙分析一段音讯<itm=12>，我照著做，发现了一座工厂的汽笛声，但不知道究竟在哪里录下的。`},Id_DisplayText_Default_35:{en:`I can try and analyze all the clues you need, but for the suspects, you'll really have to ask my colleagues.`,zh:`我会尝试分析你搜集到的线索，不过有关嫌疑犯的事情请去问同僚。`},Id_DisplayText_Default_37:{en:`In this specific case, I don't really know what to advise you.`,zh:`我不晓得这事情有什么可以告诉你。`},Id_DisplayText_Default_38:{en:`Have you tried to show this to an expert? Because I don't have a clue.`,zh:`这我不懂。问过专家了吗？`},Id_DisplayTextPerState_161:{en:`It's a hell of a lead you're chasing down. I heard rumors about that organization, but they're covering their tracks quite well. They seem to have influence at the highest levels of power. You should remain cautious.`,zh:`你正追寻危险无比的邪恶组织。我听说过它的传言，不过实际上他们很擅长消灭证据，更似乎有力左右高层决策，你必须万分谨慎。`},Id_DisplayTextPerState_162:{en:`It looks like we should be concerned about bombing attacks. There are potential targets all over the place. On Saturday, I count at least three major targets: @ First, there's the Prince's <char=29> engagement ceremony, which will take place in Greenwich <loc=M>. It's a big event for the whole country.@ Then, there's the vote on the Duke of Windsor's <char=27> proposed legislation, at the Parliament in Westminster <loc=A>. His proposal has been talked about a lot and deals precisely with the matter of terrorism. @Lastly, there is the opening of Eli Goldman's  <char=39> financial fair at the City <loc=B>. All the country's major financial professionals will be there. We will never have enough men to cover everything. We need more information.`,zh:`看来我们必须提防炸弹恐攻。到处都是潜在的袭击目标。我能举出星期六可能受袭的三个目标：首先是王子<char=29>的订婚典礼，在格林威治<loc=M>举行。这是攸关全国的重大事情。@其次是温莎公爵<char=27>提出法案的投票，在西敏国会大楼<loc=A>举行。他的议案正正针对恐怖主义。@最后，艾利·戈德曼<char=39>在市中心<loc=B>举办的财经展览开幕仪式。每处都集合了全国的政商要人，而我们的人手不足以顾全三地，急需更多资料分析。`},Id_Character_Name_19:{en:`Eli Goldman`,zh:`艾利·戈德曼`},Id_DisplayTextPerState_163:{en:`If they have that information, we can suppose it's their target. But it's worrying that they managed to get a folder from MI5, because it means they have moles inside the agency.`,zh:`要是他们有这份资料，我们大概可以锁定其目标。但是到底他们怎样取得国安局的档案？也许是部门里面有内鬼。`},Id_DisplayText_Default_39:{en:`I don't have much to tell you about that suspect.`,zh:`关于这嫌疑犯我没有什么有用的情报。`},Id_DisplayTextPerState_164:{en:`I guess he blames you for ruining his investigation, but you are probably his best chance of completing it now.`,zh:`看来他责怪你摧毁了整个调查，不过如今你是最大的破案希望。`},Id_DisplayTextPerState_165:{en:`Why didn't he trust us? He might still be alive.`,zh:`为什么他不相信我们？或许他就能保命。`},Id_DisplayTextPerState_166:{en:`He is a competent policeman. He had some family issues last time I spoke with him, I am convinced he is fine.`,zh:`他是尽责的警官，上次跟他聊天，知道他家里有点问题，但我确信他安然无恙。`},Id_DisplayTextPerState_167:{en:`Kevin may well have come into conflict with his father. He must still be devastated if he found out he died. `,zh:`尽管凯文跟父亲始终没有和解，不过我深信他得知父亲死讯，一定会受重创。 `},Id_DisplayTextPerState_168:{en:`Kevin is a rebellious child, but he's a good kid. He has a rather dark vision of the future and that's what always pushed him into conflict with the Chief Officer. He sees his father as the active agent of an outdated world.`,zh:`凯文性格叛逆，但心地善良。他对未来有许多负面想法，认为父亲只是在一个过气的世代中活跃，因此常常跟局长对著干。`},Id_DisplayTextPerState_169:{en:`Considering her past and her relationships, if she is hiding in London, you should go and have a look in Whitechapel <loc=I>. Some friends of hers have a squat over there.`,zh:`考虑到她的过去和人际关系，她在伦敦的藏身处应该是白教堂<loc=I>。你可以到那里搜索一下，她一些朋友在那里有一处非法占用居所。`},Id_Item_Name_15:{en:`Day`,zh:`第{0}日`},Id_DisplayText_Default_40:{en:`Are you sure this person is relevant to your investigation? I don't see what more could be said apart from what you already know.`,zh:`你确定这人跟本案有关吗？我知道的也就是你知道的，没有额外资料可以告诉你。`},Id_LocationState_Introduction_3:{en:`When you arrive at Parliament, you catch sight of the Duke of Windsor <char=27> in the hallway. He is in the middle of a heated discussion with the Prime Minister <char=21>, and their tone of voice isn't really friendly.`,zh:`你来到国会大楼，在走廊看到温莎公爵<char=27>。他正跟首相<char=21>吵得面红耳赤，气氛似乎并不友善。`},Id_DisplayTextPerState_170:{en:`You think my life could be threatened? That wouldn't be surprising--in fact, that's why I want to reform the justice system. We aren't safe in our own country anymore.`,zh:`你认为有人要取我命？稀松平常。正因如此，我立意改革司法制度，不然在国土上也不安全。`},Id_DisplayText_Action_1:{en:`6pm. It is imperative that you go back to Scotland Yard as soon as possible. Crisis meetings are scheduled and your presence is mandatory.@ This will mean the end of your investigation day, but orders are orders, and without the Chief Officer to protect you, you put your career at risk if you don't follow them. So hurry back to Scotland Yard.`,zh:`下午六点。你被命令立即回到苏格兰场，必须出席危机应变会议。@这表示今天的调查必须结束。失去了局长庇荫，要是你不跟从，也许就连工作也丢了。所以快回去苏格兰场。`},Id_LocationState_Introduction_4:{en:`You get inside what is probably one of the largest squats in London: A former hotel where disparate crowds of dropouts coexist. You soon run into Dolores Kelly <char=19> and Kevin Doyle <char=47> in a bedroom.`,zh:`你进入了或许是伦敦最大的非法侵占住处，原本是一座酒店，现在住满了从社会竞争被挤掉的人。你马上跑到桃乐丽思·凯莉<char=19>和凯文·代尔<char=47>的房间。`},Id_DisplayTextPerState_171:{en:`Great, now Dad's sending his cops. Told him I wouldn't go home.`,zh:`棒极了，爸爸终于派警察来。告诉他我不会回家。`},Id_DisplayTextPerState_172:{en:`Thought my hideout was better than that, but well, I guess I have nothing better to do than answer your questions now.`,zh:`我还以为藏身够隐秘，不过算了，看来现在我惟有回答你的问题。`},Id_DisplayText_Default_41:{en:`There are a lot of people in this squat, but this is not really the kind of person who would hang out here.`,zh:`这幢建筑里面有很多人，但是肯定找不到这人。`},Id_DisplayText_Default_42:{en:`You can search the whole building, but you won't find this person.`,zh:`你搜索了整幢建筑，也找不到这人。`},Id_DisplayText_Default_43:{en:`This person is not at Scotland Yard.`,zh:`这人不在苏格兰场。`},Id_DisplayText_Default_44:{en:`You thought you saw this person at Scotland Yard, but that's not the case. Probably the strain of the investigation.`,zh:`你以为这人在苏格兰场，不过并不是。也许调查为你带来太大压力。`},Id_DisplayText_Default_45:{en:`You don't find this person in the Houses of Parliament.`,zh:`你在国会大楼找不到这人。`},Id_DisplayText_Default_46:{en:`Don't know who this is and don't care.`,zh:`这是谁也与我无关。`},Id_DisplayText_Default_47:{en:`Seriously, how much longer are you going to bother me with your questions?`,zh:`老实说，你还要用这些蠢问题浪费我多少时间。`},Id_DisplayText_Default_48:{en:`Never saw that face.`,zh:`没见过这人。`},Id_DisplayTextPerState_173:{en:`He showed up at the warehouse yesterday. He wanted to get Kev' <char=47> back. Mike <char=23> got upset and there were shots fired. Thought to meself it was the moment to clear off and Kev' came with me.`,zh:`他昨天来到仓库，想要回小凯<char=47>。迈克<char=23>不耐烦，还开了枪。我觉得该开溜，而小凯跟著我来。`},Id_DisplayTextPerState_174:{en:`What an arsehole, that one. He came to get me in Ireland for a job. He made it clear that he knew something about me and I'd better follow him without a fight. I'd like to know where he got his information... @ Anyways, I soon realised that he wasn't just going to ask me to make bombs, he mostly wanted to make sure I would take the blame. He had clearly planned to leave just enough evidence to trace it back to me, and to kill me. @I think Kev' <char=47> was also on his kill list, and he saw the tide turning, just like I did. We jumped at the first chance, and this is no sexual metaphor, even though we haven't been bored since yesterday.`,zh:`那杂种。他来到爱尔兰找我帮他做事，挑明他手上有我的把柄，所以最好乖乖听话。我真想知道他是怎样到手的……@无论如何，我很快就发现他不但要我制造炸弹，还暗算我做替死鬼。让我的每一步都留下足够证据将我入罪，最终还要杀死我。@看来小凯<char=47>也是他下毒手的目标，而小凯跟我一样看得出势头不对。我们一抓到机会就溜走，而昨天以来我俩还挺自在的。`},Id_DisplayTextPerState_175:{en:`Yeah, that's the chick that was with Mike <char=23>. She looked about as chuffed as I was to put up with him. I haven't seen her since he locked me up in the warehouse with Kev' <char=47>. She still alive?`,zh:`对，这妞跟迈克<char=23>在一起。她看来跟我一样讨厌他。从我和小凯<char=47>被锁在仓库里之后就再没见过她了。还活著吗？`},Id_DisplayTextPerState_176:{en:`I heard about him, yeah. One of the champions of capitalism. If he choked on his cash, it'd be no loss.`,zh:`有听过这人。资本主义的赢家。要是他被自己的钱噎死，一点都不可惜。`},Id_DisplayTextPerState_177:{en:`I'm Dolores. I've been part of the IRA from the cradle on. I was born with a bomb in my hands, and I will keep making some as long as the people are under the yoke of iniquitous powers.`,zh:`我是桃乐丽思，自懂事以来就是爱尔兰共和军的一员。炸弹伴著我一生，只要还有人们被不公的制度箝制，我就会一直制造炸弹。`},Id_DisplayTextPerState_178:{en:`He's still a bit young, but he is cool...and rather cute. He let Mike <char=23> manipulate him, but he got it now. We're going to have a bit of fun together, so at least I won't have come to London for nothing.`,zh:`他还有点年轻，但是很酷……也有点可爱。他被迈克<char=23>操控过，不过如今已清醒。我们度过了一段快乐的时光，所以这次我来到伦敦也不是一无所获。`},Id_DisplayTextPerState_179:{en:`Mike <char=23> talked about him. He was working for him, if I understood correctly. At the same time, he wasn't quite honest with me, so I don't know that much about it.`,zh:`迈克<char=23>提起过这人。我没记错的话，以前他为这人工作。不过迈克对我不是那么开诚布公，所以我知道的事情很有限。`},Id_DisplayTextPerState_180:{en:`Of course I know the Duke! Those bloody Royalists, I know them by heart. Mike <char=23> told me he was the target. I didn't have a choice but I have to admit I found that rather pleasing. He's a bloody fascist!`,zh:`我当然知道公爵！很熟悉他，可恨的保皇党。迈克<char=23>告诉我这人是目标，虽然我别无选择，但必须承认这真是大快人心。干掉这法西斯！`},Id_DisplayTextPerState_181:{en:`A woman in power--it's rather cool. I don't have much against her yet, but I have no doubt that she's just like the rest of them. This world is over anyway.`,zh:`女性掌权，实在令人痛快。个人来说，我不讨厌她，可是终究跟其他人一样。这世界要完了。`},Id_DisplayTextPerState_182:{en:`In France, they beheaded their kings. I'm sure things would be better if we had done the same here. Have you seen the face of that sucker? Apart from entertaining the people so they don't notice they're being fooled, what does he do?`,zh:`在法国，他们砍了国王的头，要是我们的人也这样做，这国家绝对会变好。你看到那该死的嘴脸吗？他除了取悦大众，让人们不察觉自己被耍，还做了什么？`},Id_DisplayTextPerState_183:{en:`Never saw that person before, is he from the military? Looks like a dirty sort.`,zh:`没见过这人。军方的人马？看著就可厌。`},Id_DisplayTextPerState_184:{en:`Feckin' MI5, they almost managed to dismantle the IRA. But we'll keep fighting, we won't let English imperialism dictate what we do. Let them believe that they won--the young generation is on its way.`,zh:`天杀的国安局，他们几乎瓦解了爱尔兰共和军。不过我们会持续斗争，不会让英国帝国主义主宰我们。就让他们自以为胜利吧——我们的年轻人会前仆后继。`},Id_DisplayTextPerState_185:{en:`There are rumors, and I understood that Mike <char=23> was part of them. In any case, I don't have the feeling that these people share my ideals, and no matter what they're planning, I don't think I'll like it.`,zh:`关于这组织有许多谣传，而我知道迈克<char=23>是其中一员。我不认为这群人跟我理念一致。无论他们策划什么，我都不喜欢。`},Id_DisplayTextPerState_186:{en:`Right, so that's how you found us?`,zh:`你凭这个找到我们？`},Id_DisplayTextPerState_187:{en:`Yeah, I made a bomb. But I didn't really have a choice, Mike <char=23> had made that pretty clear. Just a tip: if you end up trying to defuse my baby, I use special screws--so you'd better have the right screwdriver if you want to keep out of trouble. @ I left all my equipment at the warehouse, so maybe you'll be able to find mine. And don't forget: Purple is life.`,zh:`对，我制造了一枚炸弹，但那是因为迈克<char=23>让我没得选择。给你一道提示：如果你尝试拆除我的宝贝，要用对工具。我用特殊螺丝起子组装的，一不小心就有麻烦。@我把所有工具留在仓库，所以你应该找得到。记住：紫色是生命线。`},Id_DisplayTextPerState_188:{en:`Right, so that's how you found us?`,zh:`你是这样找到我们的吗？`},Id_DisplayTextPerState_189:{en:`I don't take any more drugs than necessary. I'm okay.`,zh:`我只在需要的时候吃药，而我一切安好。`},Id_DisplayTextPerState_190:{en:`That was Mike's <char=23> computer. He must have smashed it before running away.`,zh:`迈克<char=23>的电脑，逃走前砸烂了吧。`},Id_DisplayTextPerState_191:{en:`Right, you found it. That's my specialty: I use special screws to make the work of ammo techs trying to defuse them more difficult. Without a screwdriver like that, it's almost impossible to dispose of my bombs.`,zh:`对，你找到了，这是我的特殊工具，使得拆弹人员更难拆除。只有使用了这种特别的螺丝起子，才有办法解除我的炸弹。`},Id_DisplayTextPerState_192:{en:`I don't know where Mike <char=23> found the equipment, but he had everything ready so I could work. Clearly, he has a strong team behind him.`,zh:`我不知道迈克<char=23>在那里找到这些材料，不过他早已准备好一切让我开始工作。背后明显是强大的团队。`},Id_DisplayTextPerState_193:{en:`Mike <char=23> had showed this to me on the computer. He told me he was working for MI5. I found it hard to believe but clearly, he has good contacts.`,zh:`迈克<char=23>让我在电脑看过这档案，告诉我他为国安局工作。虽然我不觉得可信，但我相信它背后是有靠山的。`},Id_DisplayTextPerState_194:{en:`Mike <char=23> made sure I had no weapon. He's the one who killed your bloke.`,zh:`迈克<char=23>不让我带著任何武器，是他杀死你们的人。`},Id_DisplayTextPerState_195:{en:`Well, I won't deny it, I was there. That bloke held me there for several days so I would make a bomb <itm=11> for him. Just ask Kev' <char=47>!`,zh:`我不会否认，因为当时我的确在场。那家伙把我关在那里几天，好让我帮他做炸弹<itm=11>。去问一下小凯<char=47>吧！`},Id_DisplayText_Default_49:{en:`I don't mind helping, no problem, just ask questions I can answer.`,zh:`我不介意帮忙，没问题的。问一些我知道的问题吧。`},Id_DisplayText_Default_50:{en:`I really don't understand why you are talking to me about this.`,zh:`我根本不清楚为什么你要问我这事情。`},Id_DisplayText_Default_51:{en:`Holy cow! I must still be tripping 'cause I don't understand a word you're saying.`,zh:`天哪！我大概是还没醒来吧，为什么我搞不清你说的任何一个字。`},Id_DisplayTextPerState_196:{en:`So you're the one trying to dismantle the M Organization? Excellent: this country needs more investigators like you. @ As a police officer, you probably won't be able to do much. Give your report to me when the time comes, and I promise you that together we'll put an end to this threat to our freedoms.`,zh:`那么你试图瓦解M组织？值得嘉许！这国家需要更多你这种调查员。@一个警官的力量也许不能做什么，不过把报告交给我，我承诺时机成熟时，就会携手扑灭威胁自由的组织。`},Id_DisplayTextPerState_197:{en:`The old mule won't listen. His legislation is excessively security-oriented, and there's no way it will pass tomorrow--whereas if he was supporting me, we could pass more flexible legislations that would better deal with terrorism.`,zh:`老家伙聼不进意见。他的法案太著重安全性，所以明天一定通过不了——要是他跟我联手，我们就可以通过一项更灵活的议案，这样更有效扑灭恐怖主义。`},Id_LocationState_Introduction_5:{en:`You arrive in front of a luxurious penthouse. A servant opens the door and leads you to a large luxurious living-room where the Prince of England <char=29> is sitting in a wide Chesterfield armchair, waiting for you.`,zh:`你来到一处豪华的阁楼门前，一名仆人为你开门，引领你到一间奢华的客厅，而英格兰王子<char=29>早已坐在宽阔的高档椅子等候你。`},Id_DisplayText_Action_3:{en:`You receive a phone call from an unknown number. "I know you are investigating the M Organization. Meet me in one hour at 15 King George Street in Greenwich <loc=M>. We have a lot to discuss."`,zh:`你接到一通不明来电：「我知道你在调查M组织。一小时后来到格林威治区乔治国王街15号<loc=M>，我们有很多事情要谈。」`},Id_DisplayText_Default_52:{en:`I don't think I know this person.`,zh:`我不认识这人。`},Id_DisplayText_Default_53:{en:`I could try and find out, but it doesn't ring a bell.`,zh:`我可以尝试找答案，但目前毫无头绪。`},Id_DisplayText_Default_54:{en:`No, I really don't know, sorry.`,zh:`抱歉，我真的不知道。`},Id_DisplayTextPerState_198:{en:`I vaguely heard of his service record. You're saying he's dead? It's dreadful. I hope you'll find who did this.`,zh:`我约略听过他的履历。你说他死了？真可怕。希望你早日揪出凶手。`},Id_DisplayTextPerState_199:{en:`A formidable politician. Without a doubt, she has been the most influential French ambassador to England in many years.@ I was surprised by her recent understanding with the Duke of Windsor <char=27>, as I didn't think their ideas were compatible.`,zh:`可怕的政治家。她无疑是多年来英国里最举足轻重的法国大使。@我很惊讶她最近竟然理解温莎公爵<char=27>的意见，因为我一向以为他俩的意见水火不相容。`},Id_DisplayTextPerState_200:{en:`I have now been the Prime Minister of the United Kingdom for one year. I am convinced I can do great things for the good of the country and that's why I won't stop defending my ideas.`,zh:`我担任了英国首相一年，深信我能为国家公益贡献良多，因此会一直坚持理念，不会放弃。`},Id_DisplayTextPerState_201:{en:`I am convinced the Prince will be a very valuable political ally in the years to come. I will see what I can do if you wish to meet him.`,zh:`我相信王子在未来几年会是政坛上可靠的盟友。要是你想见他，我会想办法。`},Id_DisplayTextPerState_202:{en:`This Colonel has a lot of influence and I know he thinks I am too lenient. But I didn't get to my position by taking direction from people who think they know how the world works better than I do. `,zh:`上校影响力非凡，我知道他觉得我处事太柔弱。不过要是以为我会听从那些自认比我聪明的人的指导，我就不会来到今天这位置了。 `},Id_DisplayTextPerState_203:{en:`I haven't yet have the opportunity to talk much with the director of MI5. He was appointed fairly recently a bit surprising as he doesn't have much experience. But well, the world is changing.`,zh:`我没有机会跟国安局局长长谈，由于他经验尚浅，我有点惊讶他受命接任局长。不过这世界确实瞬息万变。`},Id_DisplayTextPerState_204:{en:`A man with a lot of influence in financial circles. He controls powerful lobbies that make my job nearly impossible when I want to modify any legislation that goes against their financial interests.`,zh:`商界里呼风唤雨的人，控制著众多政治献金。要是我打算修改法例，撼动他们的经济利益，便随时能让我举步维艰。`},Id_DisplayTextPerState_205:{en:`That old grump. I don't trust him. I think he's still upset that his father lost the throne during the Second World War due to his Nazi sympathies. @ My mother allowed him to come back to the family, although he grew up in France. I don't like him. To me, he is living in a bygone era.`,zh:`老糊涂，我不信任他。二战时他父亲同情纳粹而丢了王位，我认为他至今耿耿于怀。@尽管他生长在法国，我母亲容许他回归家族。我不喜欢他，看著就觉得是颗活化石。`},Id_DisplayTextPerState_206:{en:`There is something I don't trust about that little weasel. There's suspicion that he achieved his position through blackmail and that his only motive is the lure of power. I'm keeping an eye on him as much as I can.`,zh:`我不信任这小滑头。有人怀疑他靠恐吓爬到这位置，唯一的目标就是攫取权力。我尽可能提防他。`},Id_DisplayTextPerState_207:{en:`Trooper is a dangerous reactionary. I think he misses the good old days of the Empire and the colonies. Thankfully, he is also a loyal defender of the Royal Family, so I do hope that he can be trusted.`,zh:`翠普是危险的反动分子。我认为他怀念帝国和殖民地时期的老日子。幸好他非常支持王室，但愿他可信。`},Id_Ending_Question_2:{en:`Who is leading the M Organization in England?`,zh:`谁在英国领导M组织？`},Id_Ending_Question_3:{en:`Who provides the M Organization with sensitive information?`,zh:`谁为M组织提供机密资讯？`},Id_DisplayTextPerState_208:{en:`That was in the computer? Surprising. That's not the kind of data that should be wandering about.`,zh:`在电脑找到？真令我意外，这是不应该流传的内容。`},Id_DisplayTextPerState_209:{en:`I made sure all our ammunition could be tracked to keep it as secure as possible.
This bullet comes from a stolen ammunition stockpile and I can guarantee it came off Mike Sanders' <char=23> weapon.`,zh:`我能够追踪到所有弹药，保证一切尽可能安全。

这发子弹从弹药库存被偷走，而且我敢说是麦克·桑德斯<char=23>击发的。`},Id_DisplayTextPerState_210:{en:`You found a bullet... I hope this will help you to find the killer.`,zh:`你找到一发子弹……希望有助你早日找出凶手。`},Id_DisplayTextPerState_211:{en:`So you know I am the one who killed him. So what? You think you're going to manage to prevent anything from happening? You lost-- you just don't know it yet.`,zh:`你知道是我杀死他的。又如何？你以为有办法阻止将要发生的事情？太天真了！你根本什么也不知道。`},Id_DisplayTextPerState_212:{en:`While he thought I was sleeping, Mike <char=23> met with one of his accomplices. I'm convinced it was her.`,zh:`迈克<char=23>跟他一名同党见面。当时他以为我睡着了，但我肯定就是她。`},Id_DisplayTextPerState_213:{en:`Erm... no... I don't know.`,zh:`嗯……我不清楚。`},Id_DisplayTextPerState_214:{en:`This story is getting worse and worse. I'll do anything I can to help you, but I don't know much. I would never have imagined it could be so serious. @I don't know if it can be useful, but apart from the punk girl <char=19>, he also met with a woman in Ireland. I didn't get a good look at her, but I think she is Indian, middle-aged and upper class. I hope you'll be able to find her.`,zh:`事情越来越糟，我会尽可能协助你，但不知道究竟能帮到什么地步。我没有想到会这样事关重大。@除了那名庞克女孩<char=19>，迈克在爱尔兰还见了另一个女人。不晓得这有没有帮助。我没有仔细看到她的样子，但应该是印度人，中年，感觉是上流人士。希望你有办法找出她。`},Id_DisplayTextPerState_215:{en:`I don't know anything about DIY.`,zh:`我对DIY毫无头绪。`},Id_DisplayTextPerState_216:{en:`I think I saw Mike <char=23> with this computer.`,zh:`我见到迈克<char=23>带著这台电脑。`},Id_DisplayTextPerState_217:{en:`Oh no--don't tell me he killed someone...`,zh:`天哪，别告诉我他杀了人。`},Id_DisplayTextPerState_219:{en:`I understood that you wanted to talk to me? I will help you as much as I can, since you saved my daughter. But I still have a lot of work to do. So let's get this over with.`,zh:`我知道你想跟我说什么。由于你帮过我的女儿，我会尽量配合，但是我还有很多工作要做，不要太过分。`},Id_DisplayTextPerState_218:{en:`Bugger. I'm so sorry. It's never easy to lose a colleague so suddenly.
Try to find out if he was involved in the M Organization <itm=02>, or if they are the ones who killed him.`,zh:`马的，我为此难过，没想到他能这样轻易走掉。

尝试找出是否卷入M组织<itm=02>而死，而且是否就是它们下手。`},Id_DisplayTextPerState_220:{en:`She should have come back from France by now. Did you question her? I am convinced she knows things about the M Organization.`,zh:`现在她应该从法国回来了，你问过她了吗？我肯定她知道M组织的事情。`},Id_DisplayTextPerState_221:{en:`It seems to be too late to concern yourself with the ambassador now.`,zh:`看来要联络大使也太迟了。`},Id_DisplayTextPerState_222:{en:`The poor kid probably didn't realise what he was getting into. I don't think you'll learn much from him.`,zh:`可怜的小伙子，还不知道被卷入怎样的事件里。我不认为你可以从他身上知道多少情报。`},Id_DisplayTextPerState_223:{en:`You think he could be the target of the M Organization? It could be: his proposed legislation to strengthen the judicial system in order to fight terrorism would have to be unpopular with them. @ This folder from MI5 is really worrying. It confirms that there's a mole in our agency. I know that my director <char=36> doesn't really like the Duke. Could he belong to such an organization?`,zh:`你觉得他是M组织的目标吗？也许吧。他提出了法案，扩大司法机构的权力以打击恐怖主义，也许使得他成了眼中钉。@国安局的档案令人堪忧，证明部门里有内鬼。我知道局长<char=36>不喜欢公爵，他会否就隶属M组织？`},Id_DisplayTextPerState_224:{en:`I already had my suspicions about him, and what you say isn't making me feel any better. He's in the best position to leak documents without anyone noticing.`,zh:`我早就怀疑他，而你说的事情没有减轻我的担忧。他完全可以不声不响地泄露机密。`},Id_DisplayTextPerState_225:{en:`You think she could be responsible for the leak? That's not how I think of her, but actually... she does have a strategic position, and McVeill <char=36> is the only one who could realize whether she is betraying him or not.`,zh:`你认为是她泄露资料？我不这么想，不过……她的确位居要津，而只有麦威尔<char=36>有办法察觉她有否背叛。`},Id_DisplayTextPerState_226:{en:`I've never heard of her, but from what you are telling me, it sounds like Sanders <char=23> used her to have an alibi.`,zh:`从来没听过这人，但是根据你告诉我的情报，看来桑德斯<char=23>利用她捏造不在场证据。`},Id_DisplayTextPerState_227:{en:`An important player in Great Britain. His influence in financial circles is undeniable. I don't know if the M Organization was interested in him just for the money or if he is involved in their future project... but let's stay alert.`,zh:`大不列颠的重要人物，在商界的影响力不容置疑。我不知道M组织接洽他只是要他的钱，还是他有份参与将来的计划……务必留神。`},Id_DisplayTextPerState_228:{en:`So the M Organization is planning a bombing attack... Okay, but this doesn't tell us what their target and their motives might be. For Saturday, I can see at least three potential targets: @ The Prince's <char=29> engagement ceremony in Greenwich <loc=M>, the vote on the Duke of Windsor's <char=27> proposed legislation at the Parliament in Westminster <loc=A>, and Eli Goldman's  <char=39> financial fair at the City <loc=B>. We have to find a better lead.`,zh:`M组织策划炸弹袭击吗……好吧，但是这看不出他们的目标和动机。我能举出星期六可能受袭的三个目标：@首先是王子<char=29>的订婚典礼，在格林威治<loc=M>举行。其次是温莎公爵<char=27>提出法案的投票，在西敏国会大楼<loc=A>举行。最后，艾利·戈德曼<char=39>在市中心<loc=B>举办财经展览的开幕仪式。我们急需更多资料分析。`},Id_DisplayTextPerState_229:{en:`I'm not much into DIY. But considering how you found it, I guess it has to do with the bombs.`,zh:`我不熟悉DIY工具，但你找到了，应该就跟炸弹有关。`},Id_DisplayTextPerState_230:{en:`This discovery is very worrying. I contacted you because I didn't trust MI5, and you're giving me confirmation that there is a link between my agency and the M Organization <itm=02>. @ I wouldn't be surprised if McVeill <char=36> was involved. I could never stand him. He got his position too easily. and I have the feeling he is putting a spoke in my wheels.`,zh:`这件事令人十分担忧。因为我信不过国安局，所以联络你。现在你给了我情报，指出我的部门跟M组织<itm=02>有关联。@就算我知道麦威尔<char=36>牵涉在内也不惊讶，因为打从一开始我就不相信他。他爬升得太容易，而且感觉他处处妨碍我。`},Id_DisplayTextPerState_231:{en:`You should be able to find your Chief Officer's killer with this. It is rare that a bullet cannot be traced nowadays.`,zh:`这样你就应该有办法找出杀死局长的凶手。如今大部分子弹都能追溯到源头。`},Id_DisplayTextPerState_232:{en:`That's right, I knew about the theft. I was trying to deal with the case internally to save us some face, but I suppose it's too late for that now. As for the accusations, they're ridiculous!`,zh:`对，我知道失窃案。当时我打算内部解决免得丢脸，但现在已经太迟了。不过那些指控实在胡说八道！`},Id_Item_Name_19:{en:`McVeill's bag`,zh:`麦威尔的袋子`},Id_DisplayTextPerState_233:{en:`You find Director McVeill's <char=36> bag. Inside: some files, including one on Colonel Karl Trooper <char=24> showing that he was informed over a week ago that explosives were missing.`,zh:`你找到麦威尔局长<char=36>的袋子，里面有些档案，其中有一份有关卡尔·翠普上校<char=24>，表明他在一星期前已经知道有炸药失窃。`},Id_Item_Name_20:{en:`Television camera`,zh:`采访影片`},Id_Item_Name_21:{en:`Decorative plants`,zh:`装饰植物`},Id_Item_Name_22:{en:`A jacket`,zh:`夹克`},Id_DisplayTextPerState_238:{en:`Of course I know Drake. I know all our agents. I shouldn't be telling you this, but here is some advice: don't trust him. He has been investigating the M Organization <itm=02> for such a long time. Perhaps for too long...`,zh:`我认识全部特务，当然也认识德雷克。我不应该这么说，但奉劝你不要相信他。他调查M组织<itm=02>很久，也许太久了……`},Id_DisplayTextPerState_239:{en:`I never had the opportunity to meet the Chief Officer, no.`,zh:`我从没见过你的局长。`},Id_DisplayTextPerState_240:{en:`I have no idea who this person is. Do they have anything to do with your case?`,zh:`不知道他是谁，跟你的案件有关？`},Id_DisplayTextPerState_241:{en:`I've been seen talking to him? Your witness must have gotten something wrong. I don't know who this person is. I've nothing to tell you.`,zh:`有人见过我跟他交谈？你的线人看错了。我不认识他，也没有事情要告诉你。`},Id_DisplayTextPerState_242:{en:`Very worrying. There were rumors that we had a mole, but this is overwhelming evidence. I think we'll have to take a closer look at Agent Drake O'Brian <char=49>.`,zh:`这真令人担忧，因为谣传我们之间有内鬼。现在证据确凿，我要重新审视德雷克·柯布连<char=49>这个人。`},Id_DisplayTextPerState_243:{en:`Cute, but she doesn't ring any bells. We don't have much leave time, so no time to flirt. `,zh:`很可爱，但我对她没印象。我们没时间浪费在无聊问题。 `},Id_DisplayTextPerState_244:{en:`Fine: I may have done business with her, but that's not your concern.`,zh:`好吧：我跟她有事情往来，但与你无关。`},Id_DisplayTextPerState_245:{en:`I should never have trusted him--he was too close to that scoundrel Roger Gaiman <char=35>, but he had received high-level support. I even seem to remember that the Duke of Windsor <char=27> had argued his case. `,zh:`我不应该相信他，因为跟无赖罗杰·盖曼<char=35>走得太近。不过他有高层人士保护，我现在记得温莎公爵<char=27>曾关说过他的案件。 `},Id_DisplayText_Action_4:{en:`As a gesture of gratitude for your help following her daughter's kidnapping, the French ambassador <char=15> answered MI5 request for her to come at Sctoland Yard <home> for interrogation.. @ She just arrived to answer your questions. She won't be staying long as she is on a tight schedule.`,zh:`为了答谢你解决她女儿的绑架案，法国大使<char=15>答应了国安局，来到苏格兰场<起始地点>接受盘问。@她刚抵达，准备回答你的问题。由于行程紧迫，她只会逗留很短时间。`},Id_DisplayTextPerState_246:{en:`Even if I wanted to cooperate, I wouldn't be able to tell you much. The Organization helped me to find a transplant to save Clara's life <char=14>. In return, they asked me for a few favors.@ I went with it for a while, until I recently decided that it wasn't worth it. Their last request was strange: they asked me to gift plants to Parliament. @I said no, and that's why they came after my daughter--so they could put pressure on me. Thank God you stepped in. `,zh:`即使我愿意帮忙，也不能告诉你太多事情。这组织帮助我找到器官移植给卡拉<char=14>，救活了她。我为它们做了一些事情作为报答。@我按它们所说的做了一阵子，最终发现不应该继续。最后一个请求很奇怪：要我给国会送一棵植物。@我拒绝了，所以它们向我的女儿下手，以此威胁我。幸好你们介入了。 `},Id_DisplayText_Default_55:{en:`I meet a lot of people in my line of work. I cannot remember everything.`,zh:`我在工作上见过很多人，而且不能都一一记住。`},Id_DisplayText_Default_56:{en:`I will help you in any way I can, but I don't think I know this person.`,zh:`我很乐意帮助你，但我不认识这人。`},Id_DisplayTextPerState_248:{en:`I guess it was partly thanks to him that I found Clara <char=14>, but I never met him.`,zh:`感谢他间接帮我找回卡拉<char=14>，不过我们从未碰面。`},Id_DisplayTextPerState_249:{en:`I heard about his death. My deepest condolences. He seemed a good man.`,zh:`听说他去世了，我深感惋惜，似乎是一名好人。`},Id_DisplayTextPerState_250:{en:`I am just back from France with Clara <char=14>. After everything that happened, we really needed some time together to recover.`,zh:`我刚刚从法国跟卡拉<char=14>一起回来。经过了这么多事，我们需要时间好好休息一下，`},Id_DisplayTextPerState_251:{en:`I haven't had a lot of contact with him, but he brought me great comfort when I was worrying about Clara <char=14>.`,zh:`我和他没有太多的来往，但是当我为卡拉<char=14>忧心如焚，幸好有他安慰我。`},Id_DisplayText_Action_5:{en:`The night passes.@ Today is Friday. After a good night's rest, you are ready for a new day of investigation.`,zh:`天亮了。@今天是星期五，好好休息了一晚，你准备开始新一天的调查。`},Id_DisplayText_Action_6:{en:`The night passes.@ Today is Saturday, the fateful day. This case will have to be solved today!`,zh:`天亮了。@今天是星期六，攸关国安，必须今天破案！`},Id_DisplayTextPerState_252:{en:`It's hard to believe. I know I can't trust anyone in this investigation, but I thought Colonel Trooper was a righteous man. I can't imagine him being involved in that shady business.`,zh:`难以置信，我知道应该对任何一个人抱著怀疑，但我之前还确信翠普上校笃信正义。没想到他也在这肮脏的事情里面掺了一脚。`},Id_DisplayText_Default_57:{en:`I don't know what to tell you.`,zh:`我不知道有什么可以告诉你。`},Id_DisplayText_Default_58:{en:`Do you really think that's relevant to the investigation?`,zh:`真的跟调查有关？`},Id_DisplayText_Default_59:{en:`No matter how much I think about it, nothing useful is coming to me.`,zh:`我没有掌握任何有用的资讯。`},Id_Item_Name_17:{en:`Bomb`,zh:`炸弹`},Id_DisplayTextPerState_254:{en:`A phone call just before the explosion... that's one hell of a coincidence...`,zh:`刚好在爆炸之前来电……哪门子的巧合……`},Id_DisplayTextPerState_255:{en:`They're not messing around. They had enough to destroy all of Parliament with that.`,zh:`他们可不是在搞恶作剧，这东西足以摧毁国会大楼。`},Id_DisplayText_Default_60:{en:`I am here of my own free will, so try not to waste my time.`,zh:`我是自愿前来的，别浪费时间。`},Id_DisplayTextPerState_256:{en:`That's exactly what I was saying. Authorities are powerless to deal with terrorism. Only my proposed legislation will solve this issue--there is a reason why they tried to blow me up during the vote. `,zh:`这正是我一直在说的，目前政府部门太软弱，无法打击恐怖主义。只有我提出的法案可以整治——因此恐怖分子打算在投票期间炸死我。 `},Id_DisplayTextPerState_257:{en:`He was going to lose. The Duke didn't stand a chance with his proposal, and now with this bloody bomb, everything is called into question!`,zh:`公爵的法案本来不可能通过，他应该会输掉。现在有这颗该死的炸弹，一切都将有变卦！`},Id_DisplayTextPerState_258:{en:`You really think I might be mixed up with people like that?`,zh:`你真的认为我跟这种人有来往？`},Id_DisplayTextPerState_259:{en:`You really have a serious case of incompetence in this police station. I hope your next Chief Officer will be less lenient.`,zh:`你们警方实在极度无能，但愿下一任局长处事能强硬一点。`},Id_DisplayTextPerState_260:{en:`I don't know your Chief Officer, but given your effectiveness, I guess I shouldn't expect too much from him either.`,zh:`我不认识你们的局长，但是领教过你的办事效率，我对他也没多少期望。`},Id_DisplayTextPerState_261:{en:`I am just back from France. Some friends helped me to find Clara <char=14> after she went missing. She's safe and sound now.`,zh:`我刚刚从法国回来。有些朋友帮我找回失踪的卡拉<char=14>。现在她安然无恙。`},Id_DisplayTextPerState_262:{en:`I don't want to hear anything more about that piece of garbage.`,zh:`我不想知道这人渣的事情。`},Id_DisplayTextPerState_263:{en:`He's the one who enabled Clara <char=14> to survive, a few years ago. With the M Organization <itm=02>, they made her transplant possible. I just didn't expect there would be such a high price to pay afterward.`,zh:`几年前他救活了卡拉<char=14>。由于M组织<itm=02>帮忙，它们给卡拉做了移植手术。没想到事后的代价如此巨大。`},Id_DisplayTextPerState_264:{en:`A wonderful woman, a true role model for me.`,zh:`了不起的女性，是我的榜样。`},Id_DisplayTextPerState_265:{en:`I haven't met him yet, but perhaps I'll have the opportunity to do so at his engagement ceremony on Saturday. He seems to have a sharp political mind.`,zh:`我没见过他，但也许会在他星期六的订婚典礼会碰面。他的政治头脑十分清晰。`},Id_DisplayTextPerState_266:{en:`I dealt with him several times. We clearly don't have the same political views, but I respect him as an adversary.`,zh:`跟他交手过好几次，我俩的政治立场截然不同，但的确是可敬的对手。`},Id_DisplayTextPerState_267:{en:`He's the MI5 director, isn't he? I know of him but I've never encountered him.`,zh:`他是国安局的局长，不是吗？听说过，但没有碰过面。`},Id_DisplayTextPerState_268:{en:`Of course I know Eli Goldman. He must have made the front page of every financial newspapers around the world over the last few years. I never met him but his political influence is well known.`,zh:`我当然认识艾利·戈德曼，过去几年全球每一份财经报都拿过他当头版封面。我没有会过他，但其政治影响力无庸置疑。`},Id_DisplayTextPerState_269:{en:`I can't tell you anything about this. But if they exist, they have done much more for my daughter <char=14> than you have.@
When Clara needed a transplant, neither the English nor the French were there. When she was kidnapped, neither the English nor the French were there. 

Clara is safe now, and it's not thanks to you. `,zh:`对此我没有事情可以告诉你，不过即使真有这么个组织，它对我女儿<char=14>的恩情远比你大。@

卡拉需要器官移植时，英国人和法国人都没有伸出援手。她被绑架时，同样没有人伸出援手。


卡拉现在活得好好的，而并不是你的功劳。 `},Id_DisplayText_Default_61:{en:`I really don't understand why you're talking to me about this.`,zh:`你为什么要问我这事情。`},Id_DisplayText_Default_62:{en:`What do you want me to do with this? No, I don't know anything about it.`,zh:`你以为我会知道吗？这我完全不懂。`},Id_Character_Name_20:{en:`Clara Blanche`,zh:`卡拉·布兰奇`},Id_DisplayTextPerState_271:{en:`My baby. I realize how lucky I was to find her again. I would do anything to protect her now.`,zh:`我的宝贝，幸好终于找回她。我肯尽一切努力保护她。`},Id_DisplayTextPerState_272:{en:`Clara was returned to me safely, no thanks to you.`,zh:`卡拉平安回来，这不是你的功劳。`},Id_DisplayTextPerState_277:{en:`It is indeed a convenient coincidence...`,zh:`的确是太巧合了……`},Id_DisplayTextPerState_278:{en:`Do you understand that this Organization should not be taken lightly?`,zh:`你知道这种组织必须严惩吗？`},Id_LocationState_Introduction_6:{en:`On orders from the Prime Minister, the Parliament was evacuated. But we can't keep it cleared for long. Everyone wants to keep talking about the Duke of Windsor's <char=27> proposed legislation, supported by Conor McVeill <char=36>. The Prime Minister <char=21> seems to be nervous because of your request.`,zh:`根据首相命令暂时疏散了国会大楼，但这不能维持很久。大家都想讨论温莎公爵<char=27>的法案，科拿·麦威尔<char=36>也支持。你的建议使得首相很紧张。`},Id_LocationState_Introduction_7:{en:`At this hour, there are only a few security guards left in this distinguished building.`,zh:`现在这座众所周知的大楼里只剩下少数保全人员。`},Id_DisplayText_Default_63:{en:`This person probably went back home already.`,zh:`这人应该回家了。`},Id_DisplayText_Default_64:{en:`You will be more likely to find this person tomorrow.`,zh:`明天再找这人吧。`},Id_DisplayTextPerState_279:{en:`Why does this man have to be so stubborn? If he agreed to compromise a bit, we could pass reforms together. Instead, he's going to hit a brick wall during the session tomorrow.`,zh:`为什么那男人如此顽固？要是他肯作一点让步，我们就能通过法案了。现在可好了，明天他铁定会碰钉子。`},Id_DisplayTextPerState_280:{en:`Your requests are becoming really inappropriate. What do you want?`,zh:`你的建议非常不恰当。你到底要做什么？`},Id_LocationState_Introduction_8:{en:`The security guard makes it clear in a particularly firm manner that you should not expect to enter this building before tomorrow.`,zh:`警卫斩钉截铁告诉你今天之内踏不进这门口。`},Id_LocationState_Introduction_9:{en:`The impressive MI5 building is a high-tech, high-security fortress. You are still finding it hard to believe that you are being let in.`,zh:`壮观的国安局大楼是一座高科技且保全严密的堡垒。至今你还不敢相信竟然获准进来了。`},Id_LocationState_Introduction_10:{en:`The impressive MI5 building is a high-tech, high-security fortress. You are still finding it hard to believe that you are being let in. `,zh:`壮观的国安局大楼是一座高科技且保全严密的堡垒。至今你还不敢相信竟然获准进来了。 `},Id_LocationState_Introduction_11:{en:`The impressive MI5 building is a high-tech, high-security fortress. You are still finding it hard to believe that you are being let in. `,zh:`壮观的国安局大楼是一座高科技且保全严密的堡垒。至今你还不敢相信竟然获准进来了。 `},Id_DisplayText_Default_65:{en:`This person doesn't seem to be in the building.`,zh:`看来人不在这建筑。`},Id_DisplayText_Default_66:{en:`Security staff make it clear that you will have to look for that person somewhere else.`,zh:`警卫清楚告诉你到别处找这人。`},Id_DisplayTextPerState_281:{en:`I don't seem to remember that you had an appointment?`,zh:`我不记得你有事前约见。`},Id_DisplayTextPerState_282:{en:`If you are here to see the Director <char=36>, he is not here. He is at Parliament <loc=A> today.`,zh:`要是想见局长<char=36>，今天他不在，因为去了国会<loc=A>。`},Id_DisplayTextPerState_283:{en:`My time is precious, today more than ever. What do you need?`,zh:`我的时间宝贵，尤其是今天。什么事？`},Id_DisplayTextPerState_284:{en:`Maybe we underestimated the extent of the terrorism issue. Find that bomb, quickly.`,zh:`也许我们低估了恐怖份子的计划。快，找出炸弹。`},Id_DisplayText_Default_67:{en:`You don't find anything like that in the room.`,zh:`房里找不到这东西。`},Id_DisplayText_Default_68:{en:`As hard as you look for it, this object is not here.`,zh:`尽可能地找过了，东西不在这。`},Id_DisplayTextPerState_285:{en:`You find the professional camera of a television crew. You rewind the tape a bit and notice that the Duke of Windsor <char=27> received a phone call and left the room shortly before you arrived.`,zh:`你发现一台电视新闻采访用的的专业摄影机，把里面的影片纪录倒转一阵子，看到在你到来前不久，温莎公爵<char=27>接到一通电话，然后便离开了房间。`},Id_DisplayTextPerState_286:{en:`As you take one of the plants out of its huge pot, you find the bomb <itm=11>. The detonator's display shows that there are only a few minutes left. If you don't manage to defuse it, nobody will.`,zh:`你从一个大瓶子拿出里面的植物，并发现了炸弹<itm=11>。上面的数字显示只剩几分钟就会爆炸。若你没办法拆除它，那么没人有办法。`},Id_LocationState_Introduction_12:{en:`You are late for the debriefing meetings, which come one after another. No matter how hard you try to explain that there are other priorities, nothing seems to work and you have to stay until it's too late to continue with the investigation.`,zh:`你迟到了一个接一个的报告会议。无论你如何努力解释有多少紧急事情要处理，看来也徒劳无功。你必须留在这里，不然没办法继续调查。`},Id_LocationState_Introduction_13:{en:`You arrive in an old abandoned warehouse. In the distance you hear the siren of the Wormwood factory. Your phone is not picking up any signal. It seems like you're onto something, but it's too dark for you to conduct the investigation without missing things.`,zh:`你来到老旧的废弃仓库，远处听到苦艾工厂的汽笛声，手机讯号断断续续，看来你来对了地方，但是现在太黑了，即使你想调查也无法看清环境。`},Id_LocationState_Introduction_14:{en:`Whether by day or by night, this squat seems to be constantly active. Despite the dense crowds of destitutes, you don't have any trouble spotting Dolores Kelly <char=19> in the company of Kevin Doyle <char=47>.`,zh:`无论白天还是晚上，这幢非法占用居所都生机蓬勃。尽管里面住满了牛鬼蛇神，你很容易就认出了桃乐丽思·凯莉<char=19>，还有在一起的凯文·代尔<char=47>。`},Id_LocationState_Introduction_15:{en:`The building superintendent makes it clear that unless directly invited, no one is welcome at this time of the day.`,zh:`保安警官清晰地告诉你只有确定受邀的人可以在这时间进去，其余人等不得入内。`},Id_LocationState_Introduction_16:{en:`At this time of the day, the barracks don't accept visitors anymore. If you don't have a warrant, you will have to come back tomorrow.`,zh:`到了这时候，军营不会接待访客。如果你没有通行证，只好明天再来。`},Id_LocationState_Introduction_17:{en:`Eli Goldman's <char=39> company is bustling with activity and everybody seems to be overworked--yet the financial genius agrees to give you an interview.`,zh:`艾利·戈德曼<char=39>的公司非常忙碌，看来每人的工作都超出负荷——但是那位商界大亨依然愿意接见你。`},Id_LocationState_Introduction_18:{en:`The City never really sleeps. Despite the late hour, you manage to meet Eli Goldman <char=39>.`,zh:`这是座不夜城。在这样深夜时间，艾利·戈德曼<char=39>依然肯见你。`},Id_Item_Name_23:{en:`A discarded phone`,zh:`丢弃的电话`},Id_Item_Name_24:{en:`Pens and paper`,zh:`纸笔`},Id_DisplayTextPerState_289:{en:`A lord probably dropped his phone in the shuffle, but there's nothing interesting to be learned from it, unless you want to know his high score on Fruit Ninja.`,zh:`一名议员掉了手机，但里面没有值得留意的资料。你知道了他玩水果忍者的分数记录。`},Id_DisplayTextPerState_290:{en:`You find plenty of papers and pens scattered around, but nothing particularly interesting.`,zh:`你找到很多纸笔散落一地，但没有线索。`},Id_DisplayTextPerState_291:{en:`With the rare woods and gilded trim, the decor of the place is rather gaudy, but it doesn't look like anything interesting is hidden there, let alone a bomb.`,zh:`高级木材和镀金装饰让这里十分华丽，不过看来里面无法藏入任何东西，更不用说炸弹。`},Id_Item_Name_25:{en:`Decor`,zh:`装饰`},Id_DisplayTextPerState_292:{en:`The Prime Minister <char=21> forgot her jacket in the room. A quick search allows you to see that she is supposed to meet Eli Goldman <char=39> tonight.`,zh:`首相<char=21>在房内掉了外套。快速调查一下，得知她约了艾利·戈德曼<char=39>今晚见面。`},Id_DisplayTextPerState_293:{en:`No matter how much you search the impressive furnishing of the room, the bomb doesn't seem to be hidden there.`,zh:`无论你花多少精力搜索房内精致的家具，也找不到隐藏的炸弹。`},Id_DisplayTextPerState_294:{en:`I trusted you. I counted on you to help me bring down the M Organization <itm=02>, and you just stab me in the back. Honestly, I don't even know if I should help you anymore.`,zh:`我相信你能帮忙打垮M组织<itm=02>，你却在背后捅我一刀。坦白说，真不知道该不该再帮助你。`},Id_DisplayTextPerState_295:{en:`We will have to remain vigilant, but I am convinced that together we can bring down the M Organization <itm=02>. I know I can trust you and that's important, as our enemies are everywhere.`,zh:`尽管我们应该互相警惕，但我相信只要合力便能打垮M组织<itm=02>。重要的是，我知道你可靠，因为敌人随时潜伏四周。`},Id_DisplayTextPerState_296:{en:`I couldn't tell you before, but yes: I am part of MI5. I've been 5's undercover agent within the M Organization <itm=02> for over ten years in an effort to dismantle them. With your help, I am convinced we are close to finding their leader.`,zh:`之前不能表明身份，但现在可以了：我是国安局派到M组织<itm=02>的卧底，至今超过十年，计划瓦解他们。有了你的帮助，我确信已经一步步迈进了。`},Id_DisplayTextPerState_297:{en:`You did a great job with the girl. I believe her mother should be willing to answer your questions.`,zh:`做得好！救出她的女儿让她愿意配合你调查。`},Id_DisplayTextPerState_298:{en:`It's a pity you didn't manage to find that girl. Her mother might withhold some information out of fear or anger.`,zh:`可惜你没找到小女孩，使得她母亲对你十分震怒，不肯配合调查。`},Id_DisplayText_Default_69:{en:`You don't find anything like that here.`,zh:`在这里找不到这东西。`},Id_DisplayText_Default_70:{en:`You should probably look elsewhere.`,zh:`到别处找吧。`},Id_LocationState_Introduction_19:{en:`Things are out of control at Scotland Yard. The Chief Officer's <char=33> death has put everyone on edge. Crisis meetings come one after another, and Scott Clover <char=43> seems to be buried in paperwork.`,zh:`苏格兰场一团乱。局长<char=33>去世使得每个人都异常紧张。危机应变会议一个接一个，而史葛·葛洛佛<char=43>被海量的文书工作淹没了。`},Id_DisplayText_Default_71:{en:`Fuck, no, I don't know who that is!`,zh:`干！我不认识这人！`},Id_DisplayText_Default_72:{en:`Why are you bothering me with all those blokes now?`,zh:`你别再拿这些家伙烦我了！`},Id_DisplayText_Default_73:{en:`Seriously, did you think you were my old man or something?`,zh:`你算老几？你是我爸吗？`},Id_DisplayTextPerState_299:{en:`...oh, shit. He was an agent of capitalism, but he was still my fucking father. I never agreed with him, but that doesn't mean... that doesn't mean I didn't love him. I have to let my mother know--she'll just fall apart...
Okay. So. What do you want to know?`,zh:`……靠，尽管他是资本主义的傀儡，好歹也是我老爸。我从没同意他的主张，但不代表我不爱他……我要告诉我妈，但她应该会昏过去……

好吧，你想知道什么？`},Id_DisplayTextPerState_300:{en:`Yeah, I should never have let myself get caught up in that story. Mike <char=23> told me we were going to build a better world, but when Dolores <char=19> showed up, I realized he was hiding things from me. @ When my dad showed up yesterday, Mike tried to kill him. We took the opportunity to clear out. I really didn't think my father wouldn't make it. I hope you'll leave that bastard Mike to waste away in a cell for a long time.`,zh:`对，我不应该牵涉进这事。迈克<char=23>告诉我要一同创造更好的世界，不过同时我遇到了桃乐丽思<char=19>，于是知道迈克有事瞒著我。@昨天我爸来见我，迈克甚至试图杀死他。我俩便趁机逃走，从没想过我爸会就此死掉。我希望你逮住迈克这混帐，让他在牢里蹲上很久。`},Id_DisplayTextPerState_301:{en:`I heard Mike <char=23> talking about him. They used to work together before but I never met him.`,zh:`听过迈克<char=23>谈起他，说以前一同工作，但没跟我见过面。`},Id_DisplayTextPerState_302:{en:`Don't know that old man.`,zh:`不认识这老人。`},Id_DisplayTextPerState_303:{en:`Ah yeah, she's the queen or something like that, right?`,zh:`啊，女皇之类的人吧。`},Id_DisplayTextPerState_304:{en:`Of course I know the Prince. I saw his face on plenty of the decorative plates they produced for his engagement. It's in Greenwich <loc=M> on Saturday.`,zh:`我当然知道王子，他这个星期六就在格林威治<loc=M>举行订婚典礼，为此还把他脸印在好多装饰碟上，我见多了。`},Id_DisplayTextPerState_305:{en:`That's Mike's <char=23> boss, right? He was scared shitless of him.`,zh:`迈克<char=23>的上司吧？迈克怕他怕得要死。`},Id_DisplayTextPerState_306:{en:`The only good thing that came out of this story is that I got to meet Dolores. That chick is wicked, you have no idea. No one else like her.`,zh:`整件事唯一可喜的，就是遇上桃乐丽思。宛如女神，独一无二。`},Id_DisplayTextPerState_307:{en:`If that bastard shot my father, I hope he'll die. I should have realized that he was just using me to reach my father. I thought he was my friend. I really got screwed.`,zh:`要是这混帐射杀我爸，我恨不得他死。还以为他是朋友，真应该看穿他只是利用我接触我爸。我有够笨的。`},Id_DisplayTextPerState_308:{en:`I think I already saw her. She was one of Mike's <char=23> friends, right? Well, she didn't seem to be close to him either. I wouldn't be surprised if he used her too.`,zh:`我应该见过她了，是迈克<char=23>的朋友吧？跟迈克看来不亲密，只怕也是被他利用。`},Id_DisplayTextPerState_309:{en:`Yeah, that's the girl who was kidnapped. My father was dead proud that you had saved her. He thought you were the best. Sometimes I even thought he'd rather have you in the family over me.`,zh:`对，她是被绑架的女孩。你救出了她，我爸无比自豪，觉得你非常称职。有时候我觉得他宁愿认你做儿子。`},Id_DisplayTextPerState_310:{en:`Yeah, that's the girl who was kidnapped. My father was disgusted that you didn't manage to find her. He considered it a personal failure.`,zh:`对，她是被绑架的女孩。我爸厌恶你找不到她，认为这是生涯污点。`},Id_DisplayText_Default_74:{en:`I don't know what that thing is.`,zh:`不知道这是什么。`},Id_DisplayText_Default_75:{en:`You suck, asking me so many questions!`,zh:`闭嘴！别问那么多问题。`},Id_DisplayTextPerState_311:{en:`I heard my father talk about it from time to time, but I have no idea what it is.`,zh:`听过父亲谈起它好几次，但不知道是什么。`},Id_DisplayTextPerState_312:{en:`That's Dolores' <char=19> things. She's honestly amazing with them, a real artist.`,zh:`那是桃乐丽思<char=19>的。她很瞭这玩意，甚至可以说是艺术家。`},Id_DisplayTextPerState_313:{en:`I couldn't swear to it because I haven't seen her since, but I think she was with Mike on the night he met me.`,zh:`我跟迈克见面那一晚应该见过她，但说不准，因为至今没再见过她。`},Id_DisplayTextPerState_314:{en:`Wow, and that's how you found me? My father was right to be proud of you.`,zh:`凭这找到我吗？难怪我爸以你为荣。`},Id_DisplayTextPerState_315:{en:`Yeah, I use drugs, so what? You're not my father!`,zh:`对，我吸毒了，又如何？你又不是我爸。`},Id_DisplayTextPerState_316:{en:`These are Dolores' <char=19> things. She told me this one was important but I can't remember why.`,zh:`这是桃乐丽思<char=19>的。她告诉我这东西很重要，但我忘了原因。`},Id_DisplayText_Default_76:{en:`What do I care?`,zh:`喔`},Id_DisplayTextPerState_317:{en:`Can I have it as a keepsake?`,zh:`我能留著它吗？`},Id_DisplayTextPerState_318:{en:`That's not my fingerprint.`,zh:`这不是我的指纹。`},Id_DisplayTextPerState_319:{en:`That's Dolores' bomb. Did they use it, then?`,zh:`这是桃乐丽思的炸弹。他们打算怎么做？`},Id_DisplayText_Default_77:{en:`I am not sure what you want from me.`,zh:`不知道你想从我身上知道什么。`},Id_DisplayText_Default_78:{en:`I am not sure I understood the question.`,zh:`我不明白你的问题。`},Id_DisplayText_Default_79:{en:`Could you send the question to my secretary by mail? I'll do my best to reply as quick as I can.`,zh:`请把问题电邮给我的秘书。我会尽快回复。`},Id_DisplayTextPerState_320:{en:`I heard the rumors, indeed. But I'm convinced that it's a scarecrow. The problem in our society is the broader social disease of terrorism, not some concentrated and mysterious conspiracy nobody knows anything about.`,zh:`我听说过关于它的谣言，但深信只是捕风捉影。实实在在威胁社会的癌症是恐怖分子，并非空穴来风的神秘阴谋组织。`},Id_DisplayTextPerState_321:{en:`I don't know much about explosives, but this looks serious indeed.`,zh:`我不懂爆裂物，但这似乎威力强大。`},Id_DisplayTextPerState_322:{en:`So you believe I am targeted by terrorists? I am not really surprised. They must quite shudder at the thought that my proposed legislation could get through. `,zh:`你相信我是恐怖分子的目标吗？我可不意外。他们得知我提出的法案将要通过，肯定怕得浑身发抖，拼死阻止。 `},Id_DisplayTextPerState_323:{en:`Well, yes, I stepped out for a moment to answer the phone. I don't remember who was calling--I confess that almost perishing in an explosion quite dominates my memories.`,zh:`对，我出外接了一阵子电话。忘了是谁打来，爆炸让我脑子一片混乱。`},Id_DisplayTextPerState_324:{en:`The bomb was hidden in the plants. It would be useful to know who brought them.`,zh:`炸弹藏在植物里，应该查一下是谁送来的。`},Id_DisplayTextPerState_325:{en:`I hear far too much about this organization and hope that you or MI5 will quickly put an end to their story. Such a threat to our security cannot be allowed to persist.`,zh:`我听过太多关于这组织的事情，希望你或国安局会迅速把它们绳之于法。不能任由它们威胁社会治安。`},Id_DisplayText_Default_80:{en:`No, I am sorry, I don't know what to tell you.`,zh:`抱歉，我不知道有什么可以告诉你。`},Id_DisplayText_Default_81:{en:`I am going to have to cut this short. I still have quite a lot to do. Do you have any remaining questions?`,zh:`长话短说，我有很多事情要处理。你还有什么问题？`},Id_DisplayText_Default_82:{en:`I have nothing special to say about this.`,zh:`我没有什么能够告诉你。`},Id_DisplayTextPerState_326:{en:`I am counting on you to find the target quickly. Surely we don't need a bombing attack <itm=11>.`,zh:`我期望你尽快找出目标，并且阻止炸弹袭击<itm=11>。`},Id_DisplayTextPerState_327:{en:`Wait, are you telling me that you found a file from MI5 on the premises of a bomber? That's particularly serious. Your case is taking a very tricky turn.`,zh:`什么？你说炸弹犯身上找到国安局的档案？此事非同小可，把整件案弄得扑朔迷离。`},Id_DisplayTextPerState_328:{en:`Thank God you were there. If that bomb had detonated, we would have lost many good people, and that bloody security law could very well have passed and turned our country into a full-blown dictatorship.`,zh:`感谢上帝，你找到它了。要是爆炸了，许多无辜的人就会丧生，那条该死的保安条例很可能就会通过，把我们的国家变成彻底独裁。`},Id_DisplayTextPerState_329:{en:`Ah yes, thank you, I had left it behind in the panic.
So you learned about the appointment with Goldman. Indeed, I take advantage of his fair to discreetly meet with some financial professionals. I know you will keep this quiet.
`,zh:`对，谢谢你，慌忙之中我弄丢了。

所以你知道我跟戈德曼约了见面。没错，我趁展览的时机跟商界精英秘密会面。我相信你也懂得守密的。"
`},Id_DisplayTextPerState_330:{en:`I will make sure I find out who brought these plants.`,zh:`我保证会找出这是谁送来。`},Id_DisplayTextPerState_331:{en:`This phone call is a convenient coincidence, especially when you know how important this session is to the Duke.`,zh:`这电话来得真是时候，尤其是对公爵来说，这场会议事关重大。`},Id_DisplayTextPerState_333:{en:`That's the daughter of the French Ambassador? She was very lucky.`,zh:`法国大使的女儿？她真幸运。`},Id_DisplayTextPerState_334:{en:`I mostly heard about it in the papers. What a horrible case.`,zh:`我在报上读过她的案件，真可怕。`},Id_DisplayText_Default_83:{en:`I have many subjects. Alas, I cannot know all of them personally.`,zh:`我有许多臣民，当然不能一一记住。`},Id_DisplayText_Default_84:{en:`I don't think I can help you with this person.`,zh:`对此我帮不上忙。`},Id_DisplayText_Default_85:{en:`No, I don't know who this is.`,zh:`我不认识这人。`},Id_DisplayTextPerState_335:{en:`My God, he's dead. What a dreadful loss. This only confirms my concerns about this M Organization.`,zh:`天哪，他死了，多么遗憾，使我更确信M组织异常危险。`},Id_DisplayTextPerState_336:{en:`I never had the opportunity to meet your Chief Officer, but the quality of his annual statistics was pretty conclusive.`,zh:`我从没见过你的局长，但他每年给的报告数据非常踏实。`},Id_DisplayTextPerState_337:{en:`The French Ambassador. She's a very skilled politician. I don't know how the Duke of Windsor <char=27> managed to convince her to support him and his projects.`,zh:`法国大使是名非常老练的政治家。我不晓得温莎公爵<char=27>怎样说服她支持自己的法案。`},Id_DisplayTextPerState_338:{en:`A wonderful woman, I really like talking to her. She's the one who talked to me about you after you questioned her. I have absolute confidence in her.`,zh:`了不起的女性，我喜欢跟她谈话。她跟你谈过之后来跟我提起你。我对她无比信任。`},Id_DisplayTextPerState_339:{en:`I am going to live here until after my engagement ceremony. Don't hesitate to come back to see me as soon as you believe you know who could be the head of this organization. We must put an end to this.`,zh:`我会住在这里直到订婚典礼。若你有任何关于M组织的头绪，随时再来找我，我们一定要终结它。`},Id_DisplayTextPerState_340:{en:`A formidable business man. The gentry has long learned to be wary of the bourgeoisie, those newly rich people who don't understand the world around them and believe they are more important than they are.`,zh:`野心勃勃的商人。士绅们必须好好防备资产家，这些窜起的暴发户明明不认识身边的世界，却自傲自大。`},Id_DisplayTextPerState_341:{en:`Poor girl. I hope her mother will find her.`,zh:`可怜的女孩，希望她的母亲找到她。`},Id_DisplayTextPerState_342:{en:`You did a great job in that case. I immediately knew you could be trusted.`,zh:`这案子你办得很好，我马上就知道你是可靠的。`},Id_DisplayText_Default_86:{en:`If I can help you, I will be happy to do so, but I am afraid your question is out of my expertise.`,zh:`我帮得到的事情，当然很乐意回答。不过恐怕你问的并非我所知。`},Id_DisplayText_Default_87:{en:`I am afraid I don't know what to tell you.`,zh:`我不知道有什么可以告诉你。`},Id_DisplayTextPerState_343:{en:`I have been hearing rumors about this group for too long. I got wind of your investigation, of that organ trafficking. All this must stop. I will do all that I can, but I need your help. Find out who is leading this organization for me!`,zh:`我很久以前已经听过这组织的传言。我也听说了你牵涉什么器官偷运的案件。这必须杜绝，力所能及的我都会做，但也需要你帮忙。帮我找出它们的首领！`},Id_DisplayTextPerState_344:{en:`A bomb... Do you know their target? Do you think they could be targeting my engagement ceremony?`,zh:`炸弹……你知道他们的目标吗？是我的订婚典礼吗？`},Id_DisplayTextPerState_345:{en:`You believe they will come after the Duke? I didn't think his law would scare people that much. In any case, I am concerned that MI5 is not as secure as it should be.`,zh:`你觉得他们的目标是公爵吗？我不认为他的法案真的那么可怕。但是值得担忧的是国安局竟然不可靠。`},Id_DisplayTextPerState_347:{en:`Well, well... Do you happen to know the nature of that call? What made him leave the room at such an important time? `,zh:`呵呵……你知道那通电话的内容吗？为什么在重要的会议中离开那房间？ `},Id_DisplayTextPerState_348:{en:`I knew I was right to trust you. This new failure must have weakened the organization. Now is the time to strike.`,zh:`我知道你是可信的。这次计谋不能得逞，一定削弱了该组织。是时候反击了。`},Id_DisplayTextPerState_349:{en:`An attack in our heart. That's the last thing we needed. Please tell me if you think you found our culprit, but I am afraid I might now be powerless to stop him.`,zh:`瞄准要害的恐攻，我们正需要这件情报。若你认为已经找到真凶，请告诉我。但是恐怕我现在没有能力阻止他。`},Id_DisplayTextPerState_350:{en:`Cameras can be made to mean anything, but I'm glad I am not him right now.`,zh:`摄影机可以塑造事实，但现在我很庆幸影片里的不是我。`},Id_DisplayTextPerState_351:{en:`I would never have allowed that. My heart is bleeding to see my country under attack like that.`,zh:`我决不允许这种事情。得悉我国被这样攻击，让我心痛不已。`},Id_DisplayTextPerState_352:{en:`I would never have allowed that. I thank you for preventing the worst from happening.`,zh:`我决不允许这种事情。感谢你阻止了这件事。`},Id_DisplayText_Default_88:{en:`I have files on everyone, but I don't know them by heart.`,zh:`我有每个人的档案，但大部分我都不认识。`},Id_DisplayText_Default_89:{en:`I would need to check, but do you really think it is important?`,zh:`我可以查一下，但真的有用吗？`},Id_DisplayText_Default_90:{en:`Right, I really do have a lot of work to do. Do you have another question?`,zh:`我差不多是时候回去工作了，你还有什么要问？`},Id_DisplayTextPerState_353:{en:`I never met your Chief Officer, but I have heard much praise about his career.`,zh:`我没见过你的局长，但听说很多人对他工作表现都赞赏有加。`},Id_DisplayTextPerState_354:{en:`I am sorry for your loss. Losing such a competent public servant is always a tragedy.`,zh:`我感到很难过。他是非常有才干的公仆，失去他实在令人惋惜。`},Id_DisplayTextPerState_355:{en:`Yes, we were monitoring the ambassador before the kidnapping happened, since her daughter's transplant. We knew she was working for the M Organization <itm=02>.`,zh:`对，在绑架案发生前我们已经在留意法国大使，那是因为她女儿的移植手术。我们知道她为M组织<itm=02>工作。`},Id_DisplayTextPerState_356:{en:`Roger Gaiman was our main lead to dismantle the M Organization <itm=02>. Now that he's dead, we have lost many years of undercover and monitoring work. No need to say that I won't thank you for that.`,zh:`我们原本指望从罗杰·盖曼著手，瓦解M组织<itm=02>。现在他死了，我们也丧失掉多年来埋伏的卧底和监控网路。实在多亏你。`},Id_DisplayTextPerState_357:{en:`The Duke's worldview is a bit too black and white. And I have the feeling that he would like to be in my position, but that won't happen if he continues to haunt the Parliament, and that's much better for him.`,zh:`公爵看世界太过非黑即白，而且我感觉他有意取我而代之。不过要是他继续在国会周旋，就不能过来接手，而且这样对他也更好。`},Id_DisplayTextPerState_358:{en:`I hear she's a very competent woman. As far as I'm concerned, I find her a bit weak.`,zh:`她是非常能干的女性。我觉得她有点太柔弱。`},Id_DisplayTextPerState_359:{en:`He is a Prince. I have no opinion about him. All that is required of him is to have a beautiful wedding and children that dazzle the whole world.`,zh:`我国王子，我对他没有看法。他需要做的就是举行美妙的婚礼，生下小孩，向全世界夸耀。`},Id_DisplayTextPerState_360:{en:`An old-style army officer, stalwart in his sense of honor. Our old institutions need people like him to work.`,zh:`老派军官，极忠于自己的荣誉感。那些过时机构需要这种人来运作。`},Id_DisplayTextPerState_361:{en:`A good agent who could have died because of you. If I am not mistaken, he was involved in one of your cases, and you exposed him in your report. That's not very smart. `,zh:`一名好特务，原本会因你而死。据我所知，你其中一宗调查牵涉到他，而报告中曝露了他的身份。这可不聪明。 `},Id_DisplayTextPerState_363:{en:`So you're the one snooping around and endangering undercover agents? What are you doing in my barracks?`,zh:`就是你到处八卦，危害卧底特务吗？来我的军营做什么？`},Id_DisplayTextPerState_364:{en:`Oh... I am sorry to hear that. Do you have any leads on the culprit?`,zh:`这令人难过……有嫌疑犯的踪迹吗？`},Id_DisplayTextPerState_365:{en:`You think Sanders may be involved in this case? I would only be half surprised, but it would be a great insult to our barracks.`,zh:`你认为桑德斯参与了此案？尽管我不感讶异，但足以使我这军营蒙羞。`},Id_DisplayTextPerState_366:{en:`No, I don't know who this person is.`,zh:`我不认识这人。`},Id_DisplayTextPerState_367:{en:`I can't remember all the people I meet. Be serious.`,zh:`老实跟你说，我记不住全部见过的人。`},Id_DisplayText_Default_91:{en:`No, I don't know.`,zh:`我不认识。`},Id_DisplayText_Default_92:{en:`Obviously, I would do my best to help you if I knew who you were talking about.`,zh:`要是我知道你在说什么，一定会尽力协助你。`},Id_DisplayText_Default_93:{en:`My secretary usually handles that, understand?`,zh:`让我的秘书负责处理，明白吗？`},Id_DisplayTextPerState_368:{en:`That's your Chief Officer. I'm sure he's a wonderful man.`,zh:`你们的局长，我肯定他十分可敬。`},Id_DisplayTextPerState_369:{en:`That's dreadful but it confirms once more how much my reform is needed.`,zh:`这事情非常可怕，但也印证了我的改革势在必行。`},Id_DisplayTextPerState_370:{en:`The French ambassador. I had the opportunity to work with her a few times. A very efficient woman.`,zh:`法国大使，我见过她好几次，办事效率优秀的女性。`},Id_DisplayTextPerState_371:{en:`I don't think I know her.`,zh:`我不认识她。`},Id_DisplayTextPerState_372:{en:`An excellent financial professional, a paragon. I have a few deals going on with him.`,zh:`出众的商界精英，我们的翘楚。我有几件事正在跟他一同办理。`},Id_DisplayTextPerState_373:{en:`I don't have much time at the moment. My legislation proposal will be examined tomorrow and I still have a lot to do.`,zh:`现在我时间不多，明天就要审议我的法案，有很多工作。`},Id_DisplayTextPerState_374:{en:`Mrs. Clarke and I don't have the same vision of the world. What she believes is a new vision, I  call naivety.`,zh:`克拉克女士和我对世界的看法不同。她以为自己有新视野，我看来只是天真。`},Id_DisplayTextPerState_375:{en:`Family is important. You should always be able to count on it. I won't be able to attend his engagement ceremony, but the wedding is what really matters, isn't it?`,zh:`家庭很重要，家人总是能依靠的。我没办法参加他的订婚典礼，但婚礼才重要，不是吗？`},Id_DisplayTextPerState_376:{en:`Our country needs reliable men like him.`,zh:`我国需要这般可靠的人。`},Id_DisplayTextPerState_377:{en:`I never really had the opportunity to work with MI5, so I know very little about its director.`,zh:`我从未跟国安局共事，对他们的局长所知甚少。`},Id_DisplayTextPerState_378:{en:`Typically I am the one asking the questions. I'm not accustomed to answering them. Don't mistake your enemy, detectives.`,zh:`通常是我问问题，不是回答。别错认敌人。`},Id_DisplayTextPerState_379:{en:`Mrs. Callum has been secretary to the MI5 Director's for longer than I could say. I believe I am her fourth director--that should tell you how competent that woman is.`,zh:`卡琳太太在国安局担任局长秘书已经好久了。我应该是她服务的第四任，你看得出她有多么能干了。`},Id_DisplayTextPerState_380:{en:`We're watching him. He is indeed an excellent candidate for the leadership of the M Organization.`,zh:`我们在监视他，因为他极有可能是M组织首领。`},Id_DisplayTextPerState_381:{en:`Well... I guess she is in the best position to withhold information from me. But how can you imagine that a mere secretary could be involved in such a business?`,zh:`的确她有绝佳的机会从我手上拿取资料，但区区秘书怎么会参与这种事情？`},Id_DisplayTextPerState_382:{en:`A remarkable man. He always acts legally, but shows every day how powerful you can get when you use the system in your own interest.`,zh:`厉害的男人，行事永远守法，不过把体制运用得炉火纯青，展示了善用体制为自己的利益服务有多强。`},Id_DisplayTextPerState_383:{en:`You did a good job in that case.`,zh:`这案子你做得很好。`},Id_DisplayTextPerState_384:{en:`If you had found that girl, surely this case would have been easier.`,zh:`要是你找到小女孩，这案件就容易多了。`},Id_DisplayText_Default_94:{en:`I can't or won't tell you anything, and that's my right.`,zh:`我有权不回答你任何问题。`},Id_DisplayText_Default_95:{en:`I have already been kind enough to answer your questions. Try not to waste my time.`,zh:`受够你这些问题了。别浪费我时间。`},Id_DisplayText_Default_96:{en:`No, I don't know what you want me to tell you and I don't like wasting my time.`,zh:`不知道你想知道什么，我不喜欢浪费时间。`},Id_DisplayTextPerState_385:{en:`We are monitoring potential threats. If the matter is serious, it is on our radar.`,zh:`我们正监控潜在威胁。要是事关重大，我们就会马上知道。`},Id_DisplayTextPerState_386:{en:`This shouldn't be in your hands. That's particularly worrying, and if there is a leak, I will take care of it personally.`,zh:`这不应该出现在你手上。此事令人担忧，要是真的泄露机密，我会亲自处理。`},Id_DisplayTextPerState_387:{en:`This behavior is suspicious to say the least, but it may be a mere coincidence.`,zh:`这行为十分可疑，不过也可能只是巧合。`},Id_DisplayTextPerState_388:{en:`I already completed my own investigation. Initially, Louise Blanche <char=15> was supposed to offer several plants to the Parliament on behalf of France. It seems that the matter was postponed following an administrative mix-up. @I do have the name of the company that ended up bringing those plants, but the sponsor doesn't exist.`,zh:`我自己调查过了。当初露易蕬·布兰奇<char=15>本该以法国的名义赠送这些植物给国会，但出于行政疏忽延迟了。@我有货运公司的资料，但没有赠送者的资料。`},Id_DisplayTextPerState_390:{en:`I have to admit I didn't think you were that efficient. Perhaps you could be useful to us after all.`,zh:`我必须承认本来对你毫无期望。也许其实你能有一点功用。`},Id_DisplayTextPerState_391:{en:`This explosion calls everything into question. I have to hurry back to the office.`,zh:`这爆炸案引发了无数问题。我要赶回办公室。`},Id_DisplayTextPerState_392:{en:`Didn't I tell you there was something wrong with that bloke?`,zh:`我没告诉过你那人不对劲吗？`},Id_DisplayTextPerState_393:{en:`I'm glad I could help you. But still, it's a pity, it could have reshuffled the cards and given power back to the people.`,zh:`帮到你我很开心，不过同时很惋惜，因为本来可以让社会大洗牌，还权于民。`},Id_DisplayTextPerState_394:{en:`Wow, they blew up Parliament with my bomb. I know I shouldn't be, but I have to admit I am a wee bit proud.`,zh:`哗！他们用我的炸弹炸掉了国会。我知道这样想并不对，不过还是感到一丝自豪。`},Id_DisplayTextPerState_395:{en:`Yeah, he's the one who put me in touch with the M Organization. He was a top gun--pity they had to silence him. So don't be surprised if I don't talk much.`,zh:`对，他帮我跟M组织牵线。他是组织里面的精英，难怪被灭口。要是我保持沉默，你也知道为什么了。`},Id_DisplayTextPerState_396:{en:`You won't prevent anything from happening. We are much smarter than you can imagine.`,zh:`你不能阻止任何事情，我们远比你想的要聪明。`},Id_DisplayTextPerState_397:{en:`That's the Prime Minister. What more do you want me to tell you? I'm not much into politics.`,zh:`你要我告诉你关于首相的什么？我不关心政治。`},Id_DisplayTextPerState_398:{en:`Well, he's a Duke. Not quite the kind of thing I am interested in.`,zh:`他是公爵，我不在意。`},Id_DisplayTextPerState_399:{en:`The royal trophy. He is going to have a wonderful engagement ceremony, everyone will be happy.`,zh:`皇家的象征。他将举行梦幻的订婚典礼。大众都会很愉快。`},Id_DisplayTextPerState_400:{en:`Why do you think I would know her?`,zh:`你怎么认为我认识她？`},Id_DisplayTextPerState_401:{en:`Yeah, I may have worked with her a bit. But you can't believe everything chicks tell you, they are born liars.`,zh:`对，也许我跟她合作过一阵子，但你不能相信那妞说的任何话，她们天生就是骗子。`},Id_DisplayTextPerState_402:{en:`She did what she had to do. I won't tell you anything more. It's too late for you to prevent things from happening now.`,zh:`她做了要做的事情。我不会再说什么。你想要阻止我们的事情，已经太迟了。`},Id_DisplayTextPerState_403:{en:`Private Sanders at your service. Did I run a red light or something?`,zh:`桑德斯一等兵报到。我是闯了红灯还是什么。`},Id_DisplayTextPerState_404:{en:`No need for me to call my barrister. It's not like I'm going to say anything. Nothing you can do to me will be worse than what the Organization will do if I betray them.`,zh:`不需要为我传唤律师，我不会说什么。你会对我做的事情，怎样也不会比背叛组织更糟的。`},Id_DisplayTextPerState_405:{en:`Yeah, yeah, I've been a bad boy, I got it. If you want to put me in jail, just go ahead. I'll be back out of there before you even turn around.`,zh:`对，对，我是个坏孩子。随便把我关进监狱吧。在你转身之前，我就会出来了。`},Id_DisplayTextPerState_406:{en:`She snitched on me? I should have known it--never trust a junkie.`,zh:`她出卖了我？我就知道——别相信垃圾。`},Id_DisplayText_Default_97:{en:`One can't know everyone.`,zh:`没人能认识所有人。`},Id_DisplayText_Default_98:{en:`I don't think I met this person, or else they didn't make an impression on me.`,zh:`我应该没见过这人，没什么印象。`},Id_DisplayTextPerState_407:{en:`The French ambassador. I've had the opportunity to follow her political career a bit, as well as her difficulties with her daughter.`,zh:`法国大使，我工作上稍稍接触过，她的政治事务，还有在她女儿被绑架的难关。`},Id_DisplayTextPerState_408:{en:`One of our main suspects regarding the M Organization <itm=02>. His loss is tragic, as we're convinced he could have taken us to their leader.`,zh:`我们在M组织<itm=02>里最大一条线索，失去他是重大打击，因为他本来可以引荐我们见到首领。`},Id_DisplayTextPerState_409:{en:`One of our most prominent political figures at the moment. In other circumstances he could have been King of England.`,zh:`当前国内风头最盛的政治人物。要是当时历史走向另一个方向，他也许就当上了英国国王。`},Id_DisplayTextPerState_410:{en:`A woman who managed to prove herself. She fully deserves her position.`,zh:`她的政绩有目共睹，担得起岗位。`},Id_DisplayTextPerState_411:{en:`His engagement ceremony is soon, and I can't wait to see his fiancée's dress.`,zh:`他的订婚典礼将近，我迫不及待想看未婚妻的礼服。`},Id_DisplayTextPerState_412:{en:`Mr. McVeill looks impressively young his face hides his true years of experience .  Have no doubt that he is a very competent person.`,zh:`麦威尔先生看似年轻，不过其实资历已深，无疑才貌双全。`},Id_DisplayTextPerState_413:{en:`You can call me Cynthia. I am lucky I attained this key position in MI5, which allows me to defend my country. I know a lot of things but I am not allowed to say anything.`,zh:`你可以叫我辛西雅，有幸担任国安局里的关键岗位，让我得以保卫国家。我知道很多事情，但不得透露。`},Id_DisplayTextPerState_414:{en:`A brilliant businessman. He's the pride of our country.`,zh:`精明商人，我国的荣耀。`},Id_DisplayTextPerState_415:{en:`The ambassador's daughter. What happened to her is terrible.`,zh:`大使的女儿，遭遇过可怕的经历。`},Id_DisplayText_Default_99:{en:`I don't know what this is about.`,zh:`不知道这是什么。`},Id_DisplayText_Default_100:{en:`You think it has something to do with your investigation? I don't know what to tell you.`,zh:`你认为跟调查有关吗？我不知道应该告诉你什么。`},Id_DisplayText_Default_101:{en:`No matter how much I think about it, I don't know what to tell you.`,zh:`我想了很久，也不知道有什么可以告诉你。`},Id_DisplayTextPerState_416:{en:`A complex case you're mixed up in. MI5 never had to face such a powerful adversary.`,zh:`你卷进了复杂的案件。国安局有史以来的劲敌。`},Id_DisplayTextPerState_417:{en:`Oh my God, you think they're going to blow up something? I hope it won't be the Prince's <char=29> engagement ceremony!`,zh:`天哪！你觉得它们想炸掉什么？我希望不是王子<char=29>的订婚典礼！`},Id_DisplayTextPerState_419:{en:`The Director is too busy to see anyone.`,zh:`局长很忙，没空见人。`},Id_DisplayTextPerState_420:{en:`Sorry, but with what just happened, the Director can't see anyone anymore.`,zh:`抱歉，在刚刚的事情发生后，局长没空见任何人。`},Id_DisplayTextPerState_421:{en:`The Director doesn't seem to be here anymore.`,zh:`局长不在。`},Id_DisplayTextPerState_422:{en:`Surprising. But you know how it is, images can be made to say anything nowadays. There is nothing like a real investigation.`,zh:`这令人惊讶，但你也明白，这个时代影片也可以用来捏造任何故事，并非真正的证据。`},Id_DisplayTextPerState_423:{en:`We are looking for the sponsor. Do not worry, they will be arrested as soon as we trace them.`,zh:`我们正追寻捐赠者。别担心，一旦找到线索，很快就会缉拿归案。`},Id_DisplayTextPerState_424:{en:`You certainly are quite resourceful. You've saved countless lives today, but the M Organization is still active and they just proved how powerful they are.`,zh:`你确实有点斤两，今天拯救了无数生命，不过M组织依然活跃，也证明了他们实在厉害。`},Id_DisplayTextPerState_425:{en:`We might not be in this situation if you hadn't been in our way. I'm going to ask you to let the professionals do their work now.`,zh:`如果没有你，我们将无法把握这个机会。请你让专业人员开始工作吧。`},Id_Ending_Final_Solution_Text_0:{en:`As the leader of the English branch of the M Organization, the Duke of Windsor <char=27> had but one purpose: take back the throne his father had lost.@ His plan was simple: pass a totalitarian law and oust the Royal Family. If his law had no chance to pass under normal circumstances, he counted on his bomb to dispose of his opponents and beyond that to elicit strong emotions that would draw people to support his actions without consideration.@ Once he became the symbol of the fight against terrorism, he would have had a free hand to pass any legislation he wanted, and become the virtual dictator of England.@ Cynthia Cullum <char=18> helped him to choose Dolores Kelly <char=19> as the bomb maker.@ She was specially selected to cast a shadow of suspicion on the IRA. Mike Sanders <char=23> was supposed to leave enough evidence to trace it back to the girl's body. @ Kevin Doyle <char=47> was only used to manipulate the Chief Officer and facilitate the murder of Roger Gaiman <char=35>, but his involvement ended up complicating matters, as the Chief Officer couldn't silence his remorse and he found his son.@ Mike had to kill him while Kevin and Dolores was escaping in a squat in Whitechapel. <loc=I>`,zh:`温莎公爵<char=27>作为M组织英国分支的首领，目标只有一个：取回父亲失去的皇位。@他的计划很简单：通过一条专制法案并排挤皇室。本来他的法案很难通过，于是策划炸弹袭击，一来除掉政敌，同时煽动公众情绪来盲目支持自己的号召。@ 要是他成了打击恐怖主义的象征，就能轻而易举通过任何法案，登上独裁者之位。@辛西雅·卡琳<char=18>帮助他选择桃乐丽思·凯莉<char=19>来制造炸弹。@这样便可把罪名推给爱尔兰共和军。迈克·桑德斯<char=23>本该留下足够证据嫁祸那女孩。@凯文·代尔<char=47>则是被用来操控局长，使得罗杰·盖曼<char=35>被杀。但是凯文涉足此事最终令事情变得复杂，因为局长对自己忙于工作感到歉疚，而自行去找回儿子。@迈克只能杀死他，与此同时凯文和桃乐丽思逃到白教堂一所非法占用居所<loc=I>。`},Id_Ending_FinalSummary_0:{en:`Congratulations detectives, you have just saved the United Kingdom from the corrupting influence of the M Organization. @ By defusing the bomb and accusing the Duke of Windsor <char=27>, you undermined his plan to seize power. His accomplice Cynthia Callum <char=18> was also charged with treason. @After years of conspiring in the shadows, the M Organization collapses like a house of cards, with henchmen like Mike Sanders revealing all they know to save themselves. @ The country can breathe at last, but there is no room for complacency: the M Organization is spread throughout the world, and its other members may one day want to avenge this outrage...`,zh:`恭喜你们阻止了英国落入M组织的魔掌。@你们拆除了炸弹，起诉了温莎公爵<char=27>，阻止了对方窃取权力。他的同党辛西雅·卡琳<char=18>同样以叛国罪被审问。@潜藏多年的M组织终于土崩瓦解，而迈克·桑德斯等从犯坦白一切以求自保。@这个国家总算可以松一口气。不过你们不可自满，因为M组织爪牙满布全球，其同党也许正怒火中烧，谋划复仇……`},Id_Ending_FinalSummary_1:{en:`Pity, detective--your suspicions were right but you are too late. The Duke of Windsor just carried out his plan. With this attack, the Duke not only disposed of his opponents, but also now poses as a victim of his own plot, making him the man of the hour. @ His grab for power disguised as legislation is adopted in emergency session to protect the country from the devastating impact of the IRA and of terrorism. For all intents, the Duke has become the new dictator of the nation.@ Perhaps one day you'll gather enough evidence to allow the Prince to bring him down, but today, he is much too powerful for you. You will have to remain discreet--the M Organization has won this battle.`,zh:`可惜，你们怀疑得没错，但行动太慢。温莎公爵已经执行了计划。这次袭击不仅排除了政敌，更自编自导自演，把自己塑造成受害者，同时是拯救国家的关键人物。@他以立法机关作掩饰，提出紧急状态法案并且被采纳，美其名曰保卫国家，对应爱尔兰共和军与恐怖主义的威胁，最终当上了这个国家新的独裁者。@也许某天你能搜集足够证据，把他拉下台，不过今天，他掌握太庞大的权力，你只好隐姓埋名——M组织棋高一着。`},Id_Ending_FinalSummary_2:{en:`Congratulations detectives, you just saved the United Kingdom and undermined the M Organization's plan. @ By defusing the bomb, you saved many lives, but the M Organization has not been dismantled. In spite of your victory, their influence seems to be growing in England and throughout the world!`,zh:`恭喜，你刚刚拯救了英国，阻止了M组织的计划，@你拆除了炸弹，救活了许多条性命，不过不足以瓦解M组织。这次你们胜利了，不过M组织的影响力在英国以至全世界都渐渐增强。`},Id_DisplayText_Default_102:{en:`I didn't find anything interesting, sorry.`,zh:`抱歉，我找不到有用的资讯。`},Id_DisplayText_Default_103:{en:`No matter how much I dig, I can't find any useful information.`,zh:`无论我怎么挖，都掌握不到任何有用的资讯。`},Id_DisplayText_Default_104:{en:`It looks like I won't be able to help you this time.`,zh:`看来这次我帮不上忙。`},Id_DisplayTextPerState_426:{en:`I told you he was shady. If he works for MI5, I finally understand why I found his information suspicious.`,zh:`我告诉过你他行事隐晦。要是他为国安局工作，那么我终于明白为什么他的资料非常可疑。`},Id_DisplayTextPerState_427:{en:`I still say that this bloke is hiding something. I don't like the look of him, and I'm not just saying that because he looks like a serial killer.`,zh:`我会说这人还在隐瞒一些事情。我不喜欢他的样子，他不仅仅是看起来像一名连环杀手。`},Id_DisplayTextPerState_428:{en:`You did a good job with her. I hope she'll remember it.`,zh:`你对她有很大恩情，希望她不会忘记。`},Id_DisplayTextPerState_429:{en:`I don't have much useful information and I'm afraid that after her daughter's case, she might be reluctant to talk to you.`,zh:`我没有多少有用的资讯，但是经过她女儿一事，看来她不愿意跟你交谈。`},Id_DisplayTextPerState_430:{en:`A pity he's dead. He probably had a lot of things to tell us--because I'm not finding anything on my side. His Army file is classified, and there's no other information apart from a bad espionage novel he published.`,zh:`真可惜他死了，本来可以让我们获得很多情报，因为我查不到多少资料。只证实了他的确曾经从军，此外就没有了。除了他出版过一本差劲的间谍小说。`},Id_DisplayTextPerState_431:{en:`He is a legend, the Duke. Did you know that his father was accused of collaborating with the Nazis? That's why he had to abdicate and hide in France: we didn't want him here anymore. @ With such a legacy, it's not surprising that the bloke is struggling to appear credible. If you are looking for him, he will probably be at Parliament in Westminster <loc=A>.`,zh:`公爵是个传说。你知道他父亲被指勾结纳粹吗？所以只好退位避居法国。这国家不需要他。@有这样的家族历史，难怪他用尽方法博取信任。要是你想找他，可以到西敏的国会大楼<loc=A>。`},Id_DisplayTextPerState_432:{en:`A very popular woman. Only the upper crust complains about her. The people, on the other hand, are delighted with everything she's already accomplished.`,zh:`非常著名的女性。只有上流阶级对她有怨言。一般大众对她的政绩显得非常满意。`},Id_DisplayTextPerState_433:{en:`It's going to be his engagement ceremony soon. I think I'll watch the online livestream. ...in the background--it won't interfere with my work, I promise.`,zh:`他的订婚典礼将近，我应该会看网上直播……在背景播放而已。我承诺不会影响工作。`},Id_DisplayTextPerState_434:{en:`An old Army hand. He took part in several conflicts, and his record is exemplary. Treat him cautiously if you question him, because someone with such impeccable service record usually has a lot of influence.`,zh:`老派军官，参与过多场武装冲突，战绩彪炳。小心问他问题，因为有如此辉煌往绩的人，影响力也必定非同小可。`},Id_DisplayTextPerState_435:{en:`Such a young bloke at the head of MI5, it's crazy. If you listen to online forums, everyone thinks he blackmailed the previous director to steal his place. Think about it--he's not even an experienced agent, just a bureaucrat.`,zh:`这样年轻伙子当上国安局局长，真是疯了。如果你上网查一下论坛，大家都认为他勒索前任局长以取而代之。你想想看，他可不是资深特务，只是一个行政官。`},Id_DisplayTextPerState_436:{en:`Not much information about him. He's apparently been involved in small cases: fights, public drunkenness. I have the feeling he was also involved in the Gaiman <char=35> case but as his records are sealed... @ If you want to find out more, you'll probably find him at his barracks in Southwark <loc=J>.`,zh:`没有多少关于他的资料，明显他牵涉轻微犯罪，包括打斗、酗酒滋事。我感觉他插手了盖曼<char=35>的案件，但记录被封存保密……@要是你想深入了解，最好前往位于南华克的军营<loc=J>找他。`},Id_DisplayTextPerState_437:{en:`Our nation's pride. Or so I hear. One thing is for sure, he has done very well for himself and has become one of the most influential men in this country. There is much talk about his financial fair, which will take place in the City <loc=B>.`,zh:`听说是本国的光荣。的确，他能人所不能，成为了这个国家影响力超凡的人。他将要举办一个财经展览，位置在市中心<loc=B>。`},Id_DisplayTextPerState_438:{en:`I hope you're not counting on me to find her?`,zh:`你不会指望我帮你找到她吧。`},Id_DisplayTextPerState_439:{en:`You did a great job in that case. The poor girl must have been terrified.`,zh:`这案件你做得很好，小女孩应该吓怕了。`},Id_DisplayTextPerState_440:{en:`The plants were delivered on the same morning by "Floralife". All the sponsor's details are false, even the bank details.`,zh:`这植物是今早由「丽花」送来的。所有付款人资料都是伪造的，包括银行资料。`},Id_DisplayTextPerState_441:{en:`Don't blame yourself, I wouldn't have done any better. It was a job for a demolitions expert.`,zh:`不要自责，我也无法做得更好。那本该是拆弹专家的工作。`},Id_DisplayTextPerState_442:{en:`I'm impressed! You can actually do anything. Please tell me you're not going to steal my job?`,zh:`你太棒了，根本万能天才！希望你不要抢走我的饭碗。`},Id_DisplayTextPerState_443:{en:`The video hasn't been tampered with, and it's 100% reliable. The Duke really did sneak out during the session.`,zh:`这段影片没有剪接，百分百可信。公爵的确在会议期间离开了。`},Id_DisplayTextPerState_444:{en:`It's a good thing you supported him. Together you have a chance to take down the M Organization.`,zh:`幸好你支援他了，因为你们一起可以拉倒M组织。`},Id_DisplayTextPerState_445:{en:`The ambassador is grateful to you. You can probably count on her to reveal what she knows.`,zh:`大使对你感恩戴德，很愿意告诉你自己知道的事情。`},Id_DisplayTextPerState_446:{en:`With the threat against her daughter remaining, I am not sure she will be willing to testify.`,zh:`她的女儿还未脱险，所以大使未必愿意合作。`},Id_DisplayTextPerState_447:{en:`The Duke is carrying his father's heavy legacy. He has to outdo himself in order to make people forget that his family was involved with the Nazis during the Second World War. If you are looking for him, you will probably find him attending Parliament in Westminster <loc=A>.`,zh:`公爵背负了父亲沉重的担子，因此要加倍努力，让人忘记其父在二战中与纳粹来往。要找他的话，可以到西敏的国会大楼<loc=A>。`},Id_DisplayTextPerState_448:{en:`A determined woman who has already contributed much to the country. She is very popular and brings a new vision to our politics.`,zh:`坚定的女性，全心为国奉献，非常有名，且为政坛注入新视野。`},Id_DisplayTextPerState_449:{en:`Everybody is talking about his engagement ceremony on Saturday, but rumor has it that he's a brilliant strategist and he could make a significant contribution to the nation if he got more involved.`,zh:`所有人都在谈论他星期六的订婚典礼，不过谣传这也是王子精明的政治把戏，以此争取曝光，显示对本国有所贡献。`},Id_DisplayTextPerState_450:{en:`An old-school man of honor. You can count on him but you have to be aware that he has priorities and the Army is at the top of his list.`,zh:`老派看重荣辱的人物，你可以请他帮忙，不过记得他心目中永远把军队放在首位。`},Id_DisplayTextPerState_451:{en:`I can only advise you to not make an enemy of him. If he attained his position at such a young age, it can only mean that Director McVeill is willing and able to do anything to serve his own interests. Fortunately, it appears he has the Crown's best interests at heart.`,zh:`我只能建议你不要与他为敌。他年纪轻轻能攀到这样的高位，只代表他为了自身利益可以不择手段。幸好他似乎同样惦记王室安危。`},Id_DisplayTextPerState_452:{en:`He's tough. You'll learn nothing from him unless you manage to catch him off guard. But he isn't as smart as he believes he is. He'll leak information. He must be at his barracks at Southwark <loc=J> if you want to interrogate him.`,zh:`他很倔强，除非人赃并获，否则他一定矢口否认。不过他自以为聪明，其实不是，所以会泄漏资讯。如果要盘问他，到南华克的军营<loc=J>就一定找得到。`},Id_DisplayTextPerState_453:{en:`To keep her position for so long, this woman must be determined and know a lot. Stay alert, she is not just a secretary.`,zh:`意志坚定的人才可以长期身居要职。小心，她不是寻常秘书。`},Id_DisplayTextPerState_454:{en:`Mr. Goldman is a rich and popular banker. He may look friendly, but he's someone who knows what he wants and will stop at nothing to get it. You will probably find him in his City premises <loc=B>.`,zh:`戈德曼先生是富有著名的银行家，看来友善，不过目标清晰，不达到就决不罢休。他不会轻易提供线索。你可以到他在市中心的企业<loc=B>找他。`},Id_DisplayTextPerState_455:{en:`Poor girl.`,zh:`可怜的女孩。`},Id_DisplayTextPerState_456:{en:`Talk to Carol Stern <char=22> about it--she'll probably be more cooperative.`,zh:`跟嘉璐·施坦<char=22>谈这件事吧，她会愿意合作的。`},Id_DisplayTextPerState_458:{en:`For him to leave the session, this call had to be a question of life or death, as the Duke has been fighting tooth and nail for his law for many months, and the moment is crucial.`,zh:`公爵好几个月都在拼生拼死推广他的法案，来到这样至关重要的时刻，这通电话一定关乎生死，才可以让他离席。`},Id_DisplayTextPerState_459:{en:`That's good work. The situation could have been critical if that bomb had detonated. But keep it up--we still don't know the actual purpose of this organization.`,zh:`做得好，要是引爆了，情况就无可挽回了。不过不要松懈，我们还搞不清楚M组织的目的。`},Id_DisplayTextPerState_460:{en:`You shouldn't blame yourself, you don't have time for that. We still don't know their actual goal!`,zh:`不要自责了，你没有时间能处理所有危机。我们还搞不清楚他们的真正目标！`},Id_DisplayTextPerState_461:{en:`We checked the whole video, and it hasn't been tampered with. Everything you can see on it is true: the Duke left the room before the explosion.`,zh:`检查过整段影片，并没有经过剪接，表示内容完全真实——公爵在爆炸前离开了房间。`},Id_DisplayTextPerState_462:{en:`There wasn't enough left to analyze anything.`,zh:`剩下的已经不足以分析。`},Id_DisplayTextPerState_463:{en:`It is clearly the bomb that was made by Dolores Kelly <char=19>--we found her fingerprints but no others. The bomber must have been wearing gloves.`,zh:`明显是桃乐丽思·凯莉<char=19>制造的炸弹，因为上面只有她的指纹。放炸弹的人带了手套。`},Id_DisplayText_Action_7:{en:`You just have time to dive into the hallway before the bomb explodes and destroys Parliament. Fortunately, there are no casualties.`,zh:`你调查到半途，炸弹爆炸，毁掉了国会大楼。幸好没人伤亡。`},Id_DisplayText_Action_8:{en:`An explosion rips through London, shaking the whole city. Parliament was just attacked, and much of the House of Lords has died in the blast.`,zh:`一场爆炸案席卷伦敦，撼动整座城市。国会大楼刚刚遭遇恐怖攻击，上议院多人罹难。`},Id_LocationState_Introduction_20:{en:`Panic rules. Firemen struggle to contain the flames. The Duke of Windsor <char=27>, one of the rare survivors of the tragedy, is watching the scene from afar.`,zh:`恐慌四处蔓延，消防员努力扑灭火灾。奇迹生还的温莎公爵<char=27>在远处眺望。`},Id_DisplayTextPerState_464:{en:`The Prime Minister is one of the first identified victims. The United Kingdom has just lost its rudder. `,zh:`首先证实逝世的是首相。英国刚失去了舵手。 `},Id_DisplayTextPerState_465:{en:`The Director of MI5 has not yet been found, but all the evidence would suggest that he is buried somewhere underneath the rubble.`,zh:`还没找到国安局局长，但种种迹象显示他被埋在瓦砾下。`},Id_DisplayTextPerState_466:{en:`You will probably have to wait for a new director, as it seems this one didn't make it out of the explosion.`,zh:`看来他没在这场爆炸案中生还，你要等待新任局长。`},Id_DisplayTextPerState_467:{en:`A terrible tragedy has befallen us all. We will have to find someone who is able to face the violence of the situation.`,zh:`可怕的惨剧降临了，我们必须找人带领我们应对暴力事件。`},Id_DisplayTextPerState_468:{en:`What can I do for you? Keep it short, I am very busy.`,zh:`有事吗？我很忙，长话短说。`},Id_LocationState_Introduction_21:{en:`When you arrive at the Parliament and the House of Lords, you see of the Duke of Windsor <char=27> in the middle of a discussion with other lords. A bit further down the corridor, the Prime Minister <char=21> is watching the scene gloomily.`,zh:`你来到国会大楼和上议院，看到温莎公爵<char=27>跟其他贵族谈得起劲，走廊不远处是冷眼旁观的首相<char=21>。`},Id_Item_Name_26:{en:`Tags`,zh:`标签`},Id_DisplayTextPerState_469:{en:`The walls are covered with tags, but none of them seem to be related to your case.`,zh:`墙上贴满标签，但看来跟你的案件完全无关。`},Id_DisplayText_Default_105:{en:`This person doesn't seem to be here.`,zh:`看来人不在这。`},Id_DisplayText_Default_106:{en:`There are many people here, but you do not find this person.`,zh:`这里很多人，但找不到这人。`},Id_DisplayTextPerState_470:{en:`Detectives? I didn't think I would see you again today. Are you here for the threats <itm=13> I received?`,zh:`侦探你好，没想到今天会再次见面。你是为了我收到的恐吓信<itm=13> 而来吗？`},Id_DisplayTextPerState_471:{en:`Seriously detectives? London's most prominent finance professionals are lining up to ask me questions and you think I have time for you?`,zh:`你认真吗？整个伦敦的商界代表排队找我，而你觉得我有时间回答你？`},Id_DisplayTextPerState_472:{en:`I will have to beg your leave: I am organizing a meeting tomorrow that is crucial to the economic policies of the United Kingdom. So unless you found out what is threatening that gathering, I don't really have time to talk to you.`,zh:`请你离开：我在筹备明天的会议，对英国经济政策至关重要。除非你找到任何事情可能危害这次会议，我真的没时间见你。`},Id_DisplayText_Default_107:{en:`You don't find anything like that here.`,zh:`在这里找不到这东西。`},Id_DisplayText_Default_108:{en:`You should probably look for this elsewhere.`,zh:`到别处找吧。`},Id_DisplayTextPerState_473:{en:`It is now or never, this organization must be taken down.`,zh:`现在是千载难逢的良机，必须捣破这组织。`},Id_DisplayTextPerState_474:{en:`We still have one day to find out what they are planning precisely. I am counting on you, we have a chance to destroy this organization completely.`,zh:`我们还有一天找出它们的计划。我全靠你一同彻底摧毁这组织。`},Id_DisplayTextPerState_475:{en:`I can never thank you enough for your support. Now that I know I can trust you, we can start dealing seriously with the M Organization <itm=02>.@ I intercepted a lot of useful information while I was undercover, but not enough to completely dismantle the group. The most promising lead I had was Roger Gaiman <char=35>, but he's dead now. @Still, the M Organization has something planned this Saturday and it must be prevented at all costs. I know for a fact that Gaiman sent Mike Sanders <char=23>, a soldier, to pick up a package in Ireland for that occasion. @ Colonel Trooper <char=24>, with whom I am in contact, confirmed that Sanders was back at his Southwark barracks <loc=J>.@ I will conclude this long speech by saying: do not trust anyone; the Organization is everywhere. Their big blow is on Saturday - we have to stop them, and fast!`,zh:`实在无比感激，现在我知道你是可靠的。我们可以开始合作对付M组织<itm=02>。@我还是卧底期间，截到了许多有用的情报，但还不足以瓦解整个集团。最可靠的线索是罗杰·盖曼<char=35>，但现在他已经死了。@不过M组织在本星期策划了大型事件，我们必须不惜代价阻止。我知道盖曼派了一名叫迈克·桑德斯<char=23>的士兵到爱尔兰，拿取这件阴谋所需物品。@我联络了翠普上校<char=24>，确认目前那个桑德斯已经回到南华克的军营<loc=J>。@总结是不要相信任何人，因为M组织的势力笼罩四周。星期六它们会重重出手，我们必须精准快速地阻止！`},Id_DisplayTextPerState_476:{en:`I guess you must be surprised. I couldn't tell you anything, but I tried to help you within the scope of my mission. I feel that I am at a standstill, and even though my superior doesn't wish to get you involved, I think you're trustworthy.@ I intercepted a lot of useful information while I was undercover, but not enough to completely dismantle the group. The most promising lead I had was Roger Gaiman <char=35>, but he is dead now. @Yet, the M Organization has something planned this Saturday and it must be prevented at all costs. I know for a fact that Gaiman sent Mike Sanders <char=23>, a soldier, to pick up a package in Ireland for that occasion. @ Colonel Trooper <char=24>, with whom I am in contact, confirmed that Sanders was back at his Southwark barracks <loc=J>.@ I will conclude this long speech by saying: do not trust anyone, the Organization is everywhere. Their big blow is on Saturday - we have to stop them, and fast!`,zh:`我猜你很意外吧。我不能告诉你更多内情，不过我尝试在任务范围里协助你。我感觉正在孤军作战，而即使我的上级不希望你插手，我依然认为你是可信的。@我截到了许多有用的资讯，但还不足以瓦解整个集团。最可靠的线索是罗杰·盖曼<char=35>，但现在他已经死了。@不过M组织在本星期策划了大型事件，我们必须不惜代价阻止。我知道盖曼派了一名叫迈克·桑德斯<char=23>的士兵到爱尔兰，拿取这件阴谋所需物品。@我联络了翠普上校<char=24>，确认目前那个桑德斯已经回到南华克的军营<loc=J>。@总结是不要相信任何人，因为M组织的势力笼罩四周。星期六它们会重重出手，我们必须精准快速地阻止！`},Id_DisplayTextPerState_477:{en:`I should have known you wouldn't hold your tongue, but you are lucky--I really need help and I think you are serious about bringing down the M Organization <itm=02>. @ I intercepted a lot of useful information while I was undercover, but not enough to completely dismantle the group. The most promising lead I had was Roger Gaiman <char=35>, but he is dead now. @Yet, the M Organization has something planned this Saturday and it must be prevented at all costs. I know for a fact that Gaiman sent Mike Sanders <char=23>, a soldier, to pick up a package in Ireland for that occasion. @ Colonel Trooper <char=24>, with whom I am in contact, confirmed that Sanders was back at his Southwark barracks <loc=J>.@ I will conclude this long speech by saying: do not trust anyone, the Organization is everywhere. Their big blow is on Saturday - we have to stop them, and fast!`,zh:`我早应该知道你不能保密，不过你走运了——我实在急需帮忙，而你看来也有心捣破M组织<itm=02>。@在我还是卧底期间，截到了许多有用的资讯，但还不足以瓦解整个集团。最可靠的线索是罗杰·盖曼<char=35>，但现在他已经死了。@M组织在本星期策划了大型事件，我们必须不惜代价阻止。我知道盖曼派了一名叫迈克·桑德斯<char=23>的士兵到爱尔兰，拿取这件阴谋所需物品。@我联络了翠普上校<char=24>，确认目前那个桑德斯已经回到南华克的军营<loc=J>。@总结是不要相信任何人，因为M组织的势力笼罩四周。星期六它们会重重出手，我们必须精准快速地阻止！`},Id_Character_Name_21:{en:`Scott Clover`,zh:`史葛·葛洛佛`},Id_DisplayTextPerState_8:{en:`Well, great timing! We're overworked today and the Chief Officer's <char=33> absence is not helping. Eli Goldman <char=39> has received death threats and he seems concerned. @ As you know him a bit, could you go to his City offices <loc=B> and determine whether we should act on them? He has powerful influence, so it's best for us all not to take the case lightly.`,zh:`你来得正好！我们工作量多得爆炸，偏偏局长<char=33>不在。艾利·戈德曼<char=39>接到威胁生命的恐吓信，令他十分担忧。@由于你认识他，请你到他在市中心的办公室<loc=B>调查一下我们是否应该行动。他的影响力非同小可，我们最好不要轻视。`},Id_Item_Name_27:{en:`Threatening photo`,zh:`威胁照片`},Id_DisplayText_Default_109:{en:`No, I don't think I know this person.`,zh:`我不认识这人。`},Id_DisplayText_Default_110:{en:`You know, I meet many people, I find it hard to remember them all.`,zh:`我见过非常多人，而没办法记住全部。`},Id_DisplayTextPerState_9:{en:`Indeed, I talked to him on the phone regarding a matter of some threats I received yesterday: this photograph of me with a red M <itm=13> written through it. @ Under normal circumstances I wouldn't have worried about it--you can imagine that one does not achieve my level of success without attracting a few enemies along the way. But with our recent case and the financial fair I am organizing, I had a bad feeling, and I also got where I am by trusting my instincts.`,zh:`没错，由于接到了恐吓信，昨天我跟他通了电话：在我的照片上画了一个红色的M字<itm=13>。@通常我不理会——你也明白在我这个位置不会没有敌人。不过最近的事情加上正在筹备的财经展览，我有不祥的预感，而我之所以爬到今天的位置，都是因为我相信自己的直觉。`},Id_DisplayText_Default_111:{en:`I don't know how I could tell you anything useful about this.`,zh:`有什么有用的资料我可以给你吗？`},Id_DisplayText_Default_112:{en:`Get to the point. We don't have time to talk about useless stuff.`,zh:`说重点。我们没时间鬼扯。`},Id_DisplayTextPerState_478:{en:`I received this photograph of me with a red M written over it. On the back you can read: "We do not forget". As you can imagine, I suspect the M Organization <itm=02> and I have reasons to be worried, considering how our story ended.`,zh:`我收到这帧照片，是我的样子被打一个红色的M字。背面写著：「我们不会忘记。」你知道我怀疑是M组织<itm=02>做的，而按照上一宗案件的结局，我有理由担忧。`},Id_DisplayTextPerState_479:{en:`After you revealed how that organization obtained organs, I decided to freeze my payment. I guess this threatening picture <itm=13> is their answer and I am counting on your help.`,zh:`得知该组织从何获取器官，我决定停止付款，看来这帧恐吓照片<itm=13>就是它们的回复，我全赖你帮忙。`},Id_DisplayTextPerState_480:{en:`The photo seems to have been taken with a smartphone and printed on a printer. Pretty ordinary equipment that can be bought anywhere. The letter was written with a red marker, so nothing remotely interesting there. @ No, the real lead is much more surprising, we have identified the handwriting as well as a fingerprint on the picture, and we are almost certain that the sender is none other than Kevin Doyle <char=47>, the Chief Officer's <char=33> son.`,zh:`这帧照片应该是用手机拍摄，再列印出来。到处都有的基本设备。这封信用红笔写字，没有特别的地方。@不过上面找到的事情就可有趣了。比对笔迹和指纹之后，发现送信人竟然是凯文·戴尔<char=47>，局长<char=33>的儿子。`},Id_DisplayTextPerState_481:{en:`Well, that, yeah... Mike <char=23> asked me to send it. Just to freak him out. Mike said he was getting rich on the backs of the poorest blokes and it was time to remind him of his proper place. I think it was all just bullshit and noise.`,zh:`对……迈克<char=23>叫我寄出，只是用来吓他一下。迈克说他剥削穷人致富，应该提醒他正确的事情。我认为都是废话。`},Id_DisplayTextPerState_482:{en:`He's a loaded bloke, right? Mike had asked me to send him a threatening photo <itm=13>, don't know what it was for.`,zh:`他是个有钱人，对吗？迈克叫我给他寄一张恐吓照片<itm=13>，不知道有什么用。`},Id_DisplayTextPerState_483:{en:`Great, as soon as there is a thing with an M on it, you're going to show it to me now?`,zh:`好啦，你见到有M字的东西就给我看对吗？`},Id_DisplayTextPerState_484:{en:`Yeah, I asked the kid <char=47> to send that. It was a joke, that's all. You going to arrest me for sending pictures?`,zh:`没错，我叫那孩子<char=47>寄出。只是开玩笑而已。我就因为寄照片所以被拘捕吗？`},Id_DisplayTextPerState_485:{en:`Oops, I have the feeling I won. It's a pity, you were funny.`,zh:`哈哈，我赢了。你真可笑。`},Id_DisplayTextPerState_486:{en:`You must be proud of yourself, but don't think for a minute that you have won. Not only will you never put me in jail, but on top of that I wouldn't bet that you'll keep your job.`,zh:`尽管骄傲吧，但别以为你赢了。你不但不可能把我送进监狱，还会丢掉工作。`},Id_Item_Name_28:{en:`Economics Magazine`,zh:`经济杂志`},Id_DisplayTextPerState_487:{en:`A bunch of magazines, among which you find an economics magazine. An article draws your attention, it mentions the financial fair Eli Goldman <char=39> will be organizing in his City offices <loc=B> this Saturday.`,zh:`一大堆经济杂志，当中有一件事引起你注意。艾利·戈德曼<char=39>在本星期六会在市中心的办公室<loc=B>举办一场财经展览的开幕典礼。`},Id_DisplayTextPerState_488:{en:`I heard he works for MI5. I hope he'll be able to help you dismantle the M Organization <itm=02>. I would sleep better.`,zh:`我听说他为国安局工作，希望有助你瓦解M组织<itm=02>，那么我才可以高枕无忧。`},Id_DisplayTextPerState_489:{en:`I heard he had been murdered. Dreadful. I hope it won't make you any less competent.`,zh:`听说他被谋杀了。真可怕，希望这不会妨碍你的工作。`},Id_DisplayTextPerState_490:{en:`A wonderful man. With him, the streets of London are safer, and there's good reason why I regularly send donations to the Metropolitan Police. 
I tried to contact him for that threat case <itm=13> but he wasn't available. I talked to one of your colleagues <char=43> instead.`,zh:`优秀的人，有他在，伦敦更安全，因此我经常捐款给都会警察局。

我尝试告诉他这起恐吓案<itm=13>，可是找不到他，改为跟你另一位同僚<char=43>对谈了。`},Id_DisplayTextPerState_491:{en:`If I understood correctly, we were involved in the same tragedy. Outside of this case, I never met the ambassador in person, even though I have heard a lot of praise about her talents. `,zh:`若我理解正确，我们面对了同样的威胁。我没见过大使，不过听说很多人赞赏她的才华。 `},Id_DisplayTextPerState_492:{en:`The Chief Officer's son? I don't think I ever met him, no. With such a bloodline, I guess he's the ideal son-in-law.`,zh:`局长的儿子？尽管我没见过他，但有那样的爸爸，我猜他会是一名好孩子。`},Id_DisplayTextPerState_493:{en:`Are you sure? The threat came from the Chief Officer's son? Well. Whether it's the M Organization or not, if that's all they have for me, I think I can safely focus on my financial fair.`,zh:`你说真的？总警官的儿子寄来恐吓信？那么无论是否M组织，要是只有这点斤两，我就能安心专注将近的财经展览。`},Id_DisplayTextPerState_494:{en:`I have read that he supervised Doctor Brown's organ trafficking, and that he died in prison. It's probably not a big loss, even though you would need a hell of a head for business to carry out such an operation.`,zh:`我读报知道是他监督布朗医生的器官偷运，而且死在狱中。这不算什么损失，不过的确是顶尖的头脑才有办法干这事业。`},Id_DisplayTextPerState_495:{en:`Yes, I know the Duke, he approached me recently to set up a funding budget. He hopes to prove to Parliament that it is possible to strengthen security while saving money. As an consultant, I could get a percentage of the resulting business.`,zh:`对，我认识公爵。最近他找我合作一个新计划，希望向国会证明有办法加强社会秩序同时省钱。我担任顾问，可以从相关的生意当中分成。`},Id_DisplayTextPerState_496:{en:`Unfortunately yes, I know the Prime Minister. She's a real impediment to investment in our country. I often feel I have to spend my days preventing her from sabotaging our economic policies.`,zh:`真不幸地，我的确认识首相。她实在很妨碍想要注资我国的投资者。我经常感觉要费神费时预防她破坏我们的经济政策。`},Id_DisplayTextPerState_497:{en:`Oh no, don't talk to me about the Prince. Why did he have to plan his engagement ceremony on the same day as my financial fair? I've even wondered if the Prime Minister <char=21> didn't ask him to do so, just to bother me.`,zh:`噢，请别跟我谈起王子。为什么他的订婚典礼选在跟我的财经展览开幕同一天呢？我甚至怀疑是首相<char=21>建议的，就为了找我麻烦。`},Id_DisplayTextPerState_498:{en:`I have a few contracts with the Army through my subsidiaries. I had the opportunity to meet with the Colonel a couple of times. A very righteous man, just what you expect from an officer.`,zh:`我的旗下公司跟军方有一些合约。我有幸跟上校见面几次。心怀正义的人，正是你期望的军官。`},Id_DisplayTextPerState_499:{en:`He's the Director of MI5, I believe. I don't know much about him, but I have to admit that I am curious. Young and ambitious, I hear.`,zh:`他是国安局局长。我不熟悉他，但的确饶有兴趣。听说他年轻又有野心。`},Id_DisplayTextPerState_500:{en:`That's the tramp at the bottom of the building, right? If you could, tell her to go somewhere else.`,zh:`她就是楼下的游民，对吗？要是你有办法，请她到别处吧。`},Id_DisplayTextPerState_501:{en:`No, I don't know him. Do you think the M Organization could have sent him after me? I guess you're working on it, but as long as you haven't found who is the leader, we won't be at peace.`,zh:`我不认识他。你觉得是M组织派他来搞我吗？我猜你在著手调查这件事，但一天找不出首领，我们也不能安眠。`},Id_DisplayTextPerState_502:{en:`On Saturday, I'm hosting my financial fair, what I hope will be an annual event. The financial stakes are huge, and if this photo <itm=13> wasn't giving me the impression that my life is in danger, I wouldn't have any time to waste on you.`,zh:`星期六我将开启一个财经展览，希望以后能每年举办。由于整个商界都翘首以盼，要是这照片<itm=13>没有威胁我的生命，我才不会跟你耗。`},Id_DisplayTextPerState_503:{en:`You think they want to detonate a bomb during my fair? Well, there's no way I am cancelling the event. So you'd best find a solution!`,zh:`你觉得它们要炸掉我的展览吗？我不会取消展览，你要解决它。`},Id_DisplayTextPerState_504:{en:`You think he is that organization's target? That would be a pity; he has much to contribute to our politics, especially for people like me. `,zh:`你觉得他是M组织的目标吗？真可怕，他对政治贡献良多，尤其是对于我这样的人来说。 `},Id_DisplayTextPerState_506:{en:`Believe me, cameras can be made to say anything. Some documentary managed to make me look like some inhuman person who only cares about money. Fortunately, I shut down that show in the aftermath.`,zh:`相信我，影片可以塑造事实。有些纪录片形容我是一心只在意财富的非人生物。之后我总算腰斩了那节目。`},Id_DisplayTextPerState_507:{en:`You have to follow the money if you are looking for the sponsor. Of course, if they have any common sense they used professional money-launderers and you won't find any trace.`,zh:`你需要从赞助者找出幕后主使。当然，他们有点常识的话，就会使用专业的洗黑钱管道，让你追踪不了。`},Id_DisplayTextPerState_508:{en:`It's an important step in my career. This fair's success will make me the key stakeholder in financial matters in this country. This is an opportunity to have a lasting impact on our economic policies, so nothing should prevent that!`,zh:`这是我事业上重要的一步，成功的话我就是这个国家的关键人物。我要借此机会让经济政策长治久安，没事情可以阻挡我！`},Id_DisplayText_Default_113:{en:`I don't think I met that person.`,zh:`我应该没见过这人。`},Id_DisplayText_Default_114:{en:`I am not sure I know who this person is.`,zh:`我不认识这人。`},Id_DisplayTextPerState_509:{en:`It's dreadful, andI don't know how we'll manage without him. He was a very inspiring superior. I learned so much from him.`,zh:`真可怕，我不知道没了他该怎么办。他是优秀的上司，我从他身上获益良多。`},Id_DisplayTextPerState_510:{en:`It's a shame the Chief Officer is not here. He stopped by the lab yesterday and we haven't seen him again since. He didn't say he would be absent. I hope nothing serious happened to him.`,zh:`只可惜局长不在，昨天他去了实验室，自此没人见过他。他没有说过会缺勤，但愿没有遇上意外。`},Id_DisplayTextPerState_511:{en:`Who could have guessed that this barman worked for MI5. You are really involved in some funny business. In any case, I hope he will be able to help you dismantle the M Organization <itm=02>`,zh:`谁料到这酒保为国安局工作？你的确卷入了有趣的事情。无论如何，我希望他可以帮助你瓦解M组织<itm=02>。`},Id_DisplayTextPerState_512:{en:`This barman really doesn't look like he's up to anything good. You should keep an eye on him.`,zh:`这酒保看来并非善类，你要盯著他。`},Id_DisplayTextPerState_513:{en:`That's a hell of a job you did in that investigation. The ambassador must be grateful.`,zh:`你实在居功厥伟，大使一定感激不尽。`},Id_DisplayTextPerState_514:{en:`I heard that the ambassador had stopped by Scotland Yard to talk to you. Perhaps she give you a lead on the M Organization?`,zh:`听说大使来到苏格兰场要跟你谈话。也许能从中得知M组织的消息？`},Id_DisplayTextPerState_515:{en:`I saw that the ambassador had stopped by Scotland Yard to talk to you, and she didn't look very happy.`,zh:`我见到大使来到苏格兰场要跟你说话，看来心情不好。`},Id_DisplayTextPerState_516:{en:`We all make mistakes. The ambassador probably won't see it that way, but it's not your fault if you couldn't save her daughter.`,zh:`我们做错了，大使不会见我们，不过救不到她女儿并非你的错。`},Id_DisplayTextPerState_517:{en:`I am not displeased that he was sent to jail. His mere presence here was making me sick.`,zh:`得知他被送进监狱，我无法不开心。他存在已经让我反感。`},Id_DisplayTextPerState_518:{en:`The Chief Officer's son, I met him once. He doesn't look like a bad guy but his awkward teenage phase is running a bit long.`,zh:`局长的儿子，我见过他一次，不是个坏人，但叛逆期有点过长。`},Id_DisplayTextPerState_519:{en:`I don't understand how his murderer could get in without being caught. You think he had an accomplice in the police force?`,zh:`不明白为什么抓不到凶手。你认为我们当中有内鬼吗？`},Id_DisplayTextPerState_520:{en:`There is a lot of talk about his proposed legislation. I heard a few things and I am not convinced. I may well be a police officer, but I don't feel like living in a police state.`,zh:`很多人谈论他提出的法案。我得知了一部分，并不喜欢。我是警察，但不喜欢住在警察国家。`},Id_DisplayTextPerState_521:{en:`We are really lucky to have such a competent and modern Prime Minister like her. I hope it will last because she has many opponents, starting with the Duke of Windsor <char=27> and Eli Goldman <char=39>.`,zh:`有她这样才干非凡且视野前瞻的人做我们的首相，实在无比幸运。希望她能久居相位，因为反对她的人可不少，例如温莎公爵<char=27>和艾利·戈德曼<char=39>。`},Id_DisplayTextPerState_522:{en:`You think we could watch his engagement ceremony on Saturday?`,zh:`你认为我们需要留意他在星期六的订婚典礼吗？`},Id_DisplayTextPerState_523:{en:`He's the Director of MI5? I think I heard his name once, but he's a rather discreet man. Doesn't he look a bit too young to be the director?`,zh:`他是国安局的局长？我听过这名字一次，但他是个低调的人。你不觉得他看起来太年轻了吗？`},Id_DisplayTextPerState_524:{en:`Yes, that name is familiar, I think I arrested her for possession of drugs <cat=08> a few years ago. I believe she's been benefiting from a rehabilitation program since then.`,zh:`对，我对这名字有印象，数年前应该曾经因藏毒<cat=08>拘捕过她。我记得她之后好好地完成了更生计划。`},Id_DisplayTextPerState_525:{en:`He scares me a bit. He looks friendly, but I know he has a lot of influence and I am afraid of the consequences if we mess up a case concerning him. He told me he got a threat by mail <itm=13>`,zh:`他有点吓到我了，看似和善，但我晓得他影响力巨大，要是我们做不好他的案件，后果堪虞。他告诉我曾经接到恐吓信<itm=13>。`},Id_DisplayTextPerState_526:{en:`Poor girl. I don't know if it would be better for her to be alive or not.`,zh:`可怜的小女孩，真不知道她遭遇了多少痛苦。`},Id_DisplayTextPerState_527:{en:`This kind of case shows you if you made the right choice.`,zh:`这案件证明了你的决定正确。`},Id_DisplayTextPerState_528:{en:`I am having a hard time getting over Tracy's death. We were close. I hope you'll manage to find who is leading this M Organization <itm=02> because that's all their fault.`,zh:`我还没有从崔丝的死讯恢复过来。本来差一点就救得了她。我希望你找出谁主使M组织<itm=02>，告慰她的在天之灵。`},Id_DisplayText_Default_115:{en:`Maybe you should send that to the lab.`,zh:`也许你该去实验室。`},Id_DisplayText_Default_116:{en:`Here's where I realize that you are much better investigators than I am, because I have no idea what you are talking about.`,zh:`我对这件事完全没有头绪，印证你是比我优秀的探员。`},Id_DisplayTextPerState_529:{en:`A picture of Eli Goldman with a red M written through it. On the back you can read: "We do not forget". It is clearly a threat and it sounds like the M Organization <itm=02>. I guess you're interested?`,zh:`艾利·戈德曼的照片，被打一个红色的M字。背面写著：「我们不会忘记。」明显是恐吓信，似乎是M组织<itm=02>做的。也许你有兴趣调查。`},Id_DisplayTextPerState_530:{en:`I hope you manage to solve this case. Such a powerful group can't be allowed to keep acting with such total impunity in our country.`,zh:`希望你破了这案件。不能任由这种蛮横组织兴风作浪，却逍遥法外。`},Id_DisplayTextPerState_531:{en:`Are you going to try and find him? I will help you if I can, but perhaps you should talk to our experts. They've been working with the Chief Officer for longer than I have and surely they will be eager to help you.`,zh:`你要尝试找他吗？我会尽力帮忙，但也许你应该问一下我们的专家。他们与局长共事时日比我长，而且他们也非常乐意出手。`},Id_DisplayTextPerState_532:{en:`With this quantity of explosive, I don't think a tall building is being targeted. Or else, the target is a big room... That's the only hypothesis I can put forward.`,zh:`这个量的炸药，那么目标应该不是高楼。也许是一间大房间……这是我唯一想到的推测。`},Id_DisplayTextPerState_533:{en:`That lead is a bit thin, did you check that the recording doesn't hide anything special?`,zh:`这线索有点薄弱，你检查过这段录音里面有什么特别吗？`},Id_DisplayTextPerState_534:{en:`I'd recognise this siren anywhere. It's the Wormwood factory's. It can be heard in the whole Dockland neighbourhood <loc=P>! There are a few abandoned warehouses in the area. It's a perfect place to hide--maybe you should go and have a look.`,zh:`我在某地方听过这汽笛声，是码头区一座苦艾工厂会发出的声音<loc=P>！那里有几座废弃仓库，最适合隐藏行踪。也许你应该去那里看一下。`},Id_DisplayTextPerState_535:{en:`I hope Carol <char=22> stopped using, or it could cost her a lot.`,zh:`我希望嘉璐<char=22>已经戒掉，不然后果不堪设想。`},Id_DisplayTextPerState_536:{en:`I've never seen anything like it before. If MI5 is involved, you'll have to be cautious and find someone to overstep their authority.`,zh:`我从没见过这种事情。要是国安局被卷入其中，你务必小心，找一个靠山，权限足以凌驾他们。`},Id_DisplayTextPerState_537:{en:`This murder shouldn't go unpunished. This bullet will lead you straight to the culprit.`,zh:`不可让凶手逃之夭夭，这发子弹很快就让你找得到犯人。`},Id_DisplayTextPerState_538:{en:`Ask Harvey Marshall, and I'm sure he'll be able to help you.`,zh:`去问哈维·马绍吧，我很有信心他帮得了你。`},Id_DisplayTextPerState_540:{en:`So Goldman <char=39> was right to contact us. Surely they didn't have this in their hideout by coincidence.`,zh:`那么戈德曼<char=39>找我们的确没错。很明显他们不会碰巧把它留在那种藏身处。`},Id_DisplayTextPerState_541:{en:`You think he was warned of what was going to happen?`,zh:`你觉得他收到警告将要出事吗？`},Id_DisplayTextPerState_542:{en:`What you just did is incredible. Do you have a lead on who might have a vested interest in the bomb going off?`,zh:`你做得实在太棒了。你想得到要是爆炸了，谁会得利吗？`},Id_DisplayTextPerState_543:{en:`You can't succeed at everything but don't let this get you down. Surely there's still time to go after the M Organization.`,zh:`你不能事事顺利，但不能因此气馁。我们还有时间追寻M组织。`},Id_DisplayTextPerState_544:{en:`Yeah, Mike <char=23> is the one who brought those magazines. I don't think he even opened them.`,zh:`对，迈克<char=23>带来这些杂志，但他连翻也没翻开过。`},Id_DisplayTextPerState_545:{en:`You think I'm going to cry because that capitalist pig is getting death threats? I hope he's having trouble sleeping, at least!`,zh:`资本主义的肥猪接到死亡恐吓，我需要掉眼泪吗？我会很开心他睡不好！`},Id_DisplayTextPerState_546:{en:`Yeah that's Goldman's <char=39> great financial mass. Mike <char=23> talked to me about it. That whole thing is a real outrage!`,zh:`对，那是戈德曼<char=39>的财经洗脑大会。迈克<char=23>告诉过我。整件事根本不可理喻！`},Id_DisplayText_Action_9:{en:`You receive a phone call:
"This is Drake O'Brian <char=49>, I think we really need to talk about the M Organization <itm=02>. Meet me discreetly at MI5 <loc=O>. Don't wait, the clock is ticking."`,zh:`你接到电话：

「我是德雷克·柯布连<char=49>，我认为需要一起好好谈一下M组织<itm=02>，秘密来国安局<loc=O>找我。别踌躇，时间宝贵。」`},Id_DisplayTextPerState_547:{en:`When he was younger, he wanted to work at the forensic lab. You should have seen him play with the chromatograph, he was really cute. But, well, he's had... difficult teenage years.`,zh:`他小时候来过鉴识实验室。你应该见过他把玩层析仪，当时他非常可爱。但是踏入叛逆期就性情大变……`},Id_DisplayTextPerState_548:{en:`Have kids, they said. After hearing the Chief Officer complain about his so many times, I don't really mind being infertile.`,zh:`人人都说要生孩子。不过听了局长抱怨那么多次，我可不后悔没小孩。`},Id_DisplayTextPerState_549:{en:`You think my life could be threatened? That wouldn't be surprising. That's why I want to reform the justice system-- we are no longer safe in our own country!`,zh:`你认为有人要取我性命？稀松平常。正因如此，我立意改革司法制度，不然在国土上也不安全！`},Id_DisplayTextPerState_550:{en:`That old grump refuses to understand anything. I know our legal system isn't fit anymore, but if he accepted to compromise a bit, we could pass reforms together. Instead, he's going to hit a brick wall during the session tomorrow.`,zh:`那老顽固一点都不明白。我晓得司法制度需要改进，但要是他肯作一点让步，我们就能通过法案了。现在可好了，明天他铁定会碰钉子。`},Id_DisplayTextPerState_551:{en:`Oh, you found it in a warehouse? It's an old computer that was stolen from me. I hope I can get it back, then.`,zh:`噢！你在仓库找到它？有人偷走了我这台电脑，我希望可以拿回来。`},Id_DisplayTextPerState_552:{en:`Why do I have the feeling that you suspect me of something?`,zh:`我感觉你有事怀疑我。`},Id_DisplayTextPerState_554:{en:`You really think I am going to snitch? I'm not suicidal.`,zh:`你以为我会招供？ 我可不喜欢找死。`},Id_DisplayTextPerState_555:{en:`You think you've won, but you're too late. You can't prevent anything from happening and I will be out of jail as soon as you turn your back. Our leader is far too high up for you to touch, little detective.`,zh:`你以为你赢了，其实太迟了。你没办法阻止将要发生的事情，而且只要你一转身，我马上就会出狱。我们的首领高高在上，小小侦探动不了他分毫。`},Id_DisplayTextPerState_556:{en:`Those geeks, I barely understand half of what they say.`,zh:`电脑宅。我听不懂他们说的语言。`},Id_DisplayTextPerState_557:{en:`The Doc is very efficient, but I have to admit he makes me a little uncomfortable.`,zh:`医生效率出色，但我必须承认他让我感到有点不自在。`},Id_DisplayTextPerState_558:{en:`I heard he used to work as a shrink in the private sector before he started working with us. He was making a very good living, but he wasn't happy, needed to feel more useful.`,zh:`听说他加入我们之前，在私人企业担任精神科医生。衣食不虞，可是并不快乐，他渴望派上用场的岗位。`},Id_DisplayTextPerState_559:{en:`I like working with Lou Chin. It is rare to find positive people like that, and in our line of work, it's a really good feeling.`,zh:`我喜欢跟刘紫嫣工作，像她那样朝气蓬勃的人能够感染别人，令整个团队都心情愉快。`},Id_DisplayText_Action_10:{en:`Scotland Yard just received an anonymous phone call. Apparently there has been an exchange of gunfire in a Dockland warehouse <loc=P>`,zh:`苏格兰场刚接到匿名电话，说到码头区仓库<loc=P>发生枪击。`},Id_DisplayTextPerState_560:{en:`Roger Gaiman died by strangulation but there were signs of struggle showing that it was not a suicide. I informed the Chief Officer <char=33> but he ignored my analyses on this matter.`,zh:`罗杰·盖曼被勒死，挣扎痕迹显示他并非自杀。我通知了局长<char=33>，但他忽视了我的分析结果。`},Id_DisplayTextPerState_561:{en:`My analyses confirm that the samples you collected only contain the Chief Officer's blood.`,zh:`我的分析发现你取得的样本只找到局长的血液。`},Id_DisplayTextPerState_562:{en:`You again? What do you want?`,zh:`又是你？什么事？`},Id_DisplayTextPerState_563:{en:`This type of bullying could come from the M Organization <itm=02>, as they tend to hold grudges.`,zh:`这种充满恨意的欺凌，疑来自M组织<itm=02>。`},Id_DisplayTextPerState_564:{en:`The M Organization <itm=02> has many financial aspects. The dismantling of their organ trafficking operation will have a huge impact on their financial resources.`,zh:`M组织<itm=02>有许多财源，破获器官偷运可以瓦解它们一大金钱命脉。`},Id_DisplayTextPerState_565:{en:`This is really serious, I will help you in any way I can to find out where and when it is going to go off.`,zh:`这事情非常严重，我会尽一切努力找出它的位置和引爆时间。`},Id_DisplayTextPerState_566:{en:`This bomb is not on the network. Why are you calling me? There is nothing I can do for you!`,zh:`网上找不到这炸弹的资料，为什么来问我？我可帮不了你！`},Id_DisplayTextPerState_567:{en:`It looks like we should be worried about bombing attacks, and there are potential targets all over the place at the moment. On Saturday, I count at least three major opportunities: @ First, there is the Prince's <char=29> engagement ceremony, which will take place in Greenwich <loc=M>. It's a big event for the whole country.@ Second, there is the vote on the Duke of Windsor's <char=27> proposed legislation, in the House of Lords at Parliament in Westminster <loc=A>. That proposal has been talked about a lot and deals precisely with the matter of terrorism. @Third and finally, there is the opening of Eli Goldman's  <char=39> financial fair in the City <loc=B>. All the country's major financial professionals will be there. We will never have enough men to cover everything. We need more information.`,zh:`看来我们必须提防炸弹袭击。目前到处都是潜在的袭击目标。我能举出星期六可能受袭的三个目标：@首先是王子<char=29>的订婚典礼，在格林威治<loc=M>举行。这是攸关全国的重大事情。@其次是温莎公爵<char=27>提出法案的投票，在西敏国会大楼<loc=A>举行。他的议案正针对恐怖主义。@最后，艾利·戈德曼<char=39>在市中心<loc=B>举办财经展览开幕仪式，集合了全国的金融要人，而我们的人手不足以顾全三地，急需更多资料分析。`},Id_DisplayTextPerState_568:{en:`Use the proper tools to defuse it. If you don't, it may explode.`,zh:`使用正确的工具拆除它，不然就会爆炸。`},Id_DisplayTextPerState_569:{en:`A basic bomb is easy to defuse, but this one has been assembled with special equipment and it is much more complicated. It will certainly help to know which equipment was used.`,zh:`基本的炸弹很容易拆解，但这个用特殊工具组装，所以复杂多了。我建议你找出当时用了什么工具。`},Id_DisplayTextPerState_570:{en:`You must use the proper tool to defuse the bomb. Hang up immediately and use the right tool!`,zh:`你一定要使用恰当的工具拆除这枚炸弹。看好它，使用正确的工具！`},Id_DisplayTextPerState_571:{en:`So the M Organization is planning a bombing attack... Okay, but that doesn't tell us their target or their motives. For Saturday, I can see at least three potential targets: @ The Prince's <char=29> engagement ceremony in Greenwich <loc=M>, the vote on the Duke of Windsor's <char=27> proposed legislation, at  Parliament in Westminster <loc=A>, and Eli Goldman's  <char=39> financial fair in the City <loc=B>. We need to find a better lead that narrows things down.`,zh:`所以M组织策划炸弹袭击吗……好吧，但是这看不出他们的目标和动机。我能举出星期六可能受袭的三个目标：@首先是王子<char=29>的订婚典礼，在格林威治<loc=M>举行。其次是温莎公爵<char=27>提出法案的投票，在西敏国会大楼<loc=A>举行。最后，艾利·戈德曼<char=39>在市中心<loc=B>举办财经展览开幕仪式。我们急需更多资料分析。`},Id_LocationState_Introduction_22:{en:`The arrangements for the Prince's <char=29> engagement ceremony are under way, and the security guards are not joking. You show your badge, but nothing is working.`,zh:`王子<char=29>的订婚典礼如火如荼，保安人员尽忠职守，即使你展示工作证也不得其门而入。`},Id_DisplayText_Default_117:{en:`We'll have to find authorizations.`,zh:`我们要先取得准许。`},Id_DisplayTextPerState_572:{en:`The Prince's engagement ceremony in Greenwich <loc=M> is making things complicated. If you believe it is really important, I will see what I can do, but don't expect miracles.`,zh:`王子在格林威治<loc=M>的订婚典礼使得事情更复杂。如果你真的认为很重要，我会尝试帮你，但别抱太大期望。`},Id_DisplayTextPerState_573:{en:`I am not surprised. I already had my doubts and that's why I distanced myself from that organization. When I was helping them, they insisted that I should get plants delivered to Parliament, but I decided to stop being involved with them.`,zh:`我可不惊讶，毕竟早就心存怀疑，因此对那组织敬而远之。我本打算帮助它们，对方却坚持我必须把植物送到国会大楼，于是我抽身离开。`},Id_DisplayTextPerState_574:{en:`That's your problem, and considering how efficient you seem to be, I wonder if I shouldn't just avoid Parliament altogether and go back to France.`,zh:`这是你的问题。想到你的办事效率，也许我应该避开国会大楼，回去法国算了。`},Id_DisplayText_Default_118:{en:`Stop asking me those questions, I have no reason to answer you.`,zh:`别再问了。我没义务回答你。`},Id_DisplayText_Default_119:{en:`My father is a scumbag for sending detectives after me. Tell him I am NEVER going home.`,zh:`我爸真低级，派探员来跟踪我！告诉他，我绝不回家`},Id_DisplayText_Default_120:{en:`What did my father find out now to justify his devotion to a corrupt system? I won't say a thing.`,zh:`我爸又要做什么事，支撑腐败的制度？我一句话也不会说。`},Id_DisplayText_Default_121:{en:`It's my father who asked you to grill me. He can just go jump in the Thames!`,zh:`我爸派你来讯问我吧，他不如跳进泰晤士河死一死！`},Id_DisplayText_Default_122:{en:`You think I don't know that you are the puppets of my father, and of the whole system, while you're at it.
I won't say a thing.`,zh:`你以为我不知道你是我爸和这整个制度的傀儡吗？

我一句话都不会说。`},Id_DisplayTextPerState_270:{en:`Mike <char=23> always told me that sometimes you have to blow up the system if you want to build a new world. He never told me what he was going to do with it.`,zh:`迈克<char=23>一直告诉我要炸掉现存制度，才能创造新世界。他从没告诉我是真的用这玩意来做的。`},Id_DisplayTextPerState_575:{en:`You think they want to blow me up? Are you sure? Do you know that Eli Goldman's <char=39> financial fair is on Saturday as well? Surely that would be a more vital target than an old crumbly like me.`,zh:`你认为它们要炸死我吗？肯定吗？你知道艾利·戈德曼<char=39>星期六也举办财经展览开幕仪式吗？比起我这个过气老人，他肯定是更好的目标。`},Id_DisplayTextPerState_576:{en:`A bomb... Do you know their target? You think it could be my engagement ceremony? If that's the case, come back and talk to me about the bomb on Saturday morning, and I'll do whatever needs to be done, even if that means postponing the engagement ceremony, regardless of how long it's been planned...`,zh:`一枚炸弹……你知道它们的目标吗？是我的订婚典礼吗？要是这样，星期六早上回来跟我谈一下，我会尽力配合，即使需要延后这场计划了很久的订婚典礼……`},Id_DisplayTextPerState_577:{en:`The army is mobilized to prevent this kind of attacks. Don't worry too much, we are looking after the populace.`,zh:`军队会出动应对这种恐攻。不用担心，我们会照顾公众。`},Id_DisplayTextPerState_578:{en:`A bombing attack? I didn't imagine the M Organization would stoop to that kind of thing, but we don't actually know what their ultimate purpose might be.`,zh:`炸弹恐攻？没想到M组织会做这种事情，不过不晓得它们最终目的是什么。`},Id_DisplayTextPerState_579:{en:`Yeah, I made a bomb but I didn't really have a choice--Mike <char=23> made that very clear. I had a "debt" to repay.`,zh:`对，我制造了这枚炸弹，但别无他法——迈克<char=23>清楚告诉我必须要还债。`},Id_DisplayTextPerState_580:{en:`You think you've won, but you are too late. You won't prevent anything from happening and I will be out of jail as soon as you turn your back. Our leader is way too high up for you to touch.`,zh:`你以为你赢了，其实太迟了。你没办法阻止将要发生的事情，而且只要你一转身，我马上就会出狱。我们的首领高高在上，你根本动不了他分毫。`},Id_DisplayTextPerState_581:{en:`You think they're going to try and blow up the barracks?`,zh:`你认为它们要炸掉我们的军营吗？`},Id_DisplayTextPerState_582:{en:`Oh my God! Do you think they'll blow something up? I hope it won't be the Prince's <char=29> engagement ceremony!`,zh:`天哪！你觉得它们要炸掉什么？我希望不是王子<char=29>的订婚典礼！`},Id_DisplayTextPerState_583:{en:`A bomb? And it's connected to Sanders <char=23>? You're starting to scare me--what did that moron get me into?`,zh:`炸弹？这跟桑德斯<char=23>有关吗？你吓到我了，那蠢蛋做了什么？`},Id_DisplayTextPerState_584:{en:`You think they want to detonate a bomb during my fair? There's absolutely no way I am cancelling this, so you'd better find a solution!@
But... well... If on Saturday morning you are still convinced that my fair is the target, come back and talk to me about the bomb and I will do what needs to be done.`,zh:`你觉得它们要炸掉我的展览吗？我不会取消展览，你要解决它！@

但是……如果你真的认为目标是我的展览，回来告诉我有关炸弹的资料，我会提早准备。`},Id_DisplayTextPerState_585:{en:`So we'll have to face a bombing attack... Do you think they are going to target Eli Goldman's <char=39> financial fair ?`,zh:`我们要预防炸弹袭击吗？你认为目标是艾利·戈德曼<char=39>的财经展览？`},Id_DisplayText_Action_11:{en:`The clock is ticking but your acting commanding officers do not give you a choice: you have to go back to Scotland Yard to attend the crisis meetings. @ Tomorrow, you will have to be at your best to prevent the M Organization from implementing their sinister plan, but your investigation time is over for today.`,zh:`尽管时间迫在眉睫，你的指挥官明令你必须立即回到苏格兰场，出席危机应变会议，不容一刻犹豫。@明天你一定要竭尽所能，阻止M组织施行邪恶计划。而你今天的调查必须告一段落。`},Id_Item_Name_29:{en:`Financial Fair`,zh:`财经展览`},Id_Item_Name_30:{en:`Prince's Engagement Ceremony`,zh:`王子的订婚典礼`},Id_DisplayTextPerState_586:{en:`It's a disaster! Do you really thing the bomb is about to blow up? I won't let that happen! Let me take care of this.`,zh:`这是灾难！你觉得什么要被炸？我不容许这事发生！让我处理吧。`},Id_DisplayText_Action_12:{en:`Eli Goldman <char=39> does what he said he would do. He evacuates the fair under the protest of the greatest bankers and financial professionals in the world. @ 
His security team is large and efficient, but it takes a good couple of hours to look for the bomb...@ To no avail. Either the financial fair isn't the target, or you are missing something. Eli Goldman is furious with you.`,zh:`艾利·戈德曼<char=39>遵守承诺，不理会全球大银行家和商界精英抗议，强行疏散了展览来宾。

他的保全团队人手充足且效率一流，但找了好几个小时也找不到炸弹……@原来是徒劳无功。你要不是误判目标，就是忽略了重要线索。艾利·戈德曼对你暴跳如雷。`},Id_DisplayTextPerState_587:{en:`Eli Goldman is furious and won't talk to you. He must clean up the mess he created because of you.`,zh:`艾利·戈德曼对你怒不可遏，不愿跟你说话，因为要清理因你而起的烂摊子。`},Id_DisplayTextPerState_588:{en:`Everybody is talking about you at the moment, even here.`,zh:`所有人都在谈论你，这里也不例外。`},Id_DisplayTextPerState_589:{en:`It's serious then! There is going to be an attack during my engagement ceremony. 
I don't have a choice. On your recommendation I will postpone, no matter if it keeps the whole nation waiting.`,zh:`我的订婚典礼是炸弹案目标？这非常严重！

我惟有按你建议延迟订婚典礼，即使要让全国等待。`},Id_DisplayText_Action_2:{en:`The Prince <char=29> reluctantly decides to postpone his engagement party. There are tears of disappointment across a whole nation who doesn't understand the reasons. The tabloids are having a field day, and the nickname "Prince Weathercock" starts to spread.@ The Prince's personal guards are in charge of looking for the explosive device... @ To no avail, either the Prince's engagement ceremony isn't the target, or you are missing something. The Prince is now stuck with his communication team.`,zh:`王子<char=29>不情不愿地延后了他的订婚典礼。因为不明个中原因，举国为此垂泪。小报把握机会，为王子取了诨名叫「风信鸡王子」，结果不胫而走。@王子的保镳团队遍寻不著爆裂物……@原来是徒劳无功。你要不是误判目标，就是忽略了重要线索。王子跟公关队伍忙得焦头烂额。`},Id_DisplayTextPerState_590:{en:`The Prince is stuck with his communication team to handle the postponement of the engagement ceremony. You can give him your report but he won't be able to answer your questions.`,zh:`王子跟公关团队为了订婚典礼延期忙得不可开交，你可以向他提交报告，但他没空回答你的提问。`},Id_DisplayTextPerState_591:{en:`I see you are getting closer to our common target. Give me your full report when you are ready. Hurry up, my engagement ceremony is starting soon.`,zh:`我知道你渐渐追踪到我们的共同敌人。你准备好详细报告之后来找我吧。快！我的订婚典礼快举行了。`},Id_DisplayTextPerState_592:{en:`Should this bomb threat really be taken seriously? The Parliament meets on Saturday for an important session. If it truly is your terrorists' target, come back to see me on Saturday morning and I will do what needs to be done.`,zh:`炸弹威胁是当真的吗？国会在星期六会举行重要会议。如果真的是袭击目标，星期六早上回来见我，我会布置所需安排。`},Id_LocationState_Introduction_23:{en:`Parliament is in the middle of a session debating the Duke of Windsor's <char=27> proposed legislation, supported by Conor McVeill <char=36>. The Prime Minister <char=21> seems to have given instructions to allow you to investigate.`,zh:`国会正在讨论温莎公爵<char=27>提出的法案，获得科拿·麦威尔<char=36>支持。首相<char=21>似乎已经下令允许你调查。`},Id_DisplayText_Action_13:{en:`The Prime Minister evacuates Parliament. She says she will take care of getting the entire building searched, but she asks you to take care of the House of Lords.`,zh:`首相疏散了国会大楼，告诉你她会负责搜索整座国会大楼内部，但指派你负责上议院。`},Id_DisplayTextPerState_593:{en:`It's a serious threat you are reporting. I will evacuate Parliament.`,zh:`你报告了重大威胁，我会疏散国会大楼。`},Id_DisplayTextPerState_594:{en:`It's really disgusting to work on spoiled food leftovers. But I could extract DNA, and it was Kevin's <char=47>. Poor boy, I hope he is okay.`,zh:`分析吃剩的食物实在恶心，但我可以从中撷取DNA。结果属于凯文<char=47>，可怜的小子，希望他平安。`},Id_DisplayTextPerState_595:{en:`I can access some databases that could help you. Let me see. This fingerprint belongs to Dolores Kelly <char=19>, suspected of being an explosives expert for terrorist organizations.`,zh:`我可以查阅一些资料库，看看对你有没帮助。好了，那指纹属于桃乐丽思·凯莉<char=19>，她被怀疑是恐怖组织的炸弹专家。`},Id_DisplayTextPerState_596:{en:`You suspect me, really? Here are my fingerprints: clearly you can see that they don't match.`,zh:`你怀疑我？真的？这是我的指纹，一核对便知道不符合。`},Id_DisplayTextPerState_597:{en:`You're just embarrassing yourself, asking me about that!
Here are my fingerprints, and clearly you can see that they don't match at all!`,zh:`问我这问题侮辱了你自己！

这是我的指纹，明显不匹配！`},Id_DisplayTextPerState_598:{en:`It won't be said that I'm not helping the police forces to do their job. Here are my fingerprints, which obviously don't match.`,zh:`我不想被人说妨碍警方执勤，这是我的指纹，很清楚并不相配。`},Id_DisplayTextPerState_599:{en:`Let me make a few calls to see if I can help you.@ A friend found a match for your fingerprint. It belongs to Dolores Kelly <char=19>, who has already been involved or suspected in several terrorism cases.`,zh:`让我问一下人，看看能否帮助你。@一位朋友找到匹配结果，属于桃乐丽思·凯莉<Char=19>。这人曾牵涉几宗恐怖袭击案件，或被怀疑与之有关。`},Id_DisplayTextPerState_600:{en:`This fingerprint isn't in the military database, so it doesn't belong to me or to any member of the military. `,zh:`军方资料库找不到这指纹，所以与我或任何军方人员无关。 `},Id_DisplayTextPerState_601:{en:`It sounds like you are asking for a favour. I'll do it for you but I will be expecting something in return. @
Let me make a few calls to see if I can help you.@ Your fingerprint belongs to Dolores Kelly <char=19>, suspected of being an explosives expert for terrorist organizations.`,zh:`你似乎需要我帮忙，可以，但我希望你能有所回报。@

让我问一下人，看看能不能帮忙。@那指纹属于桃乐丽思·凯莉<char=19>，她被怀疑是恐怖组织的炸弹专家。`},Id_DisplayTextPerState_602:{en:`Because you think the military don't already have my fingerprints in their database? Look, it's not mine.`,zh:`你以为军方资料库没有储存我的指纹吗？看清楚点，那不是我的。`},Id_DisplayTextPerState_603:{en:`Sorry, I am not allowed to search through the MI5 files for you. Ask the Director.`,zh:`抱歉，我没权限帮你搜寻国安局的档案。请问局长。`},Id_DisplayTextPerState_604:{en:`Alright, take my fingerprints if it can help you.
Doesn't look like a match.`,zh:`好吧，拿我的指纹去比对一下吧。

看来不吻合。`},Id_DisplayTextPerState_605:{en:`My fingerprints, now. Your case just keeps getting better.
Here they are, they don't match. You really are running around in circles.`,zh:`这是我的指纹，案件有进展是吗？

看，它们并不吻合。你根本在捕风捉影。`},Id_DisplayTextPerState_606:{en:`There's a database that may give us some insights... Yes, here, our Irish friends are giving me information. These fingerprints belong to one of their fellow countrywomen: Dolores Kelly <char=19>.`,zh:`有个资料库可以找到答案……对，看这里，我们的爱尔兰朋友送来资料，那属于其中一名爱尔兰人：桃乐丽思·凯莉<char=19>。`},Id_DisplayText_Action_14:{en:`5... 4... 3...

Just one more action before the bomb goes off!

Quick!`,zh:`五……四……三……

炸弹爆炸前，只剩一次行动！

快！`},Id_LocationState_Introduction_24:{en:`Panic rules. Firemen try to contain the flames. Thank God you evacuated Parliament, otherwise the Prime Minister <char=21>, the Duke of Windsor <char=27> and even the MI5 Director <char=36> would be dead.`,zh:`恐慌肆虐，消防员试图控制火势。感谢上苍你疏散了国会大楼，不然首相<char=21>、温莎公爵<char=27>，甚至国安局局长<char=36>都会罹难。`},Id_DisplayTextPerState_607:{en:`Fortunately you kept the screwdriver you found in the warehouse, so you can easily open the trap and access the wiring. You find a unique purple wire among the tangle of cables. The countdown stops as soon as you unplug it.`,zh:`多亏你带走了仓库里的特殊螺丝起子，所以轻易开启了装置，找到所有线路。你从纠缠的线管当中找到独特的紫色线，拔掉之后倒数便停止了。`},Id_DisplayTextPerState_608:{en:`The shape of the screws is really too specific. You'll never manage to remove them on time to access the wiring. It's too late. You only have time to run.`,zh:`螺丝的形状太特别，你没办法及时拆开并找到线管。太迟了，你只能逃命。`},Id_DisplayTextPerState_609:{en:`We have to find where this bomb could have been hidden before it goes off!`,zh:`我们必须找到埋藏的炸弹，以免它爆炸！`},Id_DisplayTextPerState_610:{en:`You analyze the bomb, which has been made by a professional who most likely used the best tools possible. You would need to be able to use those to defuse the bomb.`,zh:`你分析这炸弹，组装细致，看来用了很特殊的工具。你需要用相同的工具才可以拆除。`},Id_DisplayTextPerState_287:{en:`I am convinced the Prince will be a very valuable political ally in the years to come.`,zh:`我相信王子在未来几年会是政坛上可靠的盟友。`},Id_DisplayTextPerState_288:{en:`There are all types of punks here in London. Some are friendly... some not so friendly. There is a fashionable squat at the moment close to Whitechapel <loc=I>. Many punk bands go there.`,zh:`伦敦有各种各样的庞克人，有些友善的，有些并不……目前在白教堂有一所时髦的非法占用居所<loc=I>，许多庞克乐队都会去那里。`},Id_DisplayTextPerState_611:{en:`I find it hard to believe what I'm reading. I would never have imagined Colonel Trooper <char=24> working with Gaiman <char=35> or Sanders <char=23>. Maybe you should check the source-- McVeill <char=36> may have falsified the data.`,zh:`我读著觉得难以置信，无法想像翠普上校<char=24>跟盖曼<char=35>或桑德斯<char=23>同流合污。也许你该求证一下来源——麦威尔<char=36>也许捏造证据。`},Id_DisplayTextPerState_612:{en:`I can't imagine the Colonel being involved in that kind of business, and I don't even see what means of pressure the M Organization <itm=02> could apply against him. `,zh:`无法想像上校参与了这事情，甚至想不到M组织<itm=02>能对他施加什么压力。 `},Id_DisplayTextPerState_613:{en:`MI5, the military, you seem to be the only ones who are not involved! Maybe you should question yourself?`,zh:`国安局和军方都牵涉其中，看来只有你独善其身！你抚心自问有可能吗？`},Id_DisplayTextPerState_614:{en:`Now that you mention it, it's not all that surprising. For such a career military man who lives in the past, the current situation must be unbearable. Then imagine how such a dinosaur feels when asked to serve under a female Prime Minister...`,zh:`你说到重点了，其实这并不意外。这种老派军人不能忍受目前的状况。进一步想一想这种恐龙屈居女性首相下，是何种滋味……`},Id_DisplayTextPerState_615:{en:`Those are serious allegations. After what just happened, we cannot ignore them.`,zh:`这指控非常严重。发生了这种事情，我们不能坐视不理。`},Id_DisplayTextPerState_616:{en:`I was rather willing to trust the Colonel, but what you are showing me here is is overwhelming. You believe we got our man? Make your report if that is the case!`,zh:`我原本相信上校，但你给我看的证据让我动摇了。你相信他就是犯人吗？若是真的，写进报告里！`},Id_DisplayTextPerState_617:{en:`Indeed, I knew that those explosives were missing. I hoped I would resolve this matter within our institution, so the reputation of the Army wouldn't be tarnished. I don't regret that choice. This is not the concern of the Police.`,zh:`我的确知道炸裂物不翼而飞。本来希望可以内部解决，保全军方声望。我不后悔作过的决定，这不是警方需要担心的事。`},Id_DisplayTextPerState_618:{en:`Are you telling me that you just quietly searched through my bag before reading a confidential file? And you are expecting me to answer your questions?
As soon as this case is over, I will have you up on charges.`,zh:`你告诉我曾经偷偷搜过我的袋子，在里面找到机密档案，然后我要回答你的问题？

这案件告一段落之后，你等著接受纪律处分吧。`},Id_DisplayTextPerState_619:{en:`The director won't talk to you.`,zh:`局长不会跟你说话。`},Id_DisplayTextPerState_620:{en:`This shouldn't be in your hands. These are confidential documents, and if they are confirmed after our own investigation, our services will deal with it and we will do what needs to be done.`,zh:`这不应该在你手中，里面是机密档案。要是调查过后核实了个中情节，我们便会有相应行动。`},Id_DisplayTextPerState_621:{en:`I don't understand. That's not the man I know. Of course, as a military man, his worldview can sometimes be a little hard, but he is a patriot and a humanitarian. He always considered me to be equal to my male colleagues.`,zh:`我不懂，这不是我认识的上校。当然作为军方一分子，他的视野也许有点太狭窄，不过他全心爱国，同时是人道主义者，总是把我与男同袍一视同仁。`},Id_DisplayTextPerState_235:{en:`So you're working for MI5 after all? I'm not sure how useful it is to show me this kind of documents.`,zh:`原来你是为国安局工作吗？我不知道你给我看这有什么用。`},Id_DisplayTextPerState_237:{en:`I wouldn't be able to say if your case is becoming simpler or more complicated.`,zh:`我说不准究竟你的案件越来越清晰还是复杂。`},Id_DisplayTextPerState_275:{en:`This discovery is very worrying. I contacted you because I didn't trust MI5, but you are giving me confirmation that there is a link between my agency and the M Organization <itm=02>. @ I wouldn't be surprised if McVeill <char=36> was involved. I could never stand him--he got his position too easily, and I have the feeling he is putting a spoke in my wheels.`,zh:`这件事令人十分担忧。因为我信不过国安局，所以联络你。现在你给了我情报，指出我的部门跟M组织<itm=02>有关联。@就算我知道麦威尔<char=36>牵涉在内也不惊讶，因为打从一开始我就不相信他。他爬升得太容易，而且感觉他处处妨碍我。`},Id_DisplayTextPerState_276:{en:`I need to know what this computer contains in order to help you.`,zh:`我要知道里面装了什么，才帮得到你。`},Id_DisplayTextPerState_332:{en:`If it's broken, I can't repair it.`,zh:`它烂了，我不懂修复。`},Id_DisplayTextPerState_346:{en:`The Duke <char=27> could be the Organization's target? That may well be, the Organization seemed to be interested in him for some odd reason.
Yet his law isn't very likely to pass.`,zh:`公爵<char=27>是组织的目标？也许吧，出于特殊原因，那组织对他有兴趣。

但他的法案很难通过。`},Id_DisplayTextPerState_389:{en:`Just shows how overwhelmed you are. Ultimately, the Duke <char=27> might be onto something--pity his law is so unlikely to pass.`,zh:`看得出你的能耐不高。最终公爵<char=27>可能发现一些重要事情。可惜他的法案应该通过不了。`},Id_DisplayTextPerState_418:{en:`So you believe I truly have been targeted by terrorists? I suppose I shouldn't be surprised. They must all shudder at the thought that my proposed legislation could get through.`,zh:`你相信我是恐怖分子的目标吗？我可不意外。他们得知我提出的法案将要通过，肯定怕得浑身发抖。`},Id_DisplayTextPerState_622:{en:`Wait, are you telling me that you found a file from MI5 that was leaked? This is particularly serious. Your case is taking a very tricky turn.`,zh:`等一下，你说国安局的档案被泄露？此事非同小可，把整件案弄得扑朔迷离。`},Id_DisplayTextPerState_624:{en:`You believe they will come after the Duke? I didn't think his law would scare them that much. In any case, I am concerned that MI5 is not as secure as it should be.`,zh:`你觉得他们的目标是公爵吗？我不认为他的法案真的那么可怕。但是值得担忧的是国安局竟然不可靠。`},Id_DisplayTextPerState_625:{en:`This shouldn't be in your hands. It is particularly worrying, and if there is a leak, I will take care of it personally.`,zh:`你不应该拿到它。此事令人担忧，要是真的泄露机密，我会亲自处理。`},Id_DisplayTextPerState_626:{en:`Mike <char=23> had showed this to me on the computer. He told me he was working for MI5. I found it hard to believe but clearly, he has good contacts.`,zh:`迈克<char=23>让我在电脑看过这档案，告诉我他为国安局工作。虽然我不觉得可信，不过他的后台绝不单纯。`},Id_DisplayTextPerState_627:{en:`This is very worrying. There were rumours that we had a mole, but this is overwhelming evidence. I think we'll have to take a closer look at agent Drake O'Brian <char=49>.`,zh:`令人担忧，因为谣传我们之间有内鬼。现在证据确凿，我要重新审视德雷克·柯布连<char=49>这个人。`},Id_DisplayTextPerState_628:{en:`You think he is that organization's target? That would be a pity. He has much to contribute to our politics, especially for people like me. `,zh:`你觉得他是M组织的目标吗？真可怕，他对政治贡献良多，尤其是对于我这样的人来说。 `},Id_DisplayTextPerState_629:{en:`My computer is always with me, and it is not broken. Thank you for your concern.`,zh:`我总是带著我的电脑，它没有烂，谢谢关心。`},Id_DisplayTextPerState_630:{en:`I've never seen anything like it before. If MI5 is involved, you'll have to be cautious and find someone to overstep their authority.`,zh:`我从没见过这种事情。要是国安局被卷入其中，你务必小心，找一个靠山，权限足以凌驾他们。`},Id_DisplayTextPerState_273:{en:`Have you thought of showing that to Eric?`,zh:`你要给艾力看看吗？`},Id_DisplayTextPerState_274:{en:`With the evidence you've gathered, you decide not to take a chance on Mike Sanders. You rush him, handcuff him, read him his rights and send him to Scotland Yard.`,zh:`根据你找到的证据，你决定不要在迈克·桑德斯一事上冒险。你迅速找到他，戴上手铐，告诉他被捕后的权利，然后把他送到苏格兰场。`},Id_Item_Name_31:{en:`Arrest`,zh:`逮捕`},Id_DisplayTextPerState_505:{en:`If you're planning on doing my head in, I hope you've built an airtight case, because I'm not really going to make it easier for you.`,zh:`要是你打算让我不好过，希望你准备够充足，因为我可不好惹。`},Id_DisplayTextPerState_539:{en:`The ambassador will only be back in London tomorrow.`,zh:`大使明天才回伦敦。`},Id_DisplayTextPerState_553:{en:`Forensics will certainly be able to help you with that.`,zh:`鉴识专家可以帮助你。`},Id_DisplayTextPerState_623:{en:`The blood matches the quantity lost by the Chief Officer.`,zh:`血液符合局长的流失量。`},Id_Item_Name_18:{en:`drake_call`,zh:`德雷克来电`},Id_DisplayText_Default_123:{en:`There is nothing left of the House of Lords. Everything was destroyed.`,zh:`上议院什么也不剩，一切都被毁了。`},Id_LocationState_Introduction_25:{en:`It is difficult to find the right place, but someone who knows the neighborhood will be able to help you.`,zh:`很难找到正确的地方，但熟悉此区的人也许可以帮助你。`},Id_DisplayTextPerState_71:{en:`Whom could you show this to, so you could get some help on it?`,zh:`你应该展示给谁以求帮助呢？`},Id_DisplayTextPerState_247:{en:`Buck has been transferred, you won't be able to question him.`,zh:`伯克被移送了，所以你不能盘问他。`},Id_DisplayTextPerState_631:{en:`The news that you have found the Chief Officer dead is spreading. Internal struggles to determine who will take his place have begun. You're not caught up in that drama, I hope.`,zh:`你发现局长死亡的消息开始流传，内部觊觎其职位的人开始争斗。我希望你不要牵涉其中。`},Id_DisplayTextPerState_632:{en:`Can I help you?`,zh:`有何贵干？`},Id_DisplayTextPerState_633:{en:`This so-called threat, which is supposed to come from the Organization. I don't believe it. Find another lead and stop bothering us.`,zh:`威胁就这样吗，看来是那组织干的。我不想理它。调查其他方向，同时别再烦我。`},Id_DisplayTextPerState_634:{en:`It's an important fair. Some of my agents are taking care of protection, so nothing to worry about on that score.`,zh:`这是一场重要展览。我派了一些特务负责保安，所以不用担心。`},Id_DisplayTextPerState_635:{en:`This is your investigation, but remember that the Chief Officer is one of ours, his son is like family. Don't start making false accusations.`,zh:`谢谢你的调查，但记得局长是自己人，他的儿子就像家人一样。不要随便错误起诉。`},Id_LocationState_Introduction_26:{en:`You arrive in the luxurious Penthouse.\r
The Prince of England <char=29> would like a full debrief on the situation as soon as you are ready.`,zh:`你来到一所豪华的阁楼。

一旦你准备好，便可以向英格兰王子<char=29>讲述整个状况。`},Id_Item_Name_32:{en:`finish`,zh:`完结`},Id_DisplayTextPerState_105:{en:`You think I am a computer technician?`,zh:`你觉得我像电脑技师吗？`},Id_DisplayText_Default_124:{en:`This person may have died in the explosion...`,zh:`这人也许在爆炸中丧生了……`},Id_Ending_Question_0:{en:`Who made the bomb?`,zh:`谁制造炸弹？`},Id_DisplayTextPerState_636:{en:`There is plenty of ammunition on the black market. Who knows where this box may come from?`,zh:`黑市里有充足弹药供应。谁会知道来自哪里？`},Id_DisplayTextPerState_637:{en:`You've got friends in high places to twist my arm and make me come to see you.
You didn't help me when my daughter <char=14> was in danger, I don't see why I would help you now.`,zh:`你有位高权重的朋友强迫我来见你。

我女儿<char=14>身处险境时你没有帮忙，我看不出为什么现在要帮助你。`},Id_DisplayTextPerState_638:{en:`A formidable politician. Without a doubt, she has been the most influential French ambassador to England in recent years. She even managed to get France to finance the floral decoration of the House of Lords.`,zh:`可怕的政治家。她无疑是多年来英国里最举足轻重的法国大使。她甚至可以说服法国政府赞助花卉装饰给上议院。`},Id_DisplayTextPerState_639:{en:`Louise Blanche <char=15>, the French ambassador, got connected to them after her daughter <char=14> had a transplant. I'm the one who informed them that Buck <char=44> had kidnapped her, and they were interested in getting her back. @ I know she had returned to France. She is only coming back tomorrow, but maybe she knows something. I will engage the necessary pressure so you can question her.`,zh:`自从她的女儿接受心脏移植手术以后，法国大使露易蕬·布兰奇<char=15>跟那组织便有联系。就是我告知他们伯克<char=44>绑架了她女儿，而M组织打算夺回她。@我知道她去了法国，明天才回来。也许她知道一些事情。我会向她施加压力，让你得以盘问她。`},Id_Ending_FinalSummary_4:{en:`It's a pity, detectives, you arrived too late. Terrorists have won today, instilling fear among Londoners and throughout the United Kingdom. @ In spite of the losses you caused, the M Organization ends up stronger. Their influence is growing, in England and around the whole world!`,zh:`真可惜，你们太迟了。这是恐怖分子胜利的一天，在伦敦以至全英国植入了恐惧。@你未能阻止这么多伤亡，而M组织的影响力日复一日地增强，笼罩整个英国乃至全世界！`},Id_DisplayText_Action_15:{en:`The Prince <char=29> summons you to Greenwich. He would like to get to the bottom of the story.`,zh:`王子<char=29>把你唤到格林威治，希望穷究来龙去脉。`},Id_Item_Name_33:{en:`The Duke's paper`,zh:`公爵的文件`},Id_DisplayTextPerState_640:{en:`You find the Duke's presentation in defense of his anti-terrorist law.`,zh:`你发现公爵为他的反恐法案辩护。`},Id_DisplayTextPerState_641:{en:`Wow, over 10,000 points on Fruit Ninja. That lord is a master of the game. I wonder if he is as good with the game's tabletop version.`,zh:`哇，水果忍者超过一万分。这名贵族一定是游戏高手。不晓得他玩桌游版是否也同样厉害。`},Id_DisplayTextPerState_642:{en:`This speech is not on the Internet.`,zh:`网上没有这段演讲。`},Id_DisplayTextPerState_643:{en:`This speech is not on the Internet, but ever since the bomb went off, the Duke and his ideas have also exploded in popularity.`,zh:`网上没有这段演讲，但自从炸弹爆炸，公爵的思想如燎原之火，一发不可收拾。`},Id_DisplayTextPerState_644:{en:`This speech is not on the Internet, but since you defused the bomb, the Duke and his ideas have exploded in popularity.`,zh:`网上没有这段演讲，但自从你拆掉炸弹，公爵的思想如燎原之火，一发不可收拾。`},Id_DisplayTextPerState_645:{en:`Those boxes of ammunition come from the British Army. I can confirm that.`,zh:`我肯定这弹药箱来自英国陆军。`},Id_DisplayTextPerState_646:{en:`Those boxes come from the British Army, easily identified thanks to this emblem.`,zh:`这弹药箱来自英国陆军，看到这徽章很容易辨认。`},Id_DisplayTextPerState_647:{en:`To me, it's just a typical political speech.`,zh:`对我来说，只是平常的政治演讲。`},Id_DisplayTextPerState_648:{en:`I believe Mike <char=23> nicked it from the army.`,zh:`我相信是迈克<char=23>从军队偷来的。`},Id_DisplayTextPerState_649:{en:`Yes, the bullet I extracted comes from this box of ammunition. And I think the box comes from the British Army.`,zh:`对，我取出的那枚子弹来自这箱弹药，而我认为整箱来自英国陆军。`},Id_DisplayTextPerState_650:{en:`Using threats is a typical bullying technique. The secrecy surrounding the organization gets the target's imagination going about what might happen to them. It is usually quite effective.`,zh:`典型的恐吓伎俩。M组织不著痕迹，让目标疑神疑鬼，不晓得会遭遇什么，实际上很有效。`},Id_DisplayTextPerState_651:{en:`A brilliant speech. The notes are very thorough, especially at the beginning. But the end is very weak.`,zh:`非常精彩的演讲，尤其是开始的部分，注脚精辟，但结尾十分薄弱。`},Id_DisplayTextPerState_652:{en:`The fingerprints confirm that the document belongs to the Duke <char=27>.`,zh:`指纹证实这些文件属于公爵<char=27>。`},Id_DisplayTextPerState_653:{en:`Well, these are my notes, nothing of interest to you. I hope you will listen to my speech when it's broadcast on television.`,zh:`对，这些是我的手稿，与你无关。我希望你会聆听我在电视广播的演讲。`},Id_DisplayTextPerState_654:{en:`Ethically, I cannot look at the notes of a political adversary.
<i> Still, she takes a quick look </i> 
But I find it strange that he didn't work more on his conclusion.`,zh:`看政敌的手稿是不道德的。

<i>首相依然快速翻阅。</i>

我觉得他结尾草率得很奇怪。`},Id_DisplayTextPerState_655:{en:`The Duke is a smart man. I don't think lack of time is what made him skip the end of his speech.`,zh:`公爵非常精明，我不认为他会因为时间不足而跳过演讲的结尾。`},Id_DisplayTextPerState_656:{en:`After people put some of their threats into action, all their threats tend to be taken seriously.`,zh:`一旦恐吓者把恐吓付诸行动，人们就会相信对方所说的威胁。`},Id_DisplayTextPerState_657:{en:`Money is at the heart of politics nowadays, you know.`,zh:`你知道当今政治，钱能通神。`},Id_DisplayTextPerState_658:{en:`This is a box of ammunition that comes from our army, as you certainly know. It is worrying to know that the stock is not as secure as it should be. I will be sure to have a word with Colonel Trooper <char=24> about it.`,zh:`这是陆军的弹药箱，你也看得出来这些东西并没有安全储存在应该在的地方，使我有点忧心。我会跟翠普上校<char=24>说一下。`},Id_DisplayTextPerState_659:{en:`You are right, it is a box from the army.
I thought I could resolve the matter without involving any civilians. A few boxes of ammunition and explosives have been stolen. I suspect Mike Sanders <char=23> but I have no proof.`,zh:`对，这箱来自陆军。

我原以为不用牵涉平民就能解决这事件。几箱弹药和炸药被盗，我怀疑是迈克·桑德斯<char=23>干的，但苦无证据。`},Id_DisplayTextPerState_660:{en:`Thank you for making the connection between Sanders <char=23> and the theft. You have my blessing to put him behind bars.`,zh:`谢谢你找到桑德斯<char=23>与窃案的关联，感激你帮我把他关进监狱。`},Id_DisplayTextPerState_661:{en:`Obviously the Duke took some notes for his speech, nothing unusual there.`,zh:`很明显，公爵为演讲写下一些手稿，不值得大惊小怪。`},Id_DisplayTextPerState_662:{en:`Thank you for the information. One of my men will be there, obviously. Let me deal with it.`,zh:`谢谢你的资讯，我会派人去，让我处理。`},Id_DisplayTextPerState_663:{en:`Mike <char=23> said roughly the same crappy things as what's written in your papers there.
`,zh:`迈克<char=23>说的疯话，跟这张纸上的大致一样。
`},Id_DisplayTextPerState_664:{en:`I have no comments to make on politics.`,zh:`我对政治没意见。`},Id_DisplayTextPerState_665:{en:`A good speech, well-rounded.`,zh:`不错的演讲，有始有终。`},Id_DisplayTextPerState_666:{en:`It could have been worse, I guess.`,zh:`我猜这已不是最糟的结果。`},Id_DisplayTextPerState_667:{en:`I heard that some ammunition was stolen--the Colonel was actually on a witch hunt over it.`,zh:`听说一些弹药被盗，上校正在抓捕内鬼。`},Id_DisplayTextPerState_668:{en:`Some of my friends and I do indeed have a secret meeting with the Prime Minister a bit later today. But apparently you don't know the secret word.`,zh:`在今天晚一点的时候，我的确约了首相跟我和某些朋友会面，但看来你不知道秘密的内容。`},Id_DisplayTextPerState_669:{en:`I'm not sure... But digging into this looks important to me.`,zh:`我不确定这是……但我似乎有必要追查此事。`},Id_DisplayText_Default_125:{en:`There's nothing to collect here.`,zh:`这里没东西需要拿走。`},Id_DisplayText_Default_126:{en:`There's nothing to collect here.`,zh:`这里没东西需要拿走。`},Id_DisplayText_Default_127:{en:`There's nothing to collect here.`,zh:`这里没东西需要拿走。`},Id_DisplayText_Default_128:{en:`There's nothing to collect here.`,zh:`这里没东西需要拿走。`},Id_DisplayTextPerState_670:{en:`A huge financial fair will take place on Saturday in the City <loc=B>, and the greatest bankers from Great Britain and around the world will be there.`,zh:`星期六在市中心<loc=B>会举行一场大型财经展览的开幕仪式，英国乃至全球的大银行家都会聚集。`},Id_DisplayTextPerState_671:{en:`On Saturday, the Duke is going to present an important legislative proposal to Parliament in Westminster <loc=A>.`,zh:`星期六，公爵将会在西敏的国会大楼<loc=A>提出他的重要法案。`},Id_LocationState_Introduction_27:{en:`At this time of the day, the barracks do not accept visitors anymore. If you don't have a warrant, you will have to come back tomorrow.`,zh:`到了这时候，军营不会接待访客。如果你没有通行证，只好明天再来。`},Id_LocationState_Introduction_28:{en:`You made quite an impression when you neutralized Mike Sanders <char=23>. The soldiers let you go into the barracks.`,zh:`你指证迈克·桑德斯<char=23>的时候，让人留下深刻印象。士兵准许你进入军营。`},Id_DisplayText_Default_129:{en:`There is no one corresponding to this description here.`,zh:`这里没有人符合你的描述。`},Id_DisplayTextPerState_672:{en:`Well done. I am glad I trusted you.`,zh:`做得好，真庆幸我相信了你。`},Id_DisplayTextPerState_673:{en:`The session is important today. Hurry up and tell me what I can do for you.`,zh:`今天这节会议十分重要。快说，我看看能帮你什么。`},Id_DisplayTextPerState_674:{en:`I didn't think that this organization would strike at the very heart of our nation. Clearly we underestimated them.`,zh:`我以为这组织不会袭击这国家的核心。看来我们小看它了。`},Id_DisplayTextPerState_675:{en:`This is exactly what I was talking about! A bomb in Parliament! We are not safe anywhere, and we must take drastic measures!`,zh:`这正是我所说的！国会里的炸弹！我们连在那里都不安全，必须以非常手段应对！`},Id_DisplayTextPerState_676:{en:`With my engagement ceremony in the works, I have little time to offer. But this case is worrying, so how can I help you?`,zh:`我的订婚典礼如火如荼，没多少时间可以给你。不过这件事的确令人担忧，我能怎样帮你？`},Id_DisplayTextPerState_677:{en:`I'm doing what I can to try and get you an appointment with the French ambassador <char=15>, as I'm sure she could help you. But maybe you need something else?`,zh:`我尝试为你约见法国大使<char=15>，因为她帮得上忙。你还需要什么吗？`},Id_DisplayTextPerState_678:{en:`That was a prominent member of the M Organization <itm=02>, and there's so much he could have revealed. Maybe he even knew the name of their leader. @He was found dead shortly after you dismantled his scheme. It was bound to happen, I guess.`,zh:`M组织<itm=02>的重要成员。原本他可以吐露很多事情，甚至知道首领的名字。@你揭露他的犯罪模式后不久，他就在苏格兰场里死亡。我猜这是注定的。`},Id_LocationState_Introduction_29:{en:`The Murphy's is currently closed. Maybe you should look somewhere else.`,zh:`墨菲酒吧关门了，也许你得到别处。`},Id_LocationState_Introduction_30:{en:`You are late for the debriefing meetings, which come one after another. No matter how hard you try to explain that there are other priorities, nothing seems to work and you have to stay until it's too late to continue with the investigation.`,zh:`你迟到了一个接一个的报告会议。无论你如何努力解释有多少紧急事情要处理，看来也徒劳无功。你必须留在这里，不然没办法继续调查。`},Id_Location_Name_8:{en:`Murphy's`,zh:`墨菲酒吧`},Id_DisplayTextPerState_680:{en:`The embassy promises to deliver the message that you wish to talk to her. She will let you know directly as soon as she can meet you.`,zh:`领事馆会帮你向大使传递消息说你要见她，当她能跟你见面，便会直接告诉你。`},Id_DisplayTextPerState_681:{en:`The embassy is closed today. The ambassador is at the Prince's engagement ceremony.`,zh:`今天领事馆关门了。大使参与了王子的订婚典礼。`},Id_DisplayTextPerState_682:{en:`This is rather bad timing. What do you want?`,zh:`现在是坏时机。你要做什么？`},Id_DisplayText_Action_16:{en:`The French ambassador <char=15> answered MI5 request for her to come at Sctoland <home> for interrogation. She  just arrived to answer your questions. She seems upset about being summoned like that and she won't be staying long.`,zh:`法国大使<char=15>答应了国安局，来到苏格兰场<起始地点>接受盘问。@她刚刚来到，准备回答你的问题。由于不满被唤来，她只会逗留很短时间。`},Id_DisplayTextPerState_234:{en:`Thankfully I had to be away a few minutes before the explosive went off in Parliament, or else I would be dead.
But that's exactly what I was talking about! We are not safe anywhere, we need to take drastic measures to secure out country! `,zh:`庆幸我在爆炸前几分钟离开了国会大楼，不然性命难保。

这正是我所说的！国会里的炸弹！我们连在那里都不安全，必须以非常手段应对！ " `},Id_DisplayTextPerState_236:{en:`I barely know him, but he operates among the highest levels of power.`,zh:`我只是约略知道他，但他通常跟更高级的人合作。`},Id_DisplayTextPerState_253:{en:`I'm suspecting something unusual with him, but I don't know what exactly.`,zh:`我怀疑他很不寻常，但说不出个缘由。`},Id_DisplayTextPerState_362:{en:`He's a good inspector. Some say he has ambitions to take a higher position of leadership.`,zh:`他是有能的探员，有些人说他雄心壮志，要登上更高的领导地位。`},Id_Ending_Question_1:{en:`Who killed the Chief Officer Doyle <char=33>?`,zh:`谁杀死戴尔局长<char=33>？`},Id_Ending_Question_4:{en:`What's the location of Kevin Doyle's <char=47> hideout ?`,zh:`凯文·戴尔<char=47>的藏身地在哪里？`},Id_ScoreScreen_CheckObjectState_0:{en:`Was the bomb disarmed?`,zh:`有没有拆除炸弹？`},Id_LocationState_Introduction_31:{en:`Everyone is impressed that you disarmed the bomb. The Duke of Windsor <char=27>, Conor McVeill <char=36>, and the Prime Minister <char=21> are all here speaking about what happened.`,zh:`你拆除炸弹，让全部人惊叹。温莎公爵<char=27>、科拿·麦威尔<char=36>与首相<char=21>全都在谈论刚刚发生的事。`},Id_DisplayText_Action_17:{en:`The police force has been informed about the death of Chief Officer Doyle <char=33>`,zh:`警方获报得知戴尔局长<char=33>的死讯。`},Id_DisplayTextPerState_457:{en:`I don't know where he is. Did you find him?`,zh:`不知道他在哪，你找过了吗？`},Id_DisplayTextPerState_679:{en:`There's enough material here to create a bomb, but the actual bomb isn't present... Where could it be?`,zh:`这里有足够材料制造炸弹，但是到处都找不到成品……究竟在哪里？`}};export{e as t};